export default [{"id":"90-90-hold","name":"90/90 Hold","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors"],"steps":["Sit on the floor and bend your front leg in front of you so your shin runs across your body and your knee is bent to about 90 degrees.","Place your back leg out to the side with that knee also bent to about 90 degrees, shin pointing back.","Put your hands on the floor beside your hips for support.","Sit up tall, with your chest lifted and both sitting bones as close to the floor as you can manage.","Hold the position, breathing slowly, feeling the stretch in the outer hip of the front leg and the front of the hip of the back leg.","Hold for the planned time, then switch the legs and hold on the other side."],"images":{"main":"images/flat/90-90-hold-main.webp"}},{"id":"90-90-switch","name":"90/90 Switch","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors"],"steps":["Sit on the floor with the front knee bent at 90 degrees and the back knee bent at 90 degrees, and place your hands behind you for support.","Sit tall and keep your trunk upright.","Lift both knees slightly and rotate your legs to the other side in a controlled movement, so that the front leg becomes the back leg.","Settle into the 90/90 position on the new side, using your hands for balance.","Switch back to the first side, and repeat for the planned repetitions.","Keep the movement slow and smooth, without forcing the hips."],"images":{"start":"images/flat/90-90-switch-start.webp","peak":"images/flat/90-90-switch-peak.webp"}},{"id":"ab-wheel-rollout","name":"Ab Wheel Rollout","bodyPart":"core","category":"strength","equipment":"ab_wheel","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Kneel on the floor and grip the ab wheel handles shoulder-width.","Brace the core hard so the lower back stays neutral.","Roll the wheel slowly forward, extending the body as far as you can control.","Stop before the hips sag or the back arches.","Pull the wheel back to the knees by contracting the abs."],"images":{"start":"images/flat/ab-wheel-rollout-start.webp","peak":"images/flat/ab-wheel-rollout-peak.webp"}},{"id":"air-bike","name":"Air Bike","bodyPart":"full_body","category":"cardio","equipment":"air_bike","muscles":["hamstrings","quadriceps"],"steps":["Sit on the air bike and grip the moving handles.","Place your feet on the pedals and brace your core.","Push and pull the handles while pedaling at a steady pace.","Drive with both arms and legs to maintain power output.","Continue for the desired duration or distance."],"images":{"main":"images/flat/air-bike-main.webp"}},{"id":"archer-pull-ups","name":"Archer Pull Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Grip the bar wider than shoulder width with palms facing away.","Pull yourself up while shifting your body toward one hand.","Keep the opposite arm straight as a support.","Lower yourself under control back to the hang.","Alternate sides each rep or complete reps on one side first."],"images":{"start":"images/flat/archer-pull-ups-start.webp","peak":"images/flat/archer-pull-ups-peak.webp"}},{"id":"archer-push-ups","name":"Archer Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Set up in a wide push-up position with arms straight.","Lower yourself toward one hand while keeping the other arm straight.","Keep your core tight and body in a straight line.","Press back up to the start position.","Alternate sides each rep for the desired number of reps."],"images":{"start":"images/flat/archer-push-ups-start.webp","peak":"images/flat/archer-push-ups-peak.webp"}},{"id":"arnold-press","name":"Arnold Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Hold a pair of dumbbells at shoulder height with palms facing you.","Press the dumbbells overhead while rotating your palms to face forward.","Fully extend your arms at the top without locking the elbows.","Reverse the motion and rotate back to the start.","Repeat for the desired number of reps."],"images":{"start":"images/flat/arnold-press-start.webp","peak":"images/flat/arnold-press-peak.webp"}},{"id":"assisted-dips","name":"Machine Assisted Dips","bodyPart":"upper_arms","category":"strength","equipment":"dip_machine","muscles":["pectoralis_major","triceps_brachii"],"steps":["Step onto the assisted dip machine with knees on the pad.","Grip the parallel bars and support your weight with straight arms.","Lower your body by bending your elbows until shoulders are below elbows.","Press back up to the start position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/assisted-dips-start.webp","peak":"images/flat/assisted-dips-peak.webp"}},{"id":"assisted-pull-ups","name":"Assisted Pull Ups","bodyPart":"back","category":"strength","equipment":"assisted_pullup_machine","muscles":["latissimus_dorsi"],"steps":["Place your knees on the assisted pull-up machine pad.","Grip the bar with palms facing away, slightly wider than shoulders.","Pull your chest toward the bar by driving your elbows down.","Lower yourself under control to a full hang.","Repeat for the desired number of reps."],"images":{"start":"images/flat/assisted-pull-ups-start.webp","peak":"images/flat/assisted-pull-ups-peak.webp"}},{"id":"back-extension","name":"Back Extension","bodyPart":"back","category":"strength","muscles":["erector_spinae"],"steps":["Lie face down on a hyperextension bench with hips at the pad edge.","Lower your upper body toward the floor.","Raise your torso back up until your body is straight.","Repeat."],"images":{"start":"images/flat/back-extension-start.webp","peak":"images/flat/back-extension-peak.webp"}},{"id":"back-lever","name":"Back Lever","bodyPart":"full_body","category":"strength","equipment":"pull_up_bar","muscles":["erector_spinae","latissimus_dorsi"],"steps":["Hang from a bar with an overhand grip and rotate backward through the arms until inverted.","Lower the body forward and down until it is horizontal, facing the floor.","Keep the arms straight and the whole body in one rigid line from head to heels.","Brace the core and squeeze the glutes so the hips and shoulders do not sag.","Hold for time, then rotate back up under control."],"images":{"main":"images/flat/back-lever-main.webp"}},{"id":"balance-dome-crunch","name":"Balance Dome Crunch","bodyPart":"core","category":"strength","equipment":"bosu_ball","muscles":["rectus_abdominis"],"steps":["Place the balance dome on the floor with the domed side up and sit on it, then lie back so your lower back rests on the dome.","Bend your knees and place your feet flat on the floor, about hip-width apart.","Put your hands behind your head with your elbows wide, without pulling on your neck.","Curl your shoulders and upper back up toward your hips by shortening the distance between your ribs and your pelvis.","Pause briefly at the top and keep your lower back on the dome.","Lower back slowly to the start and repeat for the planned repetitions."],"images":{"start":"images/flat/balance-dome-crunch-start.webp","peak":"images/flat/balance-dome-crunch-peak.webp"}},{"id":"balance-dome-glute-bridge","name":"Balance Dome Glute Bridge","bodyPart":"upper_legs","category":"strength","equipment":"bosu_ball","muscles":["gluteus_maximus"],"steps":["Lie on your back on the floor with your knees bent and place both feet on the top of a balance dome with the domed side up.","Rest your arms flat on the floor beside you with your palms down.","Brace your trunk and press through your feet to lift your hips off the floor.","Raise your hips until your body forms a straight line from your shoulders to your knees.","Squeeze your glutes at the top and keep your hips level while the dome moves under your feet.","Lower your hips slowly to the floor and repeat for the planned repetitions."],"images":{"start":"images/flat/balance-dome-glute-bridge-start.webp","peak":"images/flat/balance-dome-glute-bridge-peak.webp"}},{"id":"balance-dome-plank","name":"Balance Dome Plank","bodyPart":"core","category":"strength","equipment":"bosu_ball","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Place the balance dome on a flat floor with the domed side up and kneel behind it.","Put your forearms on the dome with your elbows under your shoulders.","Step your feet back into a plank with your body in a straight line from head to heels.","Squeeze your glutes and brace your abdominals, keeping your neck long.","Hold the position for the planned time while the dome moves under you.","Lower your knees to the floor to finish."],"images":{"main":"images/flat/balance-dome-plank-main.webp"}},{"id":"balance-dome-push-up","name":"Balance Dome Push-Up","bodyPart":"chest","category":"strength","equipment":"bosu_ball","muscles":["pectoralis_major","triceps_brachii"],"steps":["Turn the balance dome over so that its flat platform faces up, and place your hands on the platform at about shoulder-width.","Step your feet back into a high plank with your body in a straight line from head to heels.","Brace your trunk and lower your chest toward the platform by bending your elbows.","Lower until your chest is just above the platform, keeping your elbows about 45 degrees from your body.","Press the platform away to straighten your arms, keeping the dome as level as you can.","Repeat for the planned repetitions."],"images":{"start":"images/flat/balance-dome-push-up-start.webp","peak":"images/flat/balance-dome-push-up-peak.webp"}},{"id":"balance-dome-single-leg-stand","name":"Balance Dome Single-Leg Stand","bodyPart":"lower_legs","category":"strength","equipment":"bosu_ball","muscles":["gastrocnemius","soleus"],"steps":["Place the balance dome on a flat floor with the domed side up, next to a wall or a sturdy support.","Step onto the middle of the dome with one foot and stand tall with your knee slightly bent.","Shift your weight onto that leg and lift the other knee in front of you until the thigh is about hip height.","Keep your hips level, your chest tall and your eyes on a fixed point ahead.","Hold for the planned time, letting your ankle and calf make small corrections.","Lower the foot, rest and repeat on the other leg."],"images":{"main":"images/flat/balance-dome-single-leg-stand-main.webp"}},{"id":"balance-dome-squat","name":"Balance Dome Squat","bodyPart":"upper_legs","category":"strength","equipment":"bosu_ball","muscles":["gluteus_maximus","quadriceps"],"steps":["Place the balance dome on a flat floor with the domed side up and step onto the middle of it with both feet, about hip-width apart.","Find your balance and reach your arms straight out in front of you.","Push your hips back and bend your knees, lowering until your thighs are close to parallel with the floor.","Keep your chest up and your knees in line with your toes.","Press through your whole foot to stand back up.","Repeat for the planned repetitions and step off one foot at a time."],"images":{"start":"images/flat/balance-dome-squat-start.webp","peak":"images/flat/balance-dome-squat-peak.webp"}},{"id":"balance-dome-squat-hold","name":"Balance Dome Squat Hold","bodyPart":"upper_legs","category":"strength","equipment":"bosu_ball","muscles":["gluteus_maximus","quadriceps"],"steps":["Place the balance dome on a flat floor with the domed side up and step onto the middle of it with both feet, about hip-width apart.","Stand tall and find your balance before you start to squat.","Push your hips back and bend your knees until your thighs are close to parallel with the floor.","Reach your arms straight out in front of you to counterbalance and keep your chest up.","Hold the position for the planned time, keeping your knees in line with your toes.","Stand up slowly and step off one foot at a time."],"images":{"main":"images/flat/balance-dome-squat-hold-main.webp"}},{"id":"balance-dome-stand","name":"Balance Dome Stand","bodyPart":"lower_legs","category":"strength","equipment":"bosu_ball","muscles":["gastrocnemius","soleus"],"steps":["Place the balance dome on a flat floor with the domed side up and stand next to it.","Step onto the middle of the dome with one foot, then bring the other foot up beside it, about hip-width apart.","Stand tall with your arms relaxed at your sides and your knees slightly bent.","Keep your weight even across both feet and look at a point straight ahead.","Hold the position for the planned time, letting your ankles and calves make small corrections.","Step off one foot at a time to finish."],"images":{"main":"images/flat/balance-dome-stand-main.webp"}},{"id":"balance-dome-step-up","name":"Balance Dome Step-Up","bodyPart":"upper_legs","category":"strength","equipment":"bosu_ball","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing the balance dome, placed domed side up on a flat floor.","Place one foot flat in the middle of the dome.","Press through the whole foot and straighten that leg to stand up on the dome, bringing your other foot beside it.","Stand tall for a moment and keep your weight centred over the dome.","Step back down with the other foot first, then the working foot.","Complete the planned repetitions on one leg, then switch legs."],"images":{"start":"images/flat/balance-dome-step-up-start.webp","peak":"images/flat/balance-dome-step-up-peak.webp"}},{"id":"ball-leg-curl","name":"Stability Ball Leg Curl","bodyPart":"upper_legs","category":"strength","equipment":"stability_ball","muscles":["hamstrings"],"steps":["Lie face-up on the floor with your heels and lower calves on top of a stability ball, arms out for balance.","Press through the heels to raise your hips into a straight line from shoulders to ankles.","Keeping the hips up, bend the knees to roll the ball toward your glutes.","Extend the legs back out under control without dropping the hips.","Complete all reps, then lower the hips and step off the ball."],"images":{"start":"images/flat/ball-leg-curl-start.webp","peak":"images/flat/ball-leg-curl-peak.webp"}},{"id":"ball-pike","name":"Ball Pike","bodyPart":"core","category":"strength","equipment":"stability_ball","muscles":["obliques","rectus_abdominis"],"steps":["Place the shins on a stability ball and hands on the floor in a high plank.","Brace the core and keep the legs straight.","Pike the hips up, rolling the ball toward the chest as the body forms an inverted V.","Pause briefly at the top.","Roll the ball back out to the starting plank."],"images":{"start":"images/flat/ball-pike-start.webp","peak":"images/flat/ball-pike-peak.webp"}},{"id":"band-assisted-pull-ups","name":"Band Assisted Pull Ups","bodyPart":"back","category":"strength","equipment":"resistance_band","muscles":["latissimus_dorsi"],"steps":["Loop a resistance band over the pull-up bar and step one foot into it.","Grip the bar with palms facing away, shoulder-width apart.","Pull your chest toward the bar by driving your elbows down.","Lower yourself under control to a full hang.","Repeat for the desired number of reps."],"images":{"start":"images/flat/band-assisted-pull-ups-start.webp","peak":"images/flat/band-assisted-pull-ups-peak.webp"}},{"id":"band-pull-apart","name":"Band Pull Apart","bodyPart":"shoulders","category":"strength","equipment":"resistance_band","muscles":["posterior_deltoid"],"steps":["Stand holding a light resistance band with both hands, arms extended straight in front at shoulder height.","Hands start shoulder-width apart, palms facing down.","Keeping arms straight, pull the band apart by driving the hands out to the sides.","Finish with the band touching your chest and the shoulder blades squeezed together.","Return slowly to the starting position and repeat."],"images":{"start":"images/flat/band-pull-apart-start.webp","peak":"images/flat/band-pull-apart-peak.webp"}},{"id":"band-pull-through","name":"Band Pull-Through","bodyPart":"upper_legs","category":"strength","equipment":"resistance_band","muscles":["gluteus_maximus","hamstrings"],"steps":["Anchor a resistance band at floor level and stand facing away from it, with the band passing between your legs and its free end held in both hands.","Step forward until the band is under tension and set your feet about shoulder-width apart with your knees slightly bent.","Push your hips back and hinge forward at the hips with a flat back, letting your hands travel down between your legs.","Drive your hips forward and squeeze your glutes to stand tall, bringing your hands up in front of your hips.","Pause with your body in one line, without leaning back, and then hinge down again under control.","Complete the planned repetitions."],"images":{"start":"images/flat/band-pull-through-start.webp","peak":"images/flat/band-pull-through-peak.webp"}},{"id":"band-shoulder-external-rotation","name":"Band Shoulder External Rotation","bodyPart":"shoulders","category":"strength","equipment":"resistance_band","muscles":["infraspinatus_teres_minor"],"steps":["Anchor a resistance band at about elbow height and stand sideways to it, so that the arm you are training is on the side away from the anchor.","Hold the band in that hand, bend your elbow to 90 degrees and tuck it against your side; a small folded towel between elbow and ribs helps keep it there.","Start with your forearm pointing across your stomach and the band under light tension.","Rotate your forearm outward, away from your body and the anchor, keeping your elbow fixed at your side and your wrist straight.","Pause when your forearm points slightly outward, without leaning or twisting your trunk.","Return slowly to the start against the band, repeat for the planned repetitions, and then switch arms."],"images":{"start":"images/flat/band-shoulder-external-rotation-start.webp","peak":"images/flat/band-shoulder-external-rotation-peak.webp"}},{"id":"banded-adductor-stretch","name":"Banded Adductor Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"resistance_band","muscles":["adductors"],"steps":["Lie on your back with a band looped around one foot.","Raise that leg and let it open out to the side.","Hold the band to control how far the leg lowers.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-adductor-stretch-main.webp"}},{"id":"banded-ankle-stretch","name":"Banded Ankle Stretch","bodyPart":"lower_legs","category":"stretching","equipment":"resistance_band","muscles":["gastrocnemius"],"steps":["Sit with one leg extended and a band around the forefoot.","Hold the band in both hands.","Pull so the toes draw back toward your shin.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-ankle-stretch-main.webp"}},{"id":"banded-calf-stretch","name":"Banded Calf Stretch","bodyPart":"lower_legs","category":"stretching","equipment":"resistance_band","muscles":["gastrocnemius"],"steps":["Lie on your back and loop a band around the ball of one foot.","Raise the leg and keep it fairly straight.","Pull the band so your toes draw back toward your shin.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-calf-stretch-main.webp"}},{"id":"banded-chest-stretch","name":"Banded Chest Stretch","bodyPart":"chest","category":"stretching","equipment":"resistance_band","muscles":["pectoralis_major"],"steps":["Hold a band behind your back with both hands.","Straighten your arms and draw them apart.","Lift your chest and squeeze your shoulder blades.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/banded-chest-stretch-main.webp"}},{"id":"banded-clamshell","name":"Banded Clamshell","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_medius"],"steps":["Lie on your side with hips and knees bent to roughly 45 degrees, feet stacked.","Place a loop band around both legs above the knees.","Keep the feet pressed together and the pelvis stable — do not roll back as you move.","Open the top knee upward against the band, like a clamshell opening, until you feel the glute fire.","Pause briefly at the top, then lower under control to the start.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/banded-clamshell-start.webp","peak":"images/flat/banded-clamshell-peak.webp"}},{"id":"banded-figure-4-stretch","name":"Banded Figure-4 Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"resistance_band","muscles":["gluteus_maximus"],"steps":["Lie on your back and cross one ankle over the opposite thigh.","Loop a band around the supporting thigh.","Pull both legs toward your chest with the band.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-figure-4-stretch-main.webp"}},{"id":"banded-fire-hydrant","name":"Banded Fire Hydrant","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_medius"],"steps":["Place a loop band just above your knees and assume a quadruped position with hands under shoulders and knees under hips.","Keep your core engaged and back flat, maintaining a neutral spine throughout the movement.","Slowly lift one knee out to the side, keeping the knee bent at 90 degrees, until your thigh is parallel to the floor.","Hold briefly at the top, squeezing your glute, then slowly lower your leg back to the starting position with control.","Complete all repetitions on one side before switching to the other side."],"images":{"start":"images/flat/banded-fire-hydrant-start.webp","peak":"images/flat/banded-fire-hydrant-peak.webp"}},{"id":"banded-glute-bridge","name":"Banded Glute Bridge","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus"],"steps":["Lie on your back with the knees bent and feet flat on the floor, shoulder-width apart.","Place a loop band around both legs just above the knees.","Press the lower back into the floor and brace the core.","Drive through the heels and squeeze the glutes to lift the hips into a bridge — keep the band tension by pushing the knees outward.","At the top, the body forms a straight line from shoulders to knees. Pause briefly.","Lower under control to the start and repeat for the recommended number of repetitions."],"images":{"start":"images/flat/banded-glute-bridge-start.webp","peak":"images/flat/banded-glute-bridge-peak.webp"}},{"id":"banded-good-morning","name":"Banded Good Morning","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on a loop band with both feet and pass it over the back of your neck.","Set feet hip-width with a soft bend in the knees.","Hinge at the hips, pushing them back with a flat back.","Lower until you feel a stretch in the hamstrings.","Drive the hips forward to return to standing."],"images":{"start":"images/flat/banded-good-morning-start.webp","peak":"images/flat/banded-good-morning-peak.webp"}},{"id":"banded-hamstring-stretch","name":"Banded Hamstring Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"resistance_band","muscles":["hamstrings"],"steps":["Lie on your back and loop a band around one foot.","Raise that leg straight up, holding the band in both hands.","Gently pull the band to draw the leg toward you.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-hamstring-stretch-main.webp"}},{"id":"banded-hip-thrust","name":"Banded Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus"],"steps":["Place a loop band just above your knees and sit on the floor with your upper back against a bench.","Bend your knees, plant your feet hip-width apart, and position the band to create tension.","Drive through your heels, extend your hips, and lift your glutes off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes forcefully at the top, ensuring your knees are pushed out against the band.","Slowly lower your hips back to the starting position with control."],"images":{"start":"images/flat/banded-hip-thrust-start.webp","peak":"images/flat/banded-hip-thrust-peak.webp"}},{"id":"banded-it-band-stretch","name":"Banded IT-Band Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"resistance_band","muscles":["abductors"],"steps":["Lie on your back with a band around one raised foot.","Hold the band with the opposite hand.","Draw the straight leg across your body toward the floor.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-it-band-stretch-main.webp"}},{"id":"banded-kneeling-hip-thrust","name":"Banded Kneeling Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus"],"steps":["Anchor a band low on a sturdy post, at the height of your hips when kneeling, and loop it around your hips. Kneel facing away from the post, torso upright and knees hip-width apart, far enough forward that the band is taut.","Sit your hips back toward your heels, leaning slightly forward with your back straight and core braced.","Initiate the movement by squeezing your glutes, driving your hips forward until your torso is upright.","Squeeze your glutes hard at the top, maintaining tension on the band.","Slowly reverse the movement, controlling the band's resistance as you return to the starting position."],"images":{"start":"images/flat/banded-kneeling-hip-thrust-start.webp","peak":"images/flat/banded-kneeling-hip-thrust-peak.webp"}},{"id":"banded-lat-stretch","name":"Banded Lat Stretch","bodyPart":"back","category":"stretching","equipment":"resistance_band","muscles":["latissimus_dorsi"],"steps":["Hold a band overhead with both hands under light tension.","Hinge forward at the hips with your arms reaching ahead.","Let your chest sink to lengthen the sides of your back.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/banded-lat-stretch-main.webp"}},{"id":"banded-lateral-walk","name":"Banded Lateral Walk","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_medius"],"steps":["Place a loop band around the legs above the knees (or around the ankles for a harder version).","Stand in a quarter-squat: feet shoulder-width, hips back, chest up, knees tracking over the toes.","Step one foot directly out to the side against the band tension.","Bring the trailing foot in toward the lead — keep tension on the band the entire time, do not let the feet snap together.","Continue side-stepping in one direction for the prescribed reps or distance, then reverse.","Stay low throughout; do not pop up between steps."],"images":{"start":"images/flat/banded-lateral-walk-start.webp","peak":"images/flat/banded-lateral-walk-peak.webp"}},{"id":"banded-overhead-press","name":"Banded Overhead Press","bodyPart":"shoulders","category":"strength","equipment":"resistance_band","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Stand on the middle of a resistance band with your feet about hip-width apart.","Hold the ends of the band at shoulder height with your palms facing forward and your elbows bent.","Brace your trunk and squeeze your glutes to keep your ribs down.","Press your hands straight up overhead until your arms are fully extended.","Pause briefly at the top, then lower your hands back to your shoulders under control.","Complete the planned repetitions."],"images":{"start":"images/flat/banded-overhead-press-start.webp","peak":"images/flat/banded-overhead-press-peak.webp"}},{"id":"banded-pallof-press","name":"Banded Pallof Press","bodyPart":"core","category":"strength","equipment":"resistance_band","muscles":["obliques","transverse_abdominis"],"steps":["Anchor a resistance band at chest height and stand sideways to it with your feet shoulder-width apart, holding the band with both hands at the centre of your chest.","Step away from the anchor until the band is under tension, with your knees slightly bent and your hips and shoulders facing forward.","Press your hands straight out in front of your chest until your arms are fully extended, without letting your trunk turn toward the anchor.","Hold for a moment with your body completely still.","Bring your hands back to your chest under control.","Complete the planned repetitions, then turn around and repeat on the other side."],"images":{"start":"images/flat/banded-pallof-press-start.webp","peak":"images/flat/banded-pallof-press-peak.webp"}},{"id":"banded-push-up","name":"Banded Push-Up","bodyPart":"chest","category":"strength","equipment":"resistance_band","muscles":["pectoralis_major","triceps_brachii"],"steps":["Place a resistance band across your upper back, just below your neck, and hold each end under the palm of the same hand on the floor.","Start in a high plank with your hands slightly wider than your shoulders and your body in a straight line from head to heels.","Lower your chest toward the floor by bending your elbows, keeping them at about 45 degrees to your body.","Press the floor away and straighten your arms against the pull of the band until you are back in the plank.","Keep your core tight and your hips level during the whole repetition.","Complete the planned repetitions, or drop to your knees if you cannot keep your body in one line."],"images":{"start":"images/flat/banded-push-up-start.webp","peak":"images/flat/banded-push-up-peak.webp"}},{"id":"banded-rear-delt-stretch","name":"Banded Rear Delt Stretch","bodyPart":"shoulders","category":"stretching","equipment":"resistance_band","muscles":["posterior_deltoid"],"steps":["Loop a band around one arm and hold the other end.","Draw that arm horizontally across your chest.","Use the band to deepen the pull gently.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-rear-delt-stretch-main.webp"}},{"id":"banded-romanian-deadlift","name":"Banded Romanian Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on a loop band with both feet and grip the top of the band.","Set feet hip-width with a soft bend in the knees.","Hinge at the hips, sliding the hands down the legs.","Lower until you feel a stretch in the hamstrings.","Drive the hips forward to return to standing."],"images":{"start":"images/flat/banded-romanian-deadlift-start.webp","peak":"images/flat/banded-romanian-deadlift-peak.webp"}},{"id":"banded-seated-hip-abduction","name":"Banded Seated Hip Abduction","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_medius"],"steps":["Sit on a bench or chair with a loop band around your knees.","Keep your feet flat on the floor, hip-width apart, and maintain an upright posture.","Push your knees outwards against the band, engaging your glutes.","Hold the peak contraction briefly, then slowly return your knees to the starting position.","Control the movement throughout the entire range of motion."],"images":{"start":"images/flat/banded-seated-hip-abduction-start.webp","peak":"images/flat/banded-seated-hip-abduction-peak.webp"}},{"id":"banded-shoulder-stretch","name":"Banded Shoulder Stretch","bodyPart":"shoulders","category":"stretching","equipment":"resistance_band","muscles":["anterior_deltoid"],"steps":["Hold a band behind your back, one hand high and one low.","Keep light tension in the band.","Open your chest and draw your shoulders gently back.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/banded-shoulder-stretch-main.webp"}},{"id":"banded-squat","name":"Banded Squat","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus","quadriceps"],"steps":["Place a loop band just above the knees.","Stand with feet shoulder-width apart, toes slightly out.","Push the knees out against the band as you squat down.","Descend until thighs are parallel or below.","Drive through the heels to stand back up."],"images":{"start":"images/flat/banded-squat-start.webp","peak":"images/flat/banded-squat-peak.webp"}},{"id":"banded-standing-curl","name":"Banded Standing Leg Curl","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["hamstrings"],"steps":["Loop a resistance band around one ankle and anchor the other end under your standing foot or a fixed point in front of you.","Stand tall, holding onto something for balance if needed, with a slight bend in the standing knee.","Curl the banded heel up and back toward your glute, keeping the thigh still.","Squeeze the hamstring at the top, then lower under control to a full stretch.","Complete all reps on one side, then switch legs."],"images":{"start":"images/flat/banded-standing-curl-start.webp","peak":"images/flat/banded-standing-curl-peak.webp"}},{"id":"banded-standing-hip-abduction","name":"Banded Standing Hip Abduction","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_medius"],"steps":["Place a loop band around your ankles or just above your knees.","Stand tall with a slight bend in your knees and brace your core.","Shift your weight onto one leg, maintaining a stable torso.","Slowly abduct the free leg out to the side, feeling the glute contract.","Control the movement as you return the leg to the starting position.","Complete all reps per side before switching."],"images":{"start":"images/flat/banded-standing-hip-abduction-start.webp","peak":"images/flat/banded-standing-hip-abduction-peak.webp"}},{"id":"banded-standing-hip-adduction","name":"Banded Standing Hip Adduction","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["adductors"],"steps":["Anchor a loop band to a sturdy upright at ankle height.","Step into the loop with the working leg facing the anchor side.","Stand a few feet away so the band has tension.","Sweep the working leg across the body toward the standing leg.","Return slowly to the start. Complete reps per side, then switch."],"images":{"start":"images/flat/banded-standing-hip-adduction-start.webp","peak":"images/flat/banded-standing-hip-adduction-peak.webp"}},{"id":"banded-standing-row","name":"Banded Standing Row","bodyPart":"back","category":"strength","equipment":"resistance_band","muscles":["latissimus_dorsi","rhomboids"],"steps":["Anchor a resistance band at about chest height, stand facing it with one end in each hand, and step back until the band is under light tension.","Stand tall with your feet hip-width apart and your knees slightly bent, with your arms stretched out in front of you.","Pull your elbows back along your sides and bring your hands toward your lower ribs.","Squeeze your shoulder blades together at the end of the pull without shrugging.","Slowly stretch your arms forward again, resisting the band.","Complete the planned repetitions."],"images":{"start":"images/flat/banded-standing-row-start.webp","peak":"images/flat/banded-standing-row-peak.webp"}},{"id":"banded-sumo-walk","name":"Banded Sumo Walk","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["gluteus_maximus","gluteus_medius"],"steps":["Place a loop band around your lower legs, just above the ankles.","Drop into a quarter squat with feet wider than shoulder-width.","Step sideways in a wide stance, keeping tension on the band.","Bring the trailing foot in only partway so the band stays taut, and keep stepping for the prescribed distance before leading with the other leg.","Stay low throughout — do not stand up between steps."],"images":{"start":"images/flat/banded-sumo-walk-start.webp","peak":"images/flat/banded-sumo-walk-peak.webp"}},{"id":"banded-terminal-knee-extension","name":"Banded Terminal Knee Extension","bodyPart":"upper_legs","category":"strength","equipment":"loop_band","muscles":["quadriceps"],"steps":["Anchor a loop band to a sturdy upright at knee height.","Step into the loop so the band sits behind one knee.","Step back so the band pulls the knee into a slight bend.","Extend the knee fully against the band, contracting the quad.","Return slowly. Complete reps per side, then switch."],"images":{"start":"images/flat/banded-terminal-knee-extension-start.webp","peak":"images/flat/banded-terminal-knee-extension-peak.webp"}},{"id":"banded-triceps-stretch","name":"Banded Triceps Stretch","bodyPart":"upper_arms","category":"stretching","equipment":"resistance_band","muscles":["triceps_brachii"],"steps":["Hold a band that runs down your back, top hand behind your head.","Anchor the lower hand at your lower back.","Reach the top hand down to feel the triceps lengthen.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/banded-triceps-stretch-main.webp"}},{"id":"barbell-ab-rollout","name":"Barbell Ab Rollout","bodyPart":"core","category":"strength","equipment":"barbell","muscles":["rectus_abdominis"],"steps":["Load plates of equal size on both ends of a barbell and place it on the floor.","Kneel behind the bar and grip it shoulder-width, arms extended.","Brace the core hard, then roll the bar forward away from your body.","Go as far as you can keep a neutral spine — stop before the hips sag.","Pull the bar back to the starting position by contracting the abs and lats.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/barbell-ab-rollout-start.webp","peak":"images/flat/barbell-ab-rollout-peak.webp"}},{"id":"barbell-box-squat","name":"Barbell Box Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Set a box or bench behind you at a height where your thighs end up about parallel to the floor when you sit on it.","Take the barbell on your upper back, step back and stand with your feet a little wider than shoulder-width.","Brace your trunk and push your hips back, then lower yourself under control toward the box.","Sit onto the box without dropping onto it, keeping your chest up and your shins close to vertical.","Pause briefly with your muscles still tight, without relaxing your back.","Drive through your whole foot to stand up, and repeat for the planned repetitions."],"images":{"start":"images/flat/barbell-box-squat-start.webp","peak":"images/flat/barbell-box-squat-peak.webp"}},{"id":"barbell-bulgarian-split-squat","name":"Barbell Bulgarian Split Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Set a barbell across the upper back and stand about two feet in front of a flat bench, facing away from it.","Place the top of one foot on the bench behind you, with the front foot far enough forward to keep the shin close to vertical when you lower.","Brace the trunk and lower the back knee toward the floor by bending the front hip and knee.","Descend until the front thigh is about parallel to the floor, keeping the chest up.","Drive through the middle of the front foot to return to the start.","Complete the repetitions on one leg, then switch."],"images":{"start":"images/flat/barbell-bulgarian-split-squat-start.webp","peak":"images/flat/barbell-bulgarian-split-squat-peak.webp"}},{"id":"barbell-calf-raise","name":"Barbell Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"barbell","muscles":["gastrocnemius"],"steps":["Place a barbell across your upper back as in a squat.","Stand with the balls of your feet on a raised platform.","Push up onto your toes as high as possible.","Pause and squeeze your calves at the top.","Lower your heels below the platform and repeat."],"images":{"start":"images/flat/barbell-calf-raise-start.webp","peak":"images/flat/barbell-calf-raise-peak.webp"}},{"id":"barbell-curl","name":"Barbell Curl","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["biceps_brachii"],"steps":["Stand holding a barbell with a shoulder-width underhand grip.","Curl the bar up toward your shoulders.","Squeeze at the top, then lower under control.","Repeat."],"images":{"start":"images/flat/barbell-curl-start.webp","peak":"images/flat/barbell-curl-peak.webp"}},{"id":"barbell-front-raise","name":"Barbell Front Raise","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid"],"steps":["Stand holding a barbell with an overhand grip at thigh level.","Keep your arms straight and core braced.","Raise the barbell in front of you to shoulder height.","Pause briefly at the top.","Lower under control and repeat."],"images":{"start":"images/flat/barbell-front-raise-start.webp","peak":"images/flat/barbell-front-raise-peak.webp"}},{"id":"barbell-glute-bridge","name":"Barbell Glute Bridge","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus"],"steps":["Lie on the floor with a barbell across your hips and knees bent.","Drive your hips up by squeezing your glutes.","Hold at the top with hips fully extended.","Lower with control.","Repeat."],"images":{"start":"images/flat/barbell-glute-bridge-start.webp","peak":"images/flat/barbell-glute-bridge-peak.webp"}},{"id":"barbell-isometric-squat-hold","name":"Barbell Isometric Squat Hold","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Set the bar on your upper back, grip it just outside your shoulders and step back from the rack with your feet about shoulder-width apart.","Take a big breath into your belly, brace your core and keep your chest tall.","Sit down and back until your thighs are about parallel to the floor or a little below, with your knees tracking over your toes.","Stop at the bottom and hold the position, with your weight over the middle of your feet.","Keep your back flat and your knees pushed out while you hold for the planned time.","Drive up through your feet to stand, then rack the bar."],"images":{"main":"images/flat/barbell-isometric-squat-hold-main.webp"}},{"id":"barbell-lunge","name":"Barbell Lunge","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Place a barbell across your upper back and stand tall.","Step forward with one leg into a long stride.","Lower your back knee toward the ground until your front thigh is parallel.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/barbell-lunge-start.webp","peak":"images/flat/barbell-lunge-peak.webp"}},{"id":"barbell-overhead-extension","name":"Barbell Overhead Extension","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["triceps_brachii"],"steps":["Load a barbell with an appropriate weight and stand or sit with a neutral spine.","Grip the barbell with an overhand, shoulder-width grip, and press it overhead.","Slowly lower the barbell behind your head by flexing your elbows, keeping your upper arms stable.","Extend your elbows to press the barbell back to the starting overhead position, squeezing your triceps.","Maintain control throughout the movement, avoiding momentum."],"images":{"start":"images/flat/barbell-overhead-extension-start.webp","peak":"images/flat/barbell-overhead-extension-peak.webp"}},{"id":"barbell-preacher-curl","name":"Barbell Preacher Curl","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["biceps_brachii"],"steps":["Sit on a preacher bench with your chest against the pad, gripping a barbell with an underhand, shoulder-width grip.","Position your upper arms firmly against the pad, ensuring your elbows are slightly bent at the start.","Curl the barbell upwards by contracting your biceps, keeping your upper arms stationary on the pad.","Squeeze your biceps at the top of the movement, focusing on peak contraction.","Slowly lower the barbell back to the starting position, controlling the eccentric phase.","Lower until your arms are almost fully extended to get a full stretch in the biceps."],"images":{"start":"images/flat/barbell-preacher-curl-start.webp","peak":"images/flat/barbell-preacher-curl-peak.webp"}},{"id":"barbell-pullover","name":"Barbell Pullover","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie across a bench with a barbell held over your chest.","Lower the bar back over your head in an arc.","Pull it back to the start over your chest.","Repeat."],"images":{"start":"images/flat/barbell-pullover-start.webp","peak":"images/flat/barbell-pullover-peak.webp"}},{"id":"barbell-rear-delt-row","name":"Barbell Rear Delt Row","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["posterior_deltoid"],"steps":["Hinge at the hips with a flat back until your torso is nearly parallel to the floor.","Hold a barbell with an overhand, wider-than-shoulder-width grip, arms hanging.","Row the bar up toward your upper chest with the elbows flaring out to the sides.","Pause and squeeze the rear delts and upper back at the top.","Lower the bar under control and repeat."],"images":{"start":"images/flat/barbell-rear-delt-row-start.webp","peak":"images/flat/barbell-rear-delt-row-peak.webp"}},{"id":"barbell-reverse-lunge","name":"Barbell Reverse Lunge","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Place a barbell across your upper back and stand tall.","Step one foot backward into a long stride.","Lower your back knee toward the ground under control.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/barbell-reverse-lunge-start.webp","peak":"images/flat/barbell-reverse-lunge-peak.webp"}},{"id":"barbell-row","name":"Bent-Over Barbell Row","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Hinge at the hips with a slight knee bend.","Grip the bar slightly wider than shoulder-width.","Pull the bar to your lower chest, squeezing your shoulder blades.","Lower the bar under control.","Repeat."],"images":{"start":"images/flat/barbell-row-start.webp","peak":"images/flat/barbell-row-peak.webp"}},{"id":"barbell-wrist-curl","name":"Barbell Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"barbell","muscles":["forearm_flexors"],"steps":["Sit on a bench with forearms resting on the thighs, palms up.","Hold a barbell with hands shoulder-width, wrists hanging off the knees.","Let the bar roll down to the fingertips at the bottom.","Curl the bar up by flexing the wrists.","Lower under control."],"images":{"start":"images/flat/barbell-wrist-curl-start.webp","peak":"images/flat/barbell-wrist-curl-peak.webp"}},{"id":"barbell-zercher-hold","name":"Barbell Zercher Hold","bodyPart":"core","category":"strength","equipment":"barbell","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Set a barbell on a rack at about the height of your lower ribs and place the crooks of your elbows under the bar.","Fold your arms and clasp your hands together in front of your chest to lock the bar against your body.","Lift the bar off the rack and step back, standing with your feet about shoulder-width apart.","Stand tall, brace your abs and keep your ribs down, so that the bar rests against your abdomen without pulling you forward.","Hold the position for the planned time, breathing slowly and keeping your elbows pressed together.","Return the bar to the rack, or lower it to the floor with control."],"images":{"main":"images/flat/barbell-zercher-hold-main.webp"}},{"id":"barbell-zercher-squat-hold","name":"Barbell Zercher Squat Hold","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Set a barbell on a rack at about the height of your lower ribs, place the crooks of your elbows under the bar and clasp your hands in front of your chest.","Lift the bar off the rack, step back and stand with your feet about shoulder-width apart.","Brace your abs and keep your chest tall, then sit down and back until your thighs are about parallel to the floor.","Stop at the bottom and hold, with your elbows resting inside your knees and your knees pushed out over your toes.","Keep the bar close to your abdomen and your back straight while you hold for the planned time.","Drive up through your feet to stand and return the bar to the rack."],"images":{"main":"images/flat/barbell-zercher-squat-hold-main.webp"}},{"id":"battle-rope-double-slam","name":"Battle Rope Double Slam","bodyPart":"full_body","category":"cardio","equipment":"battle_rope","muscles":["anterior_deltoid","latissimus_dorsi"],"steps":["Take one rope end in each hand and face the anchor, standing far enough back that the ropes have a slight slack.","Set your feet slightly wider than your hips and sit into a quarter squat with your chest up.","Swing both arms up together, letting the ropes rise in front of you as you extend through the hips.","Slam both ends down to the floor at the same time, hinging at the hips and driving through your lats.","Ride the rebound straight back into the next slam, keeping both arms moving in unison rather than alternating.","Keep slamming for the desired time or number of reps."],"images":{"start":"images/flat/battle-rope-double-slam-start.webp","peak":"images/flat/battle-rope-double-slam-peak.webp"}},{"id":"battle-ropes","name":"Battle Ropes","bodyPart":"full_body","category":"cardio","equipment":"battle_rope","muscles":["anterior_deltoid","lateral_deltoid","latissimus_dorsi"],"steps":["Anchor the ropes to a fixed point and grab one end in each hand.","Step back so the ropes have moderate slack.","Drop into a quarter squat with feet shoulder-width.","Drive each arm up and down rapidly to send waves through the ropes.","Continue for the prescribed work interval."],"images":{"main":"images/flat/battle-ropes-main.webp"}},{"id":"bear-crawl","name":"Bear Crawl","bodyPart":"full_body","category":"strength","muscles":["anterior_deltoid","rectus_abdominis"],"steps":["Start on all fours with your hands under your shoulders and knees under your hips.","Tuck your toes and lift your knees a few centimeters off the floor.","Keeping your back flat and hips low, step your right hand and left foot forward together.","Then move your left hand and right foot, crawling forward in a controlled rhythm.","Keep your core braced and your hips from swaying side to side."],"images":{"start":"images/flat/bear-crawl-start.webp","peak":"images/flat/bear-crawl-peak.webp"}},{"id":"bear-plank-hold","name":"Bear Plank Hold","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Start on hands and knees with the hands under the shoulders and the knees under the hips.","Tuck the toes under and brace the abdominals so the back is flat.","Press into the hands and lift the knees a couple of inches off the floor.","Hold the position with the hips level and the head in line with the spine.","Breathe steadily, then lower the knees to rest."],"images":{"main":"images/flat/bear-plank-hold-main.webp"}},{"id":"behind-the-back-barbell-shrug","name":"Behind the Back Barbell Shrug","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["trapezius"],"steps":["Stand holding a barbell behind your back with an overhand grip.","Keep your arms straight and chest up.","Shrug your shoulders straight up toward your ears.","Pause and squeeze at the top.","Lower under control and repeat."],"images":{"start":"images/flat/behind-the-back-barbell-shrug-start.webp","peak":"images/flat/behind-the-back-barbell-shrug-peak.webp"}},{"id":"behind-the-neck-lat-pulldown","name":"Behind-the-Neck Lat Pulldown","bodyPart":"back","category":"strength","equipment":"lat_pulldown_machine","muscles":["latissimus_dorsi"],"steps":["Sit at a lat pulldown station with thighs secured under the pad.","Grip the bar with a wide, overhand grip — wider than shoulder-width.","Keep the torso upright and tuck the chin slightly forward.","Pull the bar down behind the head until it touches the base of the neck.","Return under control to the full overhead stretch.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/behind-the-neck-lat-pulldown-start.webp","peak":"images/flat/behind-the-neck-lat-pulldown-peak.webp"}},{"id":"behind-the-neck-press","name":"Behind the Neck Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Sit or stand with a barbell resting on your upper traps behind your neck.","Grip the bar wider than shoulder width.","Press the bar straight up overhead until your arms are extended.","Lower the bar back to the starting position under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/behind-the-neck-press-start.webp","peak":"images/flat/behind-the-neck-press-peak.webp"}},{"id":"behind-the-neck-pull-ups","name":"Behind-the-Neck Pull-Up","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Grip the pull-up bar with an overhand grip wider than shoulder-width and hang at full arm extension with your legs together.","Keep your torso vertical rather than leaning back, and pull your elbows down and out to the sides.","Continue pulling until the bar passes behind your head and the back of your neck comes level with it, without letting the bar touch your neck.","Lower yourself under control back to a full dead hang, keeping your head still rather than letting it snap forward.","Repeat for the desired number of reps."],"images":{"start":"images/flat/behind-the-neck-pull-ups-start.webp","peak":"images/flat/behind-the-neck-pull-ups-peak.webp"}},{"id":"bench-adductor-stretch","name":"Bench Adductor Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"flat_bench","muscles":["adductors"],"steps":["Stand side-on to a bench.","Rest one straight leg up on the bench out to the side.","Keep your torso upright and shift gently toward the bench.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-adductor-stretch-main.webp"}},{"id":"bench-ankle-stretch","name":"Bench Ankle Stretch","bodyPart":"lower_legs","category":"stretching","equipment":"flat_bench","muscles":["gastrocnemius"],"steps":["Place one whole foot flat on top of a bench.","Keep your torso upright.","Drive that knee forward over your toes.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-ankle-stretch-main.webp"}},{"id":"bench-bulgarian-split-stretch","name":"Bench Bulgarian Split Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"flat_bench","muscles":["hip_flexors","quadriceps"],"steps":["Rest the top of your rear foot on a bench behind you.","Set the front foot flat and bend that knee.","Sink your hips straight down.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-bulgarian-split-stretch-main.webp"}},{"id":"bench-calf-stretch","name":"Bench Calf Stretch","bodyPart":"lower_legs","category":"stretching","equipment":"flat_bench","muscles":["gastrocnemius"],"steps":["Place the ball of one foot on the edge of a bench.","Keep that knee straight.","Let your heel drop down below the toes.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-calf-stretch-main.webp"}},{"id":"bench-chest-stretch","name":"Bench Chest Stretch","bodyPart":"chest","category":"stretching","equipment":"flat_bench","muscles":["pectoralis_major"],"steps":["Kneel with your back to a bench.","Place both hands behind you on the edge of the bench.","Sink your hips down to open the chest.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/bench-chest-stretch-main.webp"}},{"id":"bench-childs-pose","name":"Bench Child's Pose","bodyPart":"back","category":"stretching","equipment":"flat_bench","muscles":["erector_spinae","latissimus_dorsi"],"steps":["Kneel on the floor in front of a bench.","Extend both arms forward and rest them on the bench.","Sit your hips back toward your heels and let the chest sink.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/bench-childs-pose-main.webp"}},{"id":"bench-couch-stretch","name":"Bench Couch Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"flat_bench","muscles":["hip_flexors","quadriceps"],"steps":["Kneel with your rear shin against the front of a bench.","Place the front foot flat on the floor.","Bring your torso upright until the front of the thigh stretches.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-couch-stretch-main.webp"}},{"id":"bench-decline-plank-hold","name":"Bench Decline Plank Hold","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Place a bench behind you and put the tops of your feet on it, then put your hands on the floor under your shoulders with your arms straight.","Walk your hands to a position where your body is in one straight line from your head to your heels.","Squeeze your glutes, brace your abs and push the floor away so that your shoulders do not sink between your shoulder blades.","Keep your neck in line with your spine and look at the floor between your hands.","Hold the position for the planned time, breathing slowly.","Lower your knees to the floor and rest."],"images":{"main":"images/flat/bench-decline-plank-hold-main.webp"}},{"id":"bench-dips","name":"Bench Dips","bodyPart":"upper_arms","category":"strength","muscles":["triceps_brachii"],"steps":["Sit on a bench and place your hands on the edge beside your hips.","Slide your hips off the bench with legs extended.","Lower your body by bending your elbows to 90 degrees.","Press through your palms to return to the start.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bench-dips-start.webp","peak":"images/flat/bench-dips-peak.webp"}},{"id":"bench-figure-4-glute-stretch","name":"Bench Figure-4 Glute Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"flat_bench","muscles":["gluteus_maximus"],"steps":["Sit on the end of a bench.","Cross one ankle over the opposite knee.","Keep your back flat and hinge forward over the crossed leg.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-figure-4-glute-stretch-main.webp"}},{"id":"bench-hamstring-stretch","name":"Bench Hamstring Stretch","bodyPart":"upper_legs","category":"stretching","equipment":"flat_bench","muscles":["hamstrings"],"steps":["Place one heel on a bench with that leg straight.","Stand tall on the supporting leg.","Hinge forward from the hips over the raised leg.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/bench-hamstring-stretch-main.webp"}},{"id":"bench-hollow-hold","name":"Bench Hollow Hold","bodyPart":"core","category":"strength","equipment":"flat_bench","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie on your back on a flat bench with the glutes and lower back on the pad and the legs extended.","Reach the arms overhead beside the ears.","Brace the abdominals and press the lower back into the bench.","Lift the shoulders and the straight legs a few inches to form a shallow hollow.","Hold the position while breathing steadily, then lower to rest."],"images":{"main":"images/flat/bench-hollow-hold-main.webp"}},{"id":"bench-lat-stretch","name":"Bench Lat Stretch","bodyPart":"back","category":"stretching","equipment":"flat_bench","muscles":["latissimus_dorsi"],"steps":["Kneel on the floor in front of a bench.","Place both hands on top of the bench.","Sit your hips back and let your chest sink down.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/bench-lat-stretch-main.webp"}},{"id":"bench-leg-pull-in","name":"Bench Leg Pull-In","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Sit on a flat bench, grip its edges beside or just behind your hips and lean your torso back slightly.","Extend your legs out in front of you with your feet off the floor.","Pull your knees toward your chest, bringing the torso slightly forward to meet them.","Extend the legs back out under control without letting your feet touch the floor.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/bench-leg-pull-in-start.webp","peak":"images/flat/bench-leg-pull-in-peak.webp"}},{"id":"bench-press","name":"Barbell Bench Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Lie flat on a bench with your eyes under the bar.","Grip the bar slightly wider than shoulder-width.","Unrack the bar and lower it to your mid-chest.","Press the bar back up to full arm extension.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bench-press-start.webp","peak":"images/flat/bench-press-peak.webp"}},{"id":"bench-pull","name":"Bench Pull","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Lie face down on an elevated bench with arms hanging straight down.","Grip a barbell or dumbbells below you.","Row the weight up to the underside of the bench.","Squeeze your shoulder blades at the top.","Lower under control and repeat."],"images":{"start":"images/flat/bench-pull-start.webp","peak":"images/flat/bench-pull-peak.webp"}},{"id":"bent-arm-barbell-pullover","name":"Bent Arm Barbell Pullover","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie on a bench holding a barbell above your chest with bent elbows.","Keep your elbows bent throughout the movement.","Lower the barbell behind your head in an arc.","Pull the barbell back over your chest using your lats.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bent-arm-barbell-pullover-start.webp","peak":"images/flat/bent-arm-barbell-pullover-peak.webp"}},{"id":"bent-arm-ez-bar-pullover","name":"Bent-Arm EZ-Bar Pullover","bodyPart":"back","category":"strength","equipment":"ez_bar","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie on a flat bench holding an EZ-bar with a narrow overhand grip on the inner bends.","Start with the bar above your chest, elbows bent to roughly 90 degrees.","Keep the elbow angle fixed and lower the bar back in an arc overhead until a deep stretch is felt in the lats and pecs.","Pull the bar back over the chest along the same arc, without straightening the elbows.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/bent-arm-ez-bar-pullover-start.webp","peak":"images/flat/bent-arm-ez-bar-pullover-peak.webp"}},{"id":"bent-knee-copenhagen-raises","name":"Bent-Knee Copenhagen Raises","bodyPart":"core","category":"strength","equipment":"flat_bench","muscles":["adductors","obliques"],"steps":["Lie on your side next to a flat bench and place the inside of your top leg or foot on it, with the top knee slightly bent or straight.","Prop yourself up on the elbow of your lower arm, directly under your shoulder.","Lift your hips so that your body forms a straight line from your head to your top leg, and bend the knee of your lower leg under you.","Raise the bent lower knee up toward the bench, keeping your hips high.","Lower the knee slowly without letting your hips drop, and repeat for the planned repetitions.","Rest, then switch sides."],"images":{"start":"images/flat/bent-knee-copenhagen-raises-start.webp","peak":"images/flat/bent-knee-copenhagen-raises-peak.webp"}},{"id":"bent-over-db-row","name":"Bent-Over Dumbbell Row","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Stand with feet hip-width, holding a dumbbell in each hand at the sides, palms facing in.","Hinge at the hips with a flat back until the torso is roughly 30–45 degrees from horizontal, dumbbells hanging directly below the shoulders.","Brace the core and pull both dumbbells up and slightly back, driving the elbows past the ribs.","Squeeze the upper back at the top, keeping the elbows tucked.","Lower under control to the starting position with the arms fully extended.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/bent-over-db-row-start.webp","peak":"images/flat/bent-over-db-row-peak.webp"}},{"id":"bent-over-ez-bar-row","name":"Bent-Over EZ-Bar Row","bodyPart":"back","category":"strength","equipment":"ez_bar","muscles":["latissimus_dorsi","rhomboids"],"steps":["Hold an EZ-bar with an overhand grip, hinge at the hips to 45 degrees.","Pull the bar to your lower ribcage.","Lower under control.","Repeat."],"images":{"start":"images/flat/bent-over-ez-bar-row-start.webp","peak":"images/flat/bent-over-ez-bar-row-peak.webp"}},{"id":"bicep-curl","name":"Dumbbell Bicep Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Stand holding dumbbells at your sides, palms forward.","Curl the weights up toward your shoulders.","Squeeze at the top, then lower under control.","Repeat."],"images":{"start":"images/flat/bicep-curl-start.webp","peak":"images/flat/bicep-curl-peak.webp"}},{"id":"bicycle-crunch","name":"Bicycle Crunch","bodyPart":"core","category":"strength","muscles":["obliques","rectus_abdominis"],"steps":["Lie on your back with hands behind your head and legs raised.","Bring one knee toward your chest while rotating your torso to meet it with the opposite elbow.","Extend that leg while bringing the other knee in.","Continue alternating in a pedaling motion.","Repeat."],"images":{"start":"images/flat/bicycle-crunch-start.webp","peak":"images/flat/bicycle-crunch-peak.webp"}},{"id":"bird-dog","name":"Bird-Dog","bodyPart":"core","category":"strength","muscles":["erector_spinae","transverse_abdominis"],"steps":["Start on all fours with a neutral spine.","Extend your right arm forward and left leg back simultaneously.","Hold for a moment, then return.","Repeat on the other side.","Alternate."],"images":{"start":"images/flat/bird-dog-start.webp","peak":"images/flat/bird-dog-peak.webp"}},{"id":"bird-dog-hold","name":"Bird Dog Hold","bodyPart":"core","category":"strength","muscles":["erector_spinae","rectus_abdominis"],"steps":["Start on all fours with hands under shoulders and knees under hips.","Extend one arm forward and the opposite leg back.","Keep your core tight and body level.","Hold the position without rotating your torso.","Hold for time. Complete on one side, then switch."],"images":{"main":"images/flat/bird-dog-hold-main.webp"}},{"id":"boat-pose","name":"Boat Pose","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Sit on the floor with the knees bent and the feet flat, hands resting behind the thighs.","Lean back until you balance just behind the sit bones and lift the chest so the spine stays long.","Lift the shins until they are parallel to the floor, then straighten the legs as far as the back stays flat.","Reach the arms forward beside the legs and hold the position for the prescribed time.","Lower the feet under control to finish."],"images":{"main":"images/flat/boat-pose-main.webp"}},{"id":"bodyweight-calf-raise","name":"Bodyweight Calf Raise","bodyPart":"lower_legs","category":"strength","muscles":["gastrocnemius"],"steps":["Stand with feet hip-width apart on a flat surface.","Push up onto the balls of your feet as high as possible.","Squeeze your calves at the top.","Lower your heels back to the floor under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bodyweight-calf-raise-start.webp","peak":"images/flat/bodyweight-calf-raise-peak.webp"}},{"id":"bodyweight-good-morning","name":"Bodyweight Good Morning","bodyPart":"back","category":"strength","muscles":["erector_spinae","hamstrings"],"steps":["Stand with feet hip-width apart and hands behind your head.","Keep a slight bend in your knees and brace your core.","Hinge at the hips and lower your torso toward parallel.","Drive your hips forward to return to standing.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bodyweight-good-morning-start.webp","peak":"images/flat/bodyweight-good-morning-peak.webp"}},{"id":"bodyweight-lateral-raise","name":"Bodyweight Lateral Raise","bodyPart":"shoulders","category":"strength","muscles":["lateral_deltoid"],"steps":["Stand upright with arms hanging at your sides.","Raise both arms out to the sides with a slight elbow bend until parallel with the floor.","Pause briefly at the top.","Lower slowly back to the starting position.","Repeat for the desired reps."],"images":{"start":"images/flat/bodyweight-lateral-raise-start.webp","peak":"images/flat/bodyweight-lateral-raise-peak.webp"}},{"id":"bodyweight-overhead-press","name":"Bodyweight Overhead Press","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Stand tall with your feet hip-width apart and your hands in loose fists at shoulder height, palms facing forward and elbows under the wrists.","Brace your core and squeeze your glutes so your ribs stay down.","Press both arms straight up until the elbows are fully extended and the upper arms are beside your ears.","Lower your hands back to shoulder height under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bodyweight-overhead-press-start.webp","peak":"images/flat/bodyweight-overhead-press-peak.webp"}},{"id":"bodyweight-reverse-lunge","name":"Bodyweight Reverse Lunge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall with your feet hip-width apart.","Step one leg back and lower your knee toward the floor.","Lower until your front thigh is parallel to the floor.","Push through your front heel to return to standing.","Repeat on both sides."],"images":{"start":"images/flat/bodyweight-reverse-lunge-start.webp","peak":"images/flat/bodyweight-reverse-lunge-peak.webp"}},{"id":"bodyweight-squat","name":"Bodyweight Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet shoulder-width apart and arms extended forward.","Sit back and down by bending your hips and knees.","Lower until your thighs are parallel to the floor.","Drive through your heels to return to standing.","Repeat for the desired number of reps."],"images":{"start":"images/flat/bodyweight-squat-start.webp","peak":"images/flat/bodyweight-squat-peak.webp"}},{"id":"bow-pose","name":"Bow Pose","bodyPart":"back","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Lie face down with the arms beside the body and the forehead resting on the mat.","Bend the knees and take hold of the outside of both ankles.","Press the shins back into the hands so the chest and thighs lift away from the floor.","Hold the lifted position for the prescribed time, keeping the neck long and the gaze forward.","Release the ankles and lower down under control."],"images":{"main":"images/flat/bow-pose-main.webp"}},{"id":"box-jump","name":"Box Jump","bodyPart":"upper_legs","category":"plyometrics","equipment":"plyo_box","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand a foot in front of a sturdy box with feet shoulder-width.","Drop into a quarter-squat and swing the arms back.","Drive the arms up and explode off the floor onto the box.","Land softly with both feet flat and knees bent.","Step down — do not jump down — and reset."],"images":{"start":"images/flat/box-jump-start.webp","peak":"images/flat/box-jump-peak.webp"}},{"id":"box-squat","name":"Box Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in front of a box or bench, feet shoulder-width apart, with your arms extended forward for balance.","Push your hips back and bend your knees, sitting back toward the box rather than straight down.","Touch the box lightly with your glutes without collapsing onto it.","Drive through your feet to stand back up, squeezing your glutes at the top.","Repeat for the desired number of reps."],"images":{"start":"images/flat/box-squat-start.webp","peak":"images/flat/box-squat-peak.webp"}},{"id":"bulgarian-split-squat","name":"Bulgarian Split Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in front of a bench, place one foot behind you on the bench.","Hold dumbbells at your sides.","Lower your body until your front thigh is parallel to the floor.","Push through your front heel to stand back up.","Repeat on both sides."],"images":{"start":"images/flat/bulgarian-split-squat-start.webp","peak":"images/flat/bulgarian-split-squat-peak.webp"}},{"id":"burpees","name":"Burpees","bodyPart":"full_body","category":"cardio","muscles":["gluteus_maximus","pectoralis_major","quadriceps"],"steps":["Stand with feet shoulder-width apart.","Squat down and place the hands on the floor in front of you.","Jump or step the feet back into a plank, then perform a push-up.","Jump or step the feet forward to the hands.","Stand up and jump explosively, reaching the arms overhead."],"images":{"main":"images/flat/burpees-main.webp"}},{"id":"butterfly-stretch","name":"Butterfly Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["adductors"],"steps":["Sit tall and press the soles of your feet together.","Let your knees drop out toward the floor.","Hold your feet and sit up tall.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/butterfly-stretch-main.webp"}},{"id":"cable-bent-over-row","name":"Cable Bent-Over Row","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi","rhomboids"],"steps":["Attach a straight or V-bar to a low cable pulley.","Hinge at the hips with knees slightly bent.","Pull the handle toward your lower chest.","Squeeze your shoulder blades at the top.","Lower with control and repeat."],"images":{"start":"images/flat/cable-bent-over-row-start.webp","peak":"images/flat/cable-bent-over-row-peak.webp"}},{"id":"cable-chest-press","name":"Cable Chest Press","bodyPart":"chest","category":"strength","equipment":"cable","muscles":["pectoralis_major"],"steps":["Set the cables to chest height and face away from the machine.","Grip a handle in each hand and step forward into a staggered stance.","Press the handles forward until your arms are extended.","Squeeze your chest at the top.","Return under control and repeat."],"images":{"start":"images/flat/cable-chest-press-start.webp","peak":"images/flat/cable-chest-press-peak.webp"}},{"id":"cable-crunch","name":"Cable Crunch","bodyPart":"core","category":"strength","equipment":"cable","muscles":["rectus_abdominis"],"steps":["Kneel in front of a cable machine with a rope attachment at the top.","Hold the rope near your forehead with elbows bent.","Crunch down by flexing your spine and bringing your elbows to your thighs.","Squeeze your abs hard at the bottom.","Return to the start position and repeat."],"images":{"start":"images/flat/cable-crunch-start.webp","peak":"images/flat/cable-crunch-peak.webp"}},{"id":"cable-curl","name":"Cable Curl","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["biceps_brachii"],"steps":["Stand facing a low cable pulley with a straight bar or EZ-bar attachment.","Grip the bar with an underhand grip, elbows at your sides.","Curl the bar up toward your shoulders.","Lower with control.","Repeat."],"images":{"start":"images/flat/cable-curl-start.webp","peak":"images/flat/cable-curl-peak.webp"}},{"id":"cable-external-rotation","name":"Cable External Rotation","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["infraspinatus_teres_minor"],"steps":["Set a cable pulley to elbow height and grip the handle.","Stand side-on to the machine with your working elbow bent at 90 degrees.","Keep your elbow glued to your side and rotate your forearm outward.","Pause at the end of the movement.","Return under control. Complete reps on one side, then switch."],"images":{"start":"images/flat/cable-external-rotation-start.webp","peak":"images/flat/cable-external-rotation-peak.webp"}},{"id":"cable-fly","name":"Cable Fly","bodyPart":"chest","category":"strength","equipment":"cable","muscles":["pectoralis_major"],"steps":["Stand between two cable columns with handles attached to high pulleys.","With a slight bend in your elbows, open your arms wide.","Bring your hands together in front of your chest in a hugging motion.","Slowly return to the starting position.","Repeat."],"images":{"start":"images/flat/cable-fly-start.webp","peak":"images/flat/cable-fly-peak.webp"}},{"id":"cable-front-raise","name":"Cable Front Raise","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["anterior_deltoid"],"steps":["Stand facing away from a low cable pulley with a handle attachment.","Hold the handle with arm extended at your thigh.","Raise your arm forward to shoulder height keeping it straight.","Pause at the top.","Lower under control and repeat."],"images":{"start":"images/flat/cable-front-raise-start.webp","peak":"images/flat/cable-front-raise-peak.webp"}},{"id":"cable-hammer-curl","name":"Cable Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["biceps_brachii","brachialis","brachioradialis"],"steps":["Attach a rope to a low cable pulley and stand facing the machine.","Grip the rope with a neutral (hammer) grip, palms facing each other.","Curl the rope upward toward your shoulders, keeping elbows pinned at your sides.","Squeeze at the top, then lower slowly to full extension.","Repeat for the desired reps."],"images":{"start":"images/flat/cable-hammer-curl-start.webp","peak":"images/flat/cable-hammer-curl-peak.webp"}},{"id":"cable-kickback","name":"Cable Glute Kickback","bodyPart":"upper_legs","category":"strength","equipment":"cable","muscles":["gluteus_maximus"],"steps":["Attach an ankle cuff to a low cable pulley and fasten it around one ankle.","Stand facing the machine, holding the frame lightly for balance, and hinge slightly forward at the hips.","Kick the cuffed leg straight back, extending the hip fully while keeping the knee nearly straight.","Squeeze the glute at full hip extension, then return the foot slowly to the start.","Complete all reps on one side before switching."],"images":{"start":"images/flat/cable-kickback-start.webp","peak":"images/flat/cable-kickback-peak.webp"}},{"id":"cable-lateral-raise","name":"Cable Lateral Raise","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["lateral_deltoid"],"steps":["Stand sideways to a low pulley and grip the handle with the hand farther from the machine.","Keep a soft bend in the elbow and let the cable run across the front of your body.","Raise the arm out to the side until parallel to the floor.","Lower under control. Complete reps per side, then switch.","Maintain tension — do not let the weight rest at the bottom."],"images":{"start":"images/flat/cable-lateral-raise-start.webp","peak":"images/flat/cable-lateral-raise-peak.webp"}},{"id":"cable-overhead-tricep-extension","name":"Cable Overhead Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["triceps_brachii"],"steps":["Attach a rope to the low pulley and select a light weight.","Take the rope in both hands, turn away from the stack and step forward into a staggered stance so the cable pulls you back.","Raise the rope overhead with your elbows bent and your upper arms close to your ears, so your hands are behind your head.","Brace your trunk and keep your upper arms still, then straighten your elbows to push the rope up until your arms are fully extended overhead.","Pause briefly at the top, then bend your elbows to lower the rope back behind your head under control.","Repeat for the planned repetitions."],"images":{"start":"images/flat/cable-overhead-tricep-extension-start.webp","peak":"images/flat/cable-overhead-tricep-extension-peak.webp"}},{"id":"cable-pallof-press","name":"Cable Pallof Press","bodyPart":"core","category":"strength","equipment":"cable","muscles":["obliques","transverse_abdominis"],"steps":["Set a cable at chest height and take the handle in both hands, standing side-on to the machine.","Step away until there is real tension on the cable, with your feet about shoulder-width apart and knees softly bent.","Bring the handle to the centre of your chest and brace your trunk and glutes.","Press the handle straight out in front of you until your arms are extended, resisting the pull that wants to rotate you toward the machine.","Hold the extended position for a moment, then bring the handle back to your chest under control.","Complete the desired reps, then turn around and repeat facing the other way."],"images":{"start":"images/flat/cable-pallof-press-start.webp","peak":"images/flat/cable-pallof-press-peak.webp"}},{"id":"cable-pull-through","name":"Cable Pull-Through","bodyPart":"upper_legs","category":"strength","equipment":"cable","muscles":["gluteus_maximus","hamstrings"],"steps":["Attach a rope to the low pulley and stand facing away from the machine with the rope between the legs.","Step forward until the cable is taut, then brace the trunk and soften the knees.","Push the hips back while keeping the spine neutral and the arms long.","Drive the hips forward and squeeze the glutes to stand tall.","Reverse into the next hinge without letting the weight stack slam down."],"images":{"start":"images/flat/cable-pull-through-start.webp","peak":"images/flat/cable-pull-through-peak.webp"}},{"id":"cable-reverse-fly","name":"Cable Reverse Fly","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["posterior_deltoid"],"steps":["Set both pulleys at about shoulder height and stand centred between the two cable towers.","Take the left handle in your right hand and the right handle in your left hand, so the cables cross in front of you.","Stand tall with your arms reaching forward at shoulder height and a slight bend in the elbows.","Sweep your arms out and back in a wide arc, leading with the elbows, until they are in line with your shoulders.","Squeeze your shoulder blades together briefly without arching your lower back.","Bring the handles back to the crossed start position slowly and repeat for the planned repetitions."],"images":{"start":"images/flat/cable-reverse-fly-start.webp","peak":"images/flat/cable-reverse-fly-peak.webp"}},{"id":"cable-tricep-kickback","name":"Cable Tricep Kickback","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["triceps_brachii"],"steps":["Attach a handle to a low cable and hinge forward at the hips.","Tuck your upper arm against your side with elbow bent 90 degrees.","Extend your elbow to push the handle back behind you.","Squeeze your triceps at the end of the movement.","Return under control. Complete reps on one side, then switch."],"images":{"start":"images/flat/cable-tricep-kickback-start.webp","peak":"images/flat/cable-tricep-kickback-peak.webp"}},{"id":"cable-upright-row","name":"Cable Upright Row","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["lateral_deltoid","trapezius"],"steps":["Stand in front of a cable machine and grip a straight bar or rope at thigh height.","Pull the bar up toward your chin, leading with your elbows.","Lower under control.","Repeat."],"images":{"start":"images/flat/cable-upright-row-start.webp","peak":"images/flat/cable-upright-row-peak.webp"}},{"id":"cable-wrist-curl","name":"Cable Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"cable","muscles":["forearm_flexors"],"steps":["Attach a short straight bar to a low cable pulley and sit on a flat bench facing the pulley, feet flat on the floor.","Take the bar with an underhand grip, palms facing up, hands about shoulder-width apart.","Rest your forearms on your thighs so that your wrists and hands reach just past your knees.","Let the cable pull your wrists down until you feel a stretch in your forearms.","Curl the bar up by flexing your wrists, keeping your forearms on your thighs.","Lower the bar under control and repeat for the planned repetitions."],"images":{"start":"images/flat/cable-wrist-curl-start.webp","peak":"images/flat/cable-wrist-curl-peak.webp"}},{"id":"calf-raise-hold","name":"Calf Raise Hold","bodyPart":"lower_legs","category":"strength","muscles":["gastrocnemius"],"steps":["Stand tall with your feet about hip-width apart and your arms relaxed at your sides.","Push through the balls of your feet and rise onto your toes as high as you can.","Keep your knees straight and your weight over the middle of your feet, not rolling out to the little toes.","Stop at the top and hold the position, heels as high as possible.","Keep your hips level, your chest tall and your breathing slow while you hold for the planned time.","Lower your heels slowly to the floor and rest."],"images":{"main":"images/flat/calf-raise-hold-main.webp"}},{"id":"camel-pose","name":"Camel Pose","bodyPart":"core","category":"stretching","muscles":["erector_spinae","hip_flexors"],"steps":["Kneel with the knees hip-width apart and the hips stacked over the knees.","Place the hands on the back of the pelvis with the fingers pointing down and lift the chest.","Press the hips forward and arch back, reaching for the heels if the position stays comfortable.","Hold the pose for the prescribed time, keeping the neck in line with the spine.","Bring the hands back to the pelvis and come up chest-first."],"images":{"main":"images/flat/camel-pose-main.webp"}},{"id":"captains-chair-knee-raise","name":"Captain's Chair Knee Raise","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Position yourself in the captain's chair with your back flat against the pad and forearms on the armrests.","Let your legs hang straight down.","Engage your core and raise your knees toward your chest.","Hold briefly at the top, then lower slowly to the starting position.","Repeat for the desired reps."],"images":{"start":"images/flat/captains-chair-knee-raise-start.webp","peak":"images/flat/captains-chair-knee-raise-peak.webp"}},{"id":"captains-chair-leg-raise","name":"Captain's Chair Leg Raise","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Position yourself in the captain's chair with your back flat against the pad and forearms on the armrests.","Let your legs hang straight down.","Keeping your legs straight, raise them until parallel with the floor or higher.","Hold briefly at the top, then lower slowly.","Repeat for the desired reps."],"images":{"start":"images/flat/captains-chair-leg-raise-start.webp","peak":"images/flat/captains-chair-leg-raise-peak.webp"}},{"id":"cat-cow","name":"Cat-Cow","bodyPart":"back","category":"stretching","muscles":["erector_spinae","rectus_abdominis"],"steps":["Start on all fours with the hands under the shoulders and the knees under the hips.","Exhale and round the spine towards the ceiling, tucking the tailbone and letting the head drop.","Inhale and reverse it: let the belly sink, lift the chest and tailbone, and look slightly forward.","Move between the two shapes slowly, one breath per position.","Finish in a neutral spine and sit back onto the heels."],"images":{"main":"images/flat/cat-cow-main.webp"}},{"id":"cat-stretch","name":"Cat Stretch","bodyPart":"back","category":"stretching","muscles":["erector_spinae"],"steps":["Start on all fours, hands under shoulders and knees under hips.","Round your spine up toward the ceiling.","Tuck your chin toward your chest.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/cat-stretch-main.webp"}},{"id":"chair-pose","name":"Chair Pose","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with the feet together or hip-width apart and the weight in the heels.","Bend the knees and send the hips back as if sitting down onto a chair.","Raise the arms overhead beside the ears, keeping the ribs from flaring.","Hold the position for the prescribed time with the chest lifted and the knees tracking over the toes.","Press through the heels to stand back up."],"images":{"main":"images/flat/chair-pose-main.webp"}},{"id":"cheat-curl","name":"Cheat Curl","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["biceps_brachii"],"steps":["Stand holding weight at thigh level with an underhand grip.","Use a slight hip drive to start the curl.","Curl the weight up toward your shoulders explosively.","Lower the weight slowly under control through the full range.","Repeat for the desired number of reps."],"images":{"start":"images/flat/cheat-curl-start.webp","peak":"images/flat/cheat-curl-peak.webp"}},{"id":"chest-press-machine","name":"Machine Chest Press","bodyPart":"chest","category":"strength","equipment":"chest_press_machine","muscles":["pectoralis_major"],"steps":["Sit in the machine with your back flat against the pad.","Grip the handles at chest level.","Push the handles forward until your arms are fully extended.","Slowly return to the starting position.","Repeat."],"images":{"start":"images/flat/chest-press-machine-start.webp","peak":"images/flat/chest-press-machine-peak.webp"}},{"id":"chest-supported-db-row","name":"Chest-Supported Dumbbell Row","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Lie face-down on an incline bench with dumbbells hanging beneath.","Row the dumbbells up to your sides.","Squeeze at the top, then lower.","Repeat."],"images":{"start":"images/flat/chest-supported-db-row-start.webp","peak":"images/flat/chest-supported-db-row-peak.webp"}},{"id":"chest-supported-dumbbell-shrug","name":"Chest Supported Dumbbell Shrug","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["trapezius"],"steps":["Set an incline bench to about 30 degrees.","Lie face down on the bench holding dumbbells at arm's length.","Shrug your shoulders up and back toward your ears.","Squeeze your upper traps at the top.","Lower under control and repeat."],"images":{"start":"images/flat/chest-supported-dumbbell-shrug-start.webp","peak":"images/flat/chest-supported-dumbbell-shrug-peak.webp"}},{"id":"chest-supported-kettlebell-row","name":"Chest-Supported Kettlebell Row","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Lie face down on an incline bench, allowing your arms to hang freely with a kettlebell in each hand.","Brace your core and retract your shoulder blades.","Pull the kettlebells towards your hips, squeezing your shoulder blades together.","Pause briefly at the top, feeling the contraction in your back.","Slowly lower the kettlebells back to the starting position with control."],"images":{"start":"images/flat/chest-supported-kettlebell-row-start.webp","peak":"images/flat/chest-supported-kettlebell-row-peak.webp"}},{"id":"chest-supported-machine-row","name":"Chest-Supported Machine Row","bodyPart":"back","category":"strength","equipment":"seated_row_machine","muscles":["latissimus_dorsi","rhomboids"],"steps":["Adjust the seat so the handles sit at lower-chest height, then sit with your chest against the pad and your feet planted.","Reach forward and take the handles with your arms extended and your shoulders relaxed.","Brace your trunk, then pull the handles back by driving your elbows behind you.","Squeeze your shoulder blades together at the end of the pull without lifting your chest off the pad.","Pause briefly, then extend your arms to return the handles forward under control.","Repeat for the planned repetitions, keeping your chest on the pad throughout."],"images":{"start":"images/flat/chest-supported-machine-row-start.webp","peak":"images/flat/chest-supported-machine-row-peak.webp"}},{"id":"chest-supported-smith-machine-row","name":"Chest-Supported Smith Machine Row","bodyPart":"back","category":"strength","equipment":"smith_machine","muscles":["latissimus_dorsi","rhomboids"],"steps":["Set an incline bench inside the Smith machine facing the bar, and set the bar low enough that your arms hang straight when you lean on the pad.","Stand astride the bench with your feet planted and your chest resting against the top of the pad.","Take an overhand grip a little wider than shoulder-width and unhook the bar with your arms extended.","Pull the bar up to your lower chest, leading with your elbows and squeezing the shoulder blades together at the top.","Lower the bar under control until your arms are straight again, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/chest-supported-smith-machine-row-start.webp","peak":"images/flat/chest-supported-smith-machine-row-peak.webp"}},{"id":"childs-pose","name":"Child's Pose","bodyPart":"back","category":"stretching","muscles":["erector_spinae","latissimus_dorsi"],"steps":["Kneel and sit your hips back toward your heels.","Fold your torso forward over your thighs.","Reach both arms out long on the floor in front.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/childs-pose-main.webp"}},{"id":"chin-tuck-hold","name":"Chin Tuck Hold","bodyPart":"full_body","category":"strength","muscles":["trapezius"],"steps":["Stand or sit tall with your shoulders relaxed.","Pull your chin straight back, creating a double chin.","Keep your head level without tilting.","Hold the position for the desired duration.","Release and repeat for multiple sets."],"images":{"main":"images/flat/chin-tuck-hold-main.webp"}},{"id":"chin-ups","name":"Chin-Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Hang from a bar with a shoulder-width underhand grip.","Pull yourself up until chin is above the bar.","Lower under control.","Repeat."],"images":{"start":"images/flat/chin-ups-start.webp","peak":"images/flat/chin-ups-peak.webp"}},{"id":"clamshells","name":"Clamshells","bodyPart":"upper_legs","category":"strength","muscles":["abductors","gluteus_medius"],"steps":["Lie on your side with knees bent and stacked on top of each other.","Keep your feet together and hips stacked.","Open your top knee toward the ceiling without rotating your hips.","Squeeze your outer glute at the top.","Lower under control. Complete reps on one side, then switch."],"images":{"start":"images/flat/clamshells-start.webp","peak":"images/flat/clamshells-peak.webp"}},{"id":"clamshells-hold","name":"Clamshell Hold","bodyPart":"upper_legs","category":"strength","muscles":["abductors","gluteus_medius"],"steps":["Lie on one side with the hips and knees bent about 45 and 90 degrees, heels together and knees stacked.","Stack the shoulders and hips vertically and brace the trunk so the pelvis cannot roll backwards.","Open the upper knee as far as it goes without the pelvis rotating, keeping the heels touching.","Hold that open position for the prescribed time, breathing normally.","Lower the knee under control and repeat on the other side."],"images":{"main":"images/flat/clamshells-hold-main.webp"}},{"id":"clap-push-ups","name":"Clap Push-Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Begin in a standard push-up position.","Lower your chest to the floor.","Explosively push up so hands leave the ground.","Clap your hands together and land softly, returning to start.","Repeat."],"images":{"start":"images/flat/clap-push-ups-start.webp","peak":"images/flat/clap-push-ups-peak.webp"}},{"id":"clean","name":"Clean","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand over a loaded barbell with feet hip-width apart.","Grip the bar just outside your knees with an overhand grip.","Drive explosively through your legs and extend your hips.","Pull yourself under the bar and catch it on your front deltoids.","Stand fully upright to complete the lift."],"images":{"start":"images/flat/clean-start.webp","peak":"images/flat/clean-peak.webp"}},{"id":"clean-and-jerk","name":"Clean and Jerk","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["anterior_deltoid","gluteus_maximus","quadriceps"],"steps":["Pull a loaded barbell from the floor to your shoulders as in a clean.","Stand fully with the bar racked on your front delts.","Dip slightly and drive the bar overhead explosively.","Drop into a partial squat under the bar as your arms lock out overhead, feet staying about hip-width apart.","Stand up fully and hold the bar steady overhead before lowering it."],"images":{"start":"images/flat/clean-and-jerk-start.webp","peak":"images/flat/clean-and-jerk-peak.webp"}},{"id":"close-grip-barbell-curl","name":"Close-Grip Barbell Curl","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["biceps_brachii"],"steps":["Stand holding a barbell with an underhand grip, hands closer than shoulder-width apart.","Start with the bar at the thighs, arms extended, elbows tucked to the sides.","Curl the bar up to the shoulders by flexing the elbows.","Squeeze the biceps at the top, then lower under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/close-grip-barbell-curl-start.webp","peak":"images/flat/close-grip-barbell-curl-peak.webp"}},{"id":"close-grip-bench-press","name":"Close-Grip Bench Press","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["triceps_brachii"],"steps":["Lie on a flat bench and grip the barbell with hands shoulder-width apart.","Lower the bar to your lower chest keeping elbows close to your sides.","Press back up to full extension.","Repeat."],"images":{"start":"images/flat/close-grip-bench-press-start.webp","peak":"images/flat/close-grip-bench-press-peak.webp"}},{"id":"close-grip-db-bench-press","name":"Close-Grip Dumbbell Bench Press","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Lie on a flat bench and hold two dumbbells together over your chest.","Lower them to your chest keeping elbows close.","Press back up.","Repeat."],"images":{"start":"images/flat/close-grip-db-bench-press-start.webp","peak":"images/flat/close-grip-db-bench-press-peak.webp"}},{"id":"close-grip-ez-bar-bench-press","name":"Close-Grip EZ-Bar Bench Press","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["triceps_brachii"],"steps":["Lie on a flat bench and grip the inner curves of the EZ-bar.","Lower the bar to your chest with elbows tucked.","Press back up to full extension.","Repeat."],"images":{"start":"images/flat/close-grip-ez-bar-bench-press-start.webp","peak":"images/flat/close-grip-ez-bar-bench-press-peak.webp"}},{"id":"close-grip-ez-bar-curl","name":"Close-Grip EZ-Bar Curl","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["biceps_brachii"],"steps":["Stand holding an EZ-bar with hands on the inner bends, palms up.","Keep the elbows tucked at the sides.","Curl the bar up to shoulder level, squeezing the biceps.","Lower under control to a full stretch.","Repeat for the prescribed reps."],"images":{"start":"images/flat/close-grip-ez-bar-curl-start.webp","peak":"images/flat/close-grip-ez-bar-curl-peak.webp"}},{"id":"close-grip-incline-bench","name":"Close-Grip Incline Bench Press","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["triceps_brachii"],"steps":["Set bench to an incline. Grip the barbell with hands shoulder-width or closer.","Lower the bar to your upper chest.","Press back up.","Repeat."],"images":{"start":"images/flat/close-grip-incline-bench-start.webp","peak":"images/flat/close-grip-incline-bench-peak.webp"}},{"id":"close-grip-lat-pulldown","name":"Close Grip Lat Pulldown","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi"],"steps":["Sit at a lat pulldown machine and secure your thighs under the pad.","Grip the close-grip handle with palms facing each other.","Pull the handle down to your upper chest.","Squeeze your lats at the bottom.","Return under control and repeat."],"images":{"start":"images/flat/close-grip-lat-pulldown-start.webp","peak":"images/flat/close-grip-lat-pulldown-peak.webp"}},{"id":"close-grip-pull-ups","name":"Close-Grip Pull-Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Hang from a pull-up bar with hands shoulder-width or narrower, palms away.","Pull yourself up until chin clears the bar.","Lower under control.","Repeat."],"images":{"start":"images/flat/close-grip-pull-ups-start.webp","peak":"images/flat/close-grip-pull-ups-peak.webp"}},{"id":"close-grip-push-ups","name":"Close Grip Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major","triceps_brachii"],"steps":["Assume a push-up position with hands directly under your shoulders.","Keep your elbows tucked close to your ribs.","Lower your chest toward the floor.","Press back up to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/close-grip-push-ups-start.webp","peak":"images/flat/close-grip-push-ups-peak.webp"}},{"id":"close-stance-leg-press","name":"Close-Stance Leg Press","bodyPart":"upper_legs","category":"strength","equipment":"leg_press","muscles":["quadriceps"],"steps":["Set the seat and back pad so your lower back stays supported throughout the repetition.","Place your feet close together near the middle of the platform, with the toes and knees pointing along the same line.","Lower the sled by bending the knees and hips while keeping both feet flat and the knees tracking over the toes.","Press the platform away through the whole foot until the legs are extended without snapping the knees straight.","Return under control and repeat for the desired number of repetitions."],"images":{"start":"images/flat/close-stance-leg-press-start.webp","peak":"images/flat/close-stance-leg-press-peak.webp"}},{"id":"cobra-stretch","name":"Cobra Stretch","bodyPart":"core","category":"stretching","muscles":["rectus_abdominis"],"steps":["Lie face down with your hands under your shoulders.","Press through your hands to lift your chest off the floor.","Keep your hips and legs on the floor, shoulders relaxed.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/cobra-stretch-main.webp"}},{"id":"cocoons","name":"Cocoons","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Lie face-up on the floor with arms extended overhead and legs extended, hovering slightly off the floor.","Simultaneously tuck the knees toward the chest and sweep the arms forward into a crunch.","Try to touch the hands to the shins at the top.","Reverse the motion smoothly, re-extending arms and legs back to the hover.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/cocoons-start.webp","peak":"images/flat/cocoons-peak.webp"}},{"id":"commando-pull-up","name":"Commando Pull-Up","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Grip the bar with the hands one in front of the other, palms facing each other, and hang with the arms straight and the body turned sideways.","Brace the trunk and pull the shoulder blades down to start the movement.","Pull yourself up, driving the elbows down, until your head clears the bar on one side of it.","Pause briefly at the top with the chest close to the bar.","Lower under control to a full hang.","Take the head to the other side of the bar on the next repetition, or swap the hand positions each set."],"images":{"start":"images/flat/commando-pull-up-start.webp","peak":"images/flat/commando-pull-up-peak.webp"}},{"id":"concentration-curl","name":"Concentration Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Sit on a bench with legs spread, holding a dumbbell in one hand.","Brace your elbow against the inside of your thigh.","Curl the dumbbell up toward your shoulder.","Lower with control.","Repeat on both sides."],"images":{"start":"images/flat/concentration-curl-start.webp","peak":"images/flat/concentration-curl-peak.webp"}},{"id":"copenhagen-plank","name":"Copenhagen Plank","bodyPart":"core","category":"strength","equipment":"flat_bench","muscles":["adductors","obliques"],"steps":["Lie on your side next to a flat bench and place your top leg on it, with the inside of the foot or the lower part of the leg resting on the bench.","Prop yourself up on the elbow of your lower arm, directly under your shoulder.","Lift your hips so that your body forms a straight line from your head to your top foot, and let the lower leg hang or lift it toward the bench.","Keep your hips high and your trunk steady, and breathe evenly.","Hold for the planned time, then lower your hips back to the floor.","Rest, then switch sides."],"images":{"main":"images/flat/copenhagen-plank-main.webp"}},{"id":"copenhagen-plank-raises","name":"Copenhagen Plank Raises","bodyPart":"core","category":"strength","equipment":"flat_bench","muscles":["adductors","obliques"],"steps":["Lie on your side next to a flat bench and place your top leg on it, with the knee or the inner foot resting on the bench.","Prop yourself up on the elbow of your lower arm, directly under the shoulder.","Lift your hips so that your body forms a straight line from your head to your top foot, with the lower leg hanging underneath.","Raise the lower leg up toward the bench until it nearly touches the top leg, keeping your hips high.","Lower the lower leg slowly without letting your hips drop, and repeat for the planned repetitions.","Rest, then switch sides."],"images":{"start":"images/flat/copenhagen-plank-raises-start.webp","peak":"images/flat/copenhagen-plank-raises-peak.webp"}},{"id":"cossack-squat","name":"Cossack Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in a wide stance with toes turned slightly out.","Shift your weight to one side, bending that knee and sinking into a deep squat.","Keep the trailing leg straight with the heel down and toes up.","Sink as low as your mobility allows, keeping the chest tall.","Drive through the bent leg back to center, then repeat to the other side."],"images":{"start":"images/flat/cossack-squat-start.webp","peak":"images/flat/cossack-squat-peak.webp"}},{"id":"cow-face-pose","name":"Cow Face Pose","bodyPart":"shoulders","category":"stretching","muscles":["gluteus_maximus","gluteus_medius"],"steps":["Sit on the floor and cross one knee directly over the other so the knees stack in the midline.","Walk the feet out towards the hips and settle both sit bones evenly on the floor.","Reach the arm on the top-knee side up and bend it behind the head, then reach the other arm up the back to clasp.","Hold the position for the prescribed time, keeping the chest open and the spine tall.","Release and repeat with the other leg and arm on top."],"images":{"main":"images/flat/cow-face-pose-main.webp"}},{"id":"crab-dips","name":"Crab Dips","bodyPart":"upper_arms","category":"strength","muscles":["triceps_brachii"],"steps":["Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.","Press into the hands and feet and lift the hips until the trunk is roughly level with the knees.","Bend the elbows straight back to lower the hips towards the floor without sitting down.","Push back up until the arms are straight, keeping the hips lifted.","Repeat for the desired number of repetitions and lower the hips to finish."],"images":{"start":"images/flat/crab-dips-start.webp","peak":"images/flat/crab-dips-peak.webp"}},{"id":"crescent-lunge","name":"Crescent Lunge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Step one foot forward into a long stance with the back heel lifted and the toes pointing forward.","Bend the front knee to about ninety degrees so it stacks over the ankle.","Draw the back hip forward so both hip points face the front of the mat, then raise the arms overhead.","Hold the position for the prescribed time with the ribs down and the back leg straight.","Step the feet together and repeat on the other side."],"images":{"main":"images/flat/crescent-lunge-main.webp"}},{"id":"cross-body-crunch","name":"Cross-Body Crunch","bodyPart":"core","category":"strength","muscles":["obliques"],"steps":["Lie face-up on the floor with knees bent and hands lightly behind the ears.","Crunch up and rotate, bringing the right elbow toward the left knee as the knee draws up.","Return to the starting position under control.","Repeat on the other side, alternating every rep."],"images":{"start":"images/flat/cross-body-crunch-start.webp","peak":"images/flat/cross-body-crunch-peak.webp"}},{"id":"cross-body-hammer-curl","name":"Cross Body Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["brachialis","brachioradialis"],"steps":["Stand tall holding a dumbbell in each hand with a neutral grip.","Curl one dumbbell up across your body toward the opposite shoulder.","Keep your elbow stationary at your side.","Lower under control and repeat on the other side.","Continue alternating for the desired number of reps."],"images":{"start":"images/flat/cross-body-hammer-curl-start.webp","peak":"images/flat/cross-body-hammer-curl-peak.webp"}},{"id":"cross-body-shoulder-stretch","name":"Cross-Body Shoulder Stretch","bodyPart":"shoulders","category":"stretching","muscles":["posterior_deltoid"],"steps":["Stand tall and bring one straight arm across your chest.","Hook your other forearm under it.","Gently pull the arm closer to your chest.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/cross-body-shoulder-stretch-main.webp"}},{"id":"crow-pose","name":"Crow Pose","bodyPart":"upper_arms","category":"strength","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Squat with the feet close together and place the palms shoulder-width apart on the floor in front of you.","Bend the elbows straight back and set the knees high onto the backs of the upper arms.","Shift the weight forward onto the hands until the feet float off the floor.","Hold the balance for the prescribed time, rounding the upper back and looking slightly forward.","Lower the feet under control."],"images":{"main":"images/flat/crow-pose-main.webp"}},{"id":"crunches","name":"Crunches","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Lie on your back with knees bent and hands behind your head.","Curl your upper body toward your knees, lifting your shoulder blades off the floor.","Squeeze your abs at the top.","Lower with control.","Repeat."],"images":{"start":"images/flat/crunches-start.webp","peak":"images/flat/crunches-peak.webp"}},{"id":"cycling","name":"Cycling","bodyPart":"upper_legs","category":"cardio","equipment":"bicycle","muscles":["quadriceps"],"steps":["Adjust the saddle so your knee is only slightly bent when the pedal is at the bottom of the stroke.","Sit on the saddle with your hands on the handlebars, elbows slightly bent and shoulders relaxed.","Place the balls of your feet over the pedal axles.","Push each pedal down and forward, then let it come up and over the top in a smooth circle.","Keep a steady cadence and choose a gear that lets you pedal without bouncing on the saddle.","Ride for the planned time or distance, easing the pace for the last few minutes to cool down."],"images":{"main":"images/flat/cycling-main.webp"}},{"id":"dancer-pose","name":"Dancer Pose","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall and shift the weight onto one foot, keeping that knee soft.","Bend the other knee and take hold of the inside of that ankle behind you.","Press the lifted foot back into the hand and reach the opposite arm forward as the chest lifts.","Hold the shape for the prescribed time with the standing hip level and the gaze steady.","Release the foot and repeat on the other side."],"images":{"main":"images/flat/dancer-pose-main.webp"}},{"id":"db-bench-press","name":"Dumbbell Bench Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Lie on a flat bench holding a dumbbell in each hand at chest level.","Press the dumbbells up until your arms are fully extended.","Lower them slowly back to the start.","Repeat."],"images":{"start":"images/flat/db-bench-press-start.webp","peak":"images/flat/db-bench-press-peak.webp"}},{"id":"db-fly","name":"Dumbbell Fly","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Lie flat on a bench with dumbbells held above your chest, palms facing each other.","With a slight bend in the elbows, lower the dumbbells out to the sides.","Return to the start by squeezing your chest.","Repeat."],"images":{"start":"images/flat/db-fly-start.webp","peak":"images/flat/db-fly-peak.webp"}},{"id":"db-goblet-squat","name":"Dumbbell Goblet Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with your feet slightly wider than shoulder-width and your toes turned out a little.","Hold one dumbbell vertically at your chest, with both hands cupped under the top end and your elbows pointing down.","Brace your trunk and sit your hips back and down, keeping your chest tall and the dumbbell close to your body.","Lower until your thighs are at least parallel to the floor, with your knees tracking over your toes and your heels flat.","Pause briefly in the bottom position, then drive through your whole foot to stand back up.","Repeat for the planned repetitions without letting the dumbbell drift away from your chest."],"images":{"start":"images/flat/db-goblet-squat-start.webp","peak":"images/flat/db-goblet-squat-peak.webp"}},{"id":"db-kickstand-deadlift","name":"Dumbbell Kickstand Deadlift","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Step one foot back so only the toes lightly touch the floor, and hinge at the hips with a flat back.","Hold a dumbbell in one hand, low beside the front foot.","Drive through the front heel and extend the hips to stand tall, the dumbbell at your side.","Keep most of your weight on the front foot throughout.","Hinge back down, lowering the dumbbell toward the floor with a flat back. Complete all reps, then switch sides."],"images":{"start":"images/flat/db-kickstand-deadlift-start.webp","peak":"images/flat/db-kickstand-deadlift-peak.webp"}},{"id":"db-lunge","name":"Dumbbell Lunge","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand holding dumbbells at your sides.","Step forward with one foot and lower your back knee toward the floor.","Push off the front foot to return.","Alternate legs.","Repeat."],"images":{"start":"images/flat/db-lunge-start.webp","peak":"images/flat/db-lunge-peak.webp"}},{"id":"db-overhead-carry","name":"Dumbbell Overhead Carry","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Clean or press a dumbbell to a locked-out position directly above your shoulder.","Push the arm all the way up so the elbow is straight and the biceps is close to your ear.","Brace your ribs down rather than letting your lower back arch to hold the weight up.","Walk forward with controlled strides, keeping the dumbbell stacked over your shoulder and hip.","Keep your eyes forward — tipping your head back to watch the weight drags your posture with it.","Carry for the desired distance, lower under control, then repeat with the other arm."],"images":{"main":"images/flat/db-overhead-carry-main.webp"}},{"id":"db-preacher-curl","name":"Dumbbell Preacher Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Adjust the seat so the armpits rest against the top of the pad and the upper arms lie flat along it.","Hold a dumbbell in each hand with an underhand grip and let the arms hang down along the pad.","Curl both dumbbells up toward the shoulders without lifting the elbows off the pad.","Squeeze the biceps briefly at the top.","Lower the dumbbells slowly until the arms are almost fully extended, then repeat."],"images":{"start":"images/flat/db-preacher-curl-start.webp","peak":"images/flat/db-preacher-curl-peak.webp"}},{"id":"db-pullover","name":"Dumbbell Pullover","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie on a flat bench with a dumbbell held above your chest, arms extended.","Lower the dumbbell behind your head in an arc, keeping slight bend in elbows.","Stretch until you feel tension in your lats and chest.","Pull the dumbbell back to the starting position.","Repeat."],"images":{"start":"images/flat/db-pullover-start.webp","peak":"images/flat/db-pullover-peak.webp"}},{"id":"db-reverse-curl","name":"Dumbbell Reverse Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["brachialis","forearm_extensors"],"steps":["Hold dumbbells with an overhand grip at your sides.","Curl them up to shoulder height.","Lower under control.","Repeat."],"images":{"start":"images/flat/db-reverse-curl-start.webp","peak":"images/flat/db-reverse-curl-peak.webp"}},{"id":"db-reverse-wrist-curl","name":"Dumbbell Reverse Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"dumbbell","muscles":["forearm_extensors"],"steps":["Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms down.","Let both wrists drop, lowering the dumbbells toward the floor.","Lift the backs of your hands toward the ceiling by extending your wrists.","Squeeze at the top, then lower under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/db-reverse-wrist-curl-start.webp","peak":"images/flat/db-reverse-wrist-curl-peak.webp"}},{"id":"db-shrug","name":"Dumbbell Shrug","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["trapezius"],"steps":["Stand holding dumbbells at your sides.","Shrug your shoulders straight up as high as possible.","Hold briefly, then lower.","Repeat."],"images":{"start":"images/flat/db-shrug-start.webp","peak":"images/flat/db-shrug-peak.webp"}},{"id":"db-skull-crusher","name":"Dumbbell Skull Crusher","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Lie on a flat bench holding dumbbells over your chest.","Lower the dumbbells toward the sides of your head.","Extend your arms back up.","Repeat."],"images":{"start":"images/flat/db-skull-crusher-start.webp","peak":"images/flat/db-skull-crusher-peak.webp"}},{"id":"db-somersault-squat","name":"Dumbbell Somersault Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet shoulder-width holding a dumbbell in one hand at the shoulder.","Squat down while reaching the dumbbell forward and across the body.","Reach the bottom of the squat with the dumbbell extended past the opposite knee.","Drive through the heels to stand up, returning the dumbbell to the shoulder.","Complete reps per side, then switch."],"images":{"start":"images/flat/db-somersault-squat-start.webp","peak":"images/flat/db-somersault-squat-peak.webp"}},{"id":"db-squat","name":"Dumbbell Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet shoulder-width, a dumbbell in each hand at the sides.","Brace the core and keep the chest up.","Squat down by hinging at the hips and bending the knees.","Descend until the thighs are parallel or below.","Drive through the heels to stand back up."],"images":{"start":"images/flat/db-squat-start.webp","peak":"images/flat/db-squat-peak.webp"}},{"id":"db-step-up-to-balance","name":"Dumbbell Step-Up to Balance","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing a low, stable step or bench with a dumbbell in each hand, arms hanging at your sides.","Place one foot flat on top of the step.","Press through the whole of the front foot and straighten that leg to lift your body onto the step.","As you rise, drive the other knee up in front of you until the thigh is about hip height.","Stand tall on the working leg and hold the knee-up position for a moment without leaning back.","Lower the free foot back to the floor under control, then step the working leg down as well and repeat; switch legs after the planned repetitions."],"images":{"start":"images/flat/db-step-up-to-balance-start.webp","peak":"images/flat/db-step-up-to-balance-peak.webp"}},{"id":"db-sumo-squat","name":"Dumbbell Sumo Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet wider than shoulder-width, toes turned out about 30 degrees.","Hold one dumbbell vertically by its top end with both hands, letting it hang between your legs.","Brace the core and keep the chest up.","Bend at the hips and knees to sit straight down into a deep squat.","Drive through the heels to return to standing.","Repeat for the desired number of reps."],"images":{"start":"images/flat/db-sumo-squat-start.webp","peak":"images/flat/db-sumo-squat-peak.webp"}},{"id":"db-svend-press","name":"Dumbbell Svend Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Stand and press two dumbbells together horizontally at chest height.","Maintain the inward squeeze on the dumbbells throughout.","Press the dumbbells forward until your arms are almost straight.","Pull them back to the chest under control.","Repeat for the prescribed reps."],"images":{"start":"images/flat/db-svend-press-start.webp","peak":"images/flat/db-svend-press-peak.webp"}},{"id":"dead-bug","name":"Dead Bug","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Lie on your back with arms extended toward the ceiling and knees at 90 degrees.","Lower your right arm and left leg toward the floor while keeping the lower back pressed down.","Return to start.","Repeat on the other side.","Alternate."],"images":{"start":"images/flat/dead-bug-start.webp","peak":"images/flat/dead-bug-peak.webp"}},{"id":"dead-bug-hold","name":"Dead Bug Hold","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Lie on your back with the arms pointing at the ceiling and the hips and knees bent to 90 degrees.","Press the lower back into the floor and keep it there for the whole set.","Extend one arm overhead and straighten the opposite leg until both hover just above the floor.","Hold that extended position for the prescribed time without letting the ribs flare or the back arch.","Return to the start and repeat with the other arm and leg."],"images":{"main":"images/flat/dead-bug-hold-main.webp"}},{"id":"dead-hang","name":"Dead Hang","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["forearm_flexors"],"steps":["Grip a pull-up bar with palms facing away, shoulder-width apart.","Hang with your arms fully extended and feet off the ground.","Relax your shoulders and let your body hang.","Keep your core lightly engaged.","Hold for the desired duration."],"images":{"main":"images/flat/dead-hang-main.webp"}},{"id":"deadlift","name":"Barbell Deadlift","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["erector_spinae","gluteus_maximus","hamstrings"],"steps":["Stand with feet hip-width apart, bar over mid-foot.","Hinge at the hips and grip the bar.","Brace your core and lift by extending hips and knees.","Stand tall at the top, then lower under control.","Repeat."],"images":{"start":"images/flat/deadlift-start.webp","peak":"images/flat/deadlift-peak.webp"}},{"id":"decline-bench-press","name":"Decline Bench Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Set the bench to a decline angle. Lie down and secure your feet.","Hold a dumbbell in each hand above your chest, then lower them to the sides of your lower chest.","Press the dumbbells back up to the start.","Repeat."],"images":{"start":"images/flat/decline-bench-press-start.webp","peak":"images/flat/decline-bench-press-peak.webp"}},{"id":"decline-bench-press-barbell","name":"Decline Barbell Bench Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Set the bench to a decline angle. Lie down and secure your feet.","Grip the bar slightly wider than shoulder-width.","Lower the bar to your lower chest, then press back up.","Repeat."],"images":{"start":"images/flat/decline-bench-press-barbell-start.webp","peak":"images/flat/decline-bench-press-barbell-peak.webp"}},{"id":"decline-bench-press-ez-bar","name":"Decline EZ-Bar Bench Press","bodyPart":"chest","category":"strength","equipment":"ez_bar","muscles":["pectoralis_major"],"steps":["Set the bench to a decline. Secure your feet and grip the EZ-bar.","Lower the bar to your lower chest.","Press back up explosively.","Repeat."],"images":{"start":"images/flat/decline-bench-press-ez-bar-start.webp","peak":"images/flat/decline-bench-press-ez-bar-peak.webp"}},{"id":"decline-crunch","name":"Decline Crunch","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Secure your feet at the top of a decline bench.","Lie back with hands crossed on your chest or behind your head.","Crunch up by flexing your spine toward your knees.","Squeeze your abs at the top.","Lower under control and repeat."],"images":{"start":"images/flat/decline-crunch-start.webp","peak":"images/flat/decline-crunch-peak.webp"}},{"id":"decline-db-fly","name":"Decline Dumbbell Fly","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Lie on a decline bench holding dumbbells above your chest.","With a slight elbow bend, lower the dumbbells wide to each side.","Squeeze the chest to bring them back up.","Repeat."],"images":{"start":"images/flat/decline-db-fly-start.webp","peak":"images/flat/decline-db-fly-peak.webp"}},{"id":"decline-push-up","name":"Decline Push-Up","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Place your feet on an elevated surface and hands on the ground.","Lower your chest to the floor in a controlled manner.","Push back up to the start.","Repeat."],"images":{"start":"images/flat/decline-push-up-start.webp","peak":"images/flat/decline-push-up-peak.webp"}},{"id":"deep-squat-hold","name":"Deep Squat Hold","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with the feet slightly wider than the shoulders and the toes turned out.","Clasp the hands in front of the chest and sit the hips down between the heels.","Lower until the hips are below the knees while the heels stay flat on the floor.","Keep the chest up and press the elbows against the knees to push them out.","Hold the position, breathing steadily, then stand up."],"images":{"main":"images/flat/deep-squat-hold-main.webp"}},{"id":"deficit-deadlift","name":"Deficit Deadlift","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["erector_spinae","gluteus_maximus","hamstrings"],"steps":["Stand on a small platform with a loaded barbell over your midfoot.","Hinge down and grip the bar just outside your knees.","Drive through your legs to stand up while keeping the bar close.","Lock out your hips and knees at the top.","Lower under control and repeat."],"images":{"start":"images/flat/deficit-deadlift-start.webp","peak":"images/flat/deficit-deadlift-peak.webp"}},{"id":"deficit-push-ups","name":"Deficit Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Place your hands on two elevated surfaces like parallettes or blocks.","Assume a plank position with hands under your shoulders.","Lower your chest below the level of your hands.","Press back up to extend your arms.","Repeat for the desired number of reps."],"images":{"start":"images/flat/deficit-push-ups-start.webp","peak":"images/flat/deficit-push-ups-peak.webp"}},{"id":"diamond-push-ups","name":"Diamond Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major","triceps_brachii"],"steps":["Assume a push-up position with hands close together forming a diamond.","Keep your elbows tucked close to your sides.","Lower your chest toward your hands.","Press back up to extend your arms.","Repeat for the desired number of reps."],"images":{"start":"images/flat/diamond-push-ups-start.webp","peak":"images/flat/diamond-push-ups-peak.webp"}},{"id":"dips","name":"Chest Dips","bodyPart":"chest","category":"strength","equipment":"dip_station","muscles":["pectoralis_major","triceps_brachii"],"steps":["Grip parallel dip bars and lift yourself to the top position with arms locked.","Lean your torso forward slightly.","Lower your body by bending your elbows until shoulders are below elbows.","Press back up to the starting position.","Repeat."],"images":{"start":"images/flat/dips-start.webp","peak":"images/flat/dips-peak.webp"}},{"id":"dolphin-pose","name":"Dolphin Pose","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","trapezius"],"steps":["Kneel and place the forearms on the floor shoulder-width apart with the elbows under the shoulders.","Tuck the toes and lift the hips up and back until the body forms an inverted V.","Press the forearms down and draw the shoulders away from the ears; let the heels stay high.","Hold the position for the prescribed time, keeping the neck relaxed between the arms.","Lower the knees to the floor to come out."],"images":{"main":"images/flat/dolphin-pose-main.webp"}},{"id":"donkey-calf-raise","name":"Donkey Calf Raise","bodyPart":"lower_legs","category":"strength","muscles":["gastrocnemius"],"steps":["Bend at the hips and place your hands on the floor in front of you, hips high and legs nearly straight.","Set your feet hip-width apart with your weight on the balls of the feet.","Lower your heels as far as they go (below the edge if you stand on a raised platform) for a full stretch.","Drive up onto the toes as high as possible, squeezing the calves.","Lower under control to a deep stretch."],"images":{"start":"images/flat/donkey-calf-raise-start.webp","peak":"images/flat/donkey-calf-raise-peak.webp"}},{"id":"doorway-chest-stretch","name":"Doorway Chest Stretch","bodyPart":"chest","category":"stretching","muscles":["pectoralis_major"],"steps":["Stand tall and raise your arms into a goalpost position.","Bend your elbows ninety degrees, forearms vertical.","Draw your elbows back and squeeze your shoulder blades.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/doorway-chest-stretch-main.webp"}},{"id":"double-db-kickstand-deadlift","name":"Double Dumbbell Kickstand Deadlift","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Step one foot back so only the toes touch the floor, and hinge at the hips with a flat back.","Hold a dumbbell in each hand, low on either side of the front shin.","Drive through the front heel and extend the hips to stand tall, the dumbbells at your sides.","Keep most of your weight on the front foot throughout.","Hinge back down, lowering both dumbbells toward the floor with a flat back. Switch sides after all reps."],"images":{"start":"images/flat/double-db-kickstand-deadlift-start.webp","peak":"images/flat/double-db-kickstand-deadlift-peak.webp"}},{"id":"double-db-overhead-carry","name":"Double Dumbbell Overhead Carry","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Clean or press a dumbbell to lockout above each shoulder.","Straighten both elbows fully and keep reaching up into the weights so the shoulders stay active, without letting the dumbbells sink down onto them.","Brace hard and keep your ribs down — with both arms overhead the temptation to arch is much stronger.","Walk forward with short, deliberate strides, keeping both dumbbells stacked over your shoulders.","Keep breathing shallowly and steadily instead of holding your breath for the whole carry.","Carry for the desired distance, then lower both weights under control."],"images":{"main":"images/flat/double-db-overhead-carry-main.webp"}},{"id":"double-kettlebell-bicep-curl","name":"Double Kettlebell Bicep Curl","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["biceps_brachii"],"steps":["Stand holding a kettlebell in each hand by the handle, palms facing forward.","Keep the elbows tucked to the sides and the bells hanging at arm length.","Curl both kettlebells up toward the shoulders by flexing the elbows.","Squeeze the biceps at the top, then lower under control to the starting position.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/double-kettlebell-bicep-curl-start.webp","peak":"images/flat/double-kettlebell-bicep-curl-peak.webp"}},{"id":"double-kettlebell-clean","name":"Double Kettlebell Clean","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with two kettlebells on the floor between your feet, handles angled slightly inward.","Hinge at the hips, grip the handles, and hike the kettlebells back between the legs.","Explosively extend the hips to drive the kettlebells up along the body.","As they reach chest height, spear your hands through the handles to catch them at the rack position on the shoulders.","Lower back to the hang by hinging at the hips and guiding the bells between the legs.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/double-kettlebell-clean-start.webp","peak":"images/flat/double-kettlebell-clean-peak.webp"}},{"id":"double-kettlebell-clean-and-press","name":"Double Kettlebell Clean and Press","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Stand with two kettlebells on the floor between your feet, feet about hip-width apart, and hinge at the hips to grip one handle in each hand.","Drive through your legs and extend your hips explosively to pull both kettlebells up, then rotate your elbows under and catch the bells in the racked position at the front of your shoulders.","Brace your core and press both kettlebells overhead until your arms are fully locked out.","Lower the kettlebells back to the racked position, then down to the floor under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/double-kettlebell-clean-and-press-start.webp","peak":"images/flat/double-kettlebell-clean-and-press-peak.webp"}},{"id":"double-kettlebell-dead-clean","name":"Double Kettlebell Dead Clean","bodyPart":"full_body","category":"olympic","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Set two kettlebells on the floor between your feet.","Hinge down and grip both handles.","Drive explosively through your legs and hips.","Pull the kettlebells up and rotate them to the rack position.","Lower them back to the floor and repeat."],"images":{"start":"images/flat/double-kettlebell-dead-clean-start.webp","peak":"images/flat/double-kettlebell-dead-clean-peak.webp"}},{"id":"double-kettlebell-dead-split-snatch","name":"Double Kettlebell Dead Split Snatch","bodyPart":"full_body","category":"olympic","equipment":"kettlebell","muscles":["anterior_deltoid","gluteus_maximus"],"steps":["Set two kettlebells on the floor between your feet.","Hinge down and grip both handles firmly.","Explosively pull the kettlebells overhead in one motion.","Drop into a split stance to catch them at lockout.","Recover by stepping feet back together."],"images":{"start":"images/flat/double-kettlebell-dead-split-snatch-start.webp","peak":"images/flat/double-kettlebell-dead-split-snatch-peak.webp"}},{"id":"double-kettlebell-jerk","name":"Double Kettlebell Jerk","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","quadriceps"],"steps":["Start with two kettlebells racked on the shoulders, elbows resting on the hips.","Perform a short dip at the knees, then explosively extend the legs to drive the kettlebells up.","As the bells rise, perform a second dip under them by bending the knees again.","Catch the kettlebells overhead with arms locked out, then stand fully upright.","Lower them back to the rack under control and repeat."],"images":{"start":"images/flat/double-kettlebell-jerk-start.webp","peak":"images/flat/double-kettlebell-jerk-peak.webp"}},{"id":"double-kettlebell-overhead-carry","name":"Double Kettlebell Overhead Carry","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Clean two kettlebells to the rack, then press or push press both to lockout overhead.","Straighten both elbows and settle each bell behind and above its wrist, with your wrists straight.","Pull your ribs down and brace hard before the first step; with both bells overhead there is nothing to counterbalance with.","Walk forward with short, controlled strides, keeping both bells stacked over your shoulders.","Keep looking straight ahead and breathe steadily through the carry.","Cover the desired distance, then lower both bells to the rack and down under control."],"images":{"main":"images/flat/double-kettlebell-overhead-carry-main.webp"}},{"id":"double-kettlebell-overhead-press","name":"Double Kettlebell Overhead Press","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Clean two kettlebells to the rack position at your shoulders.","Stand tall with feet hip-width apart.","Press both kettlebells straight overhead.","Lock out your arms at the top.","Lower back to the rack position and repeat."],"images":{"start":"images/flat/double-kettlebell-overhead-press-start.webp","peak":"images/flat/double-kettlebell-overhead-press-peak.webp"}},{"id":"double-kettlebell-push-press","name":"Double Kettlebell Push Press","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid"],"steps":["Stand with two kettlebells racked at the shoulders, elbows down and tucked.","Feet shoulder-width, core braced.","Dip the knees slightly while keeping the torso vertical.","Explosively extend the legs and press both bells overhead in one motion.","Lock out with the bells over the mid-foot.","Lower back to the rack under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/double-kettlebell-push-press-start.webp","peak":"images/flat/double-kettlebell-push-press-peak.webp"}},{"id":"double-kettlebell-rear-delt-row","name":"Double Kettlebell Rear Delt Row","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["posterior_deltoid","rhomboids"],"steps":["Stand a kettlebell just outside each foot with your feet about hip-width apart.","Hinge at the hips with a flat back until your torso is close to parallel with the floor, letting your knees bend slightly.","Take both handles with an overhand grip and let your arms hang straight down from your shoulders.","Row both bells up by driving your elbows out to the sides, away from your ribs rather than back along them.","Stop when your upper arms are roughly in line with your shoulders, and squeeze your shoulder blades together.","Lower the bells under control until your arms hang straight again, and repeat for the desired reps."],"images":{"start":"images/flat/double-kettlebell-rear-delt-row-start.webp","peak":"images/flat/double-kettlebell-rear-delt-row-peak.webp"}},{"id":"double-kettlebell-row","name":"Double Kettlebell Row","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Hold a kettlebell in each hand and hinge forward at the hips.","Let your arms hang straight down from your shoulders.","Row both kettlebells to your hips by driving elbows back.","Squeeze your shoulder blades at the top.","Lower under control and repeat."],"images":{"start":"images/flat/double-kettlebell-row-start.webp","peak":"images/flat/double-kettlebell-row-peak.webp"}},{"id":"double-kettlebell-split-jerk","name":"Double Kettlebell Split Jerk","bodyPart":"full_body","category":"olympic","equipment":"kettlebell","muscles":["anterior_deltoid","quadriceps"],"steps":["Clean two kettlebells to the rack position at your shoulders.","Dip slightly by bending your knees.","Drive the kettlebells overhead explosively.","Split your legs to catch them with locked arms.","Recover by stepping feet back together."],"images":{"start":"images/flat/double-kettlebell-split-jerk-start.webp","peak":"images/flat/double-kettlebell-split-jerk-peak.webp"}},{"id":"double-kettlebell-swing-snatch","name":"Double Kettlebell Swing Snatch","bodyPart":"full_body","category":"olympic","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with feet shoulder-width apart holding two kettlebells.","Hinge at the hips to swing the bells between your legs.","Explosively drive your hips forward to swing the bells up.","Punch through to catch both kettlebells overhead with locked arms.","Lower under control and repeat."],"images":{"start":"images/flat/double-kettlebell-swing-snatch-start.webp","peak":"images/flat/double-kettlebell-swing-snatch-peak.webp"}},{"id":"downward-dog","name":"Downward-Facing Dog","bodyPart":"full_body","category":"stretching","muscles":["gastrocnemius","hamstrings"],"steps":["Start on all fours with hands slightly ahead of your shoulders.","Tuck your toes and lift your hips up and back.","Straighten your legs and press your heels toward the floor.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/downward-dog-main.webp"}},{"id":"downward-dog-knee-tuck","name":"Downward Dog Knee Tuck","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Set up in downward dog with the hands shoulder-width apart and the hips high.","Press the floor away and brace the trunk so the lower back stays long.","Draw one knee in towards the chest, rounding the upper back slightly as it comes in.","Extend the leg back to the starting position under control.","Repeat with the other leg and keep alternating for the desired number of repetitions."],"images":{"start":"images/flat/downward-dog-knee-tuck-start.webp","peak":"images/flat/downward-dog-knee-tuck-peak.webp"}},{"id":"downward-dog-pedal","name":"Downward Dog Pedal","bodyPart":"lower_legs","category":"stretching","muscles":["gastrocnemius","soleus"],"steps":["Set up in downward dog with the hands shoulder-width apart and the hips high.","Bend one knee and let that heel lift while the opposite heel presses down towards the floor.","Switch sides smoothly, as if pedalling, keeping the hips high throughout.","Keep the hands pressing evenly so the shoulders stay stable.","Continue alternating for the desired number of repetitions or time."],"images":{"start":"images/flat/downward-dog-pedal-start.webp","peak":"images/flat/downward-dog-pedal-peak.webp"}},{"id":"downward-dog-to-knee-drive","name":"Downward Dog to Knee Drive","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Set up in downward dog and lift one leg behind you into three-legged dog.","Press both hands down and shift the weight slightly forward.","Round the upper back and drive that knee forward towards the elbow or the nose.","Extend the leg back up to three-legged dog under control.","Finish the repetitions on that side and repeat on the other."],"images":{"start":"images/flat/downward-dog-to-knee-drive-start.webp","peak":"images/flat/downward-dog-to-knee-drive-peak.webp"}},{"id":"downward-dog-to-low-lunge","name":"Downward Dog to Low Lunge","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors"],"steps":["Start in downward dog with the hands shoulder-width apart.","Shift the weight forward and step one foot up between the hands.","Lower the back knee to the floor and sink the hips into a low lunge.","Press back through the hands, lift the back knee and step the front foot back to downward dog.","Repeat on the other side and keep alternating."],"images":{"start":"images/flat/downward-dog-to-low-lunge-start.webp","peak":"images/flat/downward-dog-to-low-lunge-peak.webp"}},{"id":"downward-dog-to-plank","name":"Downward Dog to Plank","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","rectus_abdominis"],"steps":["Set up in downward dog with the hips high and the hands shoulder-width apart.","Shift the weight forward and lower the hips until the body forms a straight line in a high plank.","Hold the plank for a moment with the ribs down and the glutes engaged.","Press the floor away and lift the hips back up into downward dog.","Continue alternating for the desired number of repetitions."],"images":{"start":"images/flat/downward-dog-to-plank-start.webp","peak":"images/flat/downward-dog-to-plank-peak.webp"}},{"id":"downward-dog-to-upward-dog","name":"Downward Dog to Upward Dog","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","erector_spinae"],"steps":["Start in downward dog with the hips high and the hands shoulder-width apart.","Shift forward through plank and lower slightly, then press the chest through into upward dog with the thighs off the floor.","Draw the shoulders back and down and keep the neck long.","Tuck the toes, press the floor away and lift the hips back into downward dog.","Continue moving between the two positions for the desired number of repetitions."],"images":{"start":"images/flat/downward-dog-to-upward-dog-start.webp","peak":"images/flat/downward-dog-to-upward-dog-peak.webp"}},{"id":"drag-curl","name":"Drag Curl","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["biceps_brachii"],"steps":["Stand holding a barbell with an underhand grip, hands shoulder-width apart.","Start with the bar at the thighs and elbows at the sides.","Curl the bar by sliding (dragging) it straight up along your body.","As the bar rises, let the elbows travel backward so the bar stays in contact with your torso.","Stop when the bar reaches mid-chest; the biceps will be fully shortened.","Lower under control along the same path and repeat."],"images":{"start":"images/flat/drag-curl-start.webp","peak":"images/flat/drag-curl-peak.webp"}},{"id":"dragon-flag","name":"Dragon Flag","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Lie on a bench and grip it firmly behind your head.","Raise your body up so only your upper back stays on the bench.","Keep your body rigid in a straight line.","Lower your body under control until nearly horizontal.","Raise back up and repeat."],"images":{"start":"images/flat/dragon-flag-start.webp","peak":"images/flat/dragon-flag-peak.webp"}},{"id":"dumbbell-bench-pull","name":"Dumbbell Bench Pull","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Lie face down on an incline bench holding dumbbells.","Let your arms hang straight down.","Pull the dumbbells up toward your chest, squeezing your shoulder blades.","Lower with control.","Repeat."],"images":{"start":"images/flat/dumbbell-bench-pull-start.webp","peak":"images/flat/dumbbell-bench-pull-peak.webp"}},{"id":"dumbbell-calf-raise","name":"Dumbbell Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"dumbbell","muscles":["gastrocnemius","soleus"],"steps":["Stand holding a dumbbell in each hand at your sides.","Set your feet flat on the floor, or place the balls of your feet on a raised surface with heels hanging off for a deeper stretch.","Press through the balls of your feet to raise your heels as high as possible.","Squeeze your calves at the top of the movement.","Lower your heels back to the floor (or below the platform) to stretch the calves.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-calf-raise-start.webp","peak":"images/flat/dumbbell-calf-raise-peak.webp"}},{"id":"dumbbell-clean-and-press","name":"Dumbbell Clean and Press","bodyPart":"full_body","category":"olympic","equipment":"dumbbell","muscles":["anterior_deltoid","gluteus_maximus","quadriceps"],"steps":["Stand with the feet hip-width apart and a dumbbell in each hand, hanging at your sides.","Hinge at the hips and bend the knees slightly to lower the dumbbells to just below the knees.","Explosively extend the hips and knees and shrug to pull the dumbbells up to the shoulders, catching them with the elbows forward.","Dip slightly at the knees and drive the dumbbells straight overhead until the arms are locked out.","Lower the dumbbells back to the shoulders, then to your sides, under control.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/dumbbell-clean-and-press-start.webp","peak":"images/flat/dumbbell-clean-and-press-peak.webp"}},{"id":"dumbbell-curl-and-press","name":"Dumbbell Curl and Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","biceps_brachii"],"steps":["Stand tall with the feet hip-width apart, holding a dumbbell in each hand at your sides with the palms facing forward.","Curl both dumbbells up to the shoulders, keeping the elbows close to the body.","Press the dumbbells overhead until the arms are fully extended.","Lower the dumbbells back to the shoulders under control.","Lower them to your sides with a controlled reverse curl, then repeat."],"images":{"start":"images/flat/dumbbell-curl-and-press-start.webp","peak":"images/flat/dumbbell-curl-and-press-peak.webp"}},{"id":"dumbbell-deadlift","name":"Dumbbell Deadlift","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["erector_spinae","gluteus_maximus","hamstrings"],"steps":["Stand with feet hip-width apart, hinge at the hips with a flat back and hold the dumbbells low, at shin height.","Brace your core and keep the dumbbells close to your legs.","Drive through your heels and extend your hips to stand up tall.","Extend your hips fully at the top without hyperextending your lower back.","Hinge back down, lowering the dumbbells along your legs to your shins.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-deadlift-start.webp","peak":"images/flat/dumbbell-deadlift-peak.webp"}},{"id":"dumbbell-face-pull","name":"Dumbbell Face Pull","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["posterior_deltoid","rhomboids"],"steps":["Stand or sit holding a dumbbell in each hand with arms extended forward.","Bend your elbows and pull the dumbbells toward your face.","Flare your elbows out wide to shoulder height.","Squeeze your rear delts and upper back at the peak.","Lower the dumbbells back under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-face-pull-start.webp","peak":"images/flat/dumbbell-face-pull-peak.webp"}},{"id":"dumbbell-farmers-walk","name":"Dumbbell Farmer's Walk","bodyPart":"full_body","category":"strength","equipment":"dumbbell","muscles":["forearm_flexors","trapezius"],"steps":["Stand tall with a dumbbell in each hand, arms extended at your sides.","Retract your shoulder blades and brace your core, maintaining a neutral spine.","Walk slowly and deliberately for a set distance or duration, taking short, controlled steps.","Keep your chest up and avoid leaning to one side as you walk.","Focus on maintaining a strong, stable posture throughout the movement."],"images":{"main":"images/flat/dumbbell-farmers-walk-main.webp"}},{"id":"dumbbell-floor-press","name":"Dumbbell Floor Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Lie on the floor with a dumbbell in each hand at chest level.","Press the dumbbells upward until arms are extended.","Lower under control until elbows touch the floor.","Repeat."],"images":{"start":"images/flat/dumbbell-floor-press-start.webp","peak":"images/flat/dumbbell-floor-press-peak.webp"}},{"id":"dumbbell-front-raise","name":"Dumbbell Front Raise","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid"],"steps":["Stand with dumbbells at your sides, palms facing your thighs.","Raise one or both dumbbells forward to shoulder height.","Lower under control.","Repeat."],"images":{"start":"images/flat/dumbbell-front-raise-start.webp","peak":"images/flat/dumbbell-front-raise-peak.webp"}},{"id":"dumbbell-front-squat","name":"Dumbbell Front Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Hold a dumbbell in each hand resting on top of your shoulders.","Keep your elbows high and torso upright.","Lower your hips by bending knees until thighs are parallel to the floor.","Drive through your heels to stand back up.","Maintain a neutral spine throughout.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-front-squat-start.webp","peak":"images/flat/dumbbell-front-squat-peak.webp"}},{"id":"dumbbell-hip-thrust","name":"Dumbbell Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus"],"steps":["Sit on the floor with your upper back against a bench, knees bent, feet flat, and a dumbbell across your hips.","Brace your core and drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes powerfully at the top of the movement, ensuring full hip extension.","Slowly lower your hips back down to the starting position with control, maintaining tension.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/dumbbell-hip-thrust-start.webp","peak":"images/flat/dumbbell-hip-thrust-peak.webp"}},{"id":"dumbbell-pistol-squat","name":"Dumbbell Pistol Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall, holding a dumbbell in each hand with your arms hanging at your sides.","Lift one leg straight out in front of you, keeping it extended throughout the movement.","Lower your body by bending the knee of your standing leg, keeping your chest up and back straight.","Descend until your glutes are close to your heel or your thigh is parallel to the floor, maintaining balance.","Push through your heel to return to the starting position, extending your standing leg fully.","Complete all reps on one side, then switch legs and repeat for the other side per set."],"images":{"start":"images/flat/dumbbell-pistol-squat-start.webp","peak":"images/flat/dumbbell-pistol-squat-peak.webp"}},{"id":"dumbbell-push-press","name":"Dumbbell Push Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Stand holding dumbbells at shoulder height with palms facing forward.","Slightly bend your knees into a quarter squat.","Drive through your legs to generate momentum, then press the dumbbells overhead.","Lock out your arms at the top.","Lower the dumbbells back to shoulder height with control."],"images":{"start":"images/flat/dumbbell-push-press-start.webp","peak":"images/flat/dumbbell-push-press-peak.webp"}},{"id":"dumbbell-reverse-fly","name":"Dumbbell Reverse Fly","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["posterior_deltoid"],"steps":["Hinge forward at the hips holding dumbbells with arms hanging down.","Keep your back flat and knees slightly bent.","Raise the dumbbells out to the sides until level with your shoulders.","Squeeze your shoulder blades together at the top.","Lower the dumbbells back with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-reverse-fly-start.webp","peak":"images/flat/dumbbell-reverse-fly-peak.webp"}},{"id":"dumbbell-romanian-deadlift","name":"Dumbbell Romanian Deadlift","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand holding dumbbells in front of your thighs with a soft knee bend.","Hinge at the hips and push your glutes back.","Lower the dumbbells along your legs until you feel a hamstring stretch.","Keep your back flat and shoulders pulled back.","Drive your hips forward to return to standing.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-romanian-deadlift-start.webp","peak":"images/flat/dumbbell-romanian-deadlift-peak.webp"}},{"id":"dumbbell-shoulder-press","name":"Dumbbell Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Sit or stand holding dumbbells at shoulder height, palms facing forward.","Press both dumbbells overhead until arms are fully extended.","Keep your core braced and avoid arching your lower back.","Lower the dumbbells under control back to shoulder height.","Do not let the dumbbells drift behind your head.","Repeat for the desired number of reps."],"images":{"start":"images/flat/dumbbell-shoulder-press-start.webp","peak":"images/flat/dumbbell-shoulder-press-peak.webp"}},{"id":"dumbbell-side-bend","name":"Dumbbell Side Bend","bodyPart":"core","category":"strength","equipment":"dumbbell","muscles":["obliques"],"steps":["Stand upright holding a dumbbell in one hand at your side.","Keep the opposite hand on your hip or behind your head.","Bend laterally toward the dumbbell side, lowering it along your thigh.","Return to upright, then bend to the opposite side using only your obliques.","Complete all reps per side."],"images":{"start":"images/flat/dumbbell-side-bend-start.webp","peak":"images/flat/dumbbell-side-bend-peak.webp"}},{"id":"dumbbell-snatch","name":"Dumbbell Snatch","bodyPart":"full_body","category":"olympic","equipment":"dumbbell","muscles":["anterior_deltoid","gluteus_maximus","trapezius"],"steps":["Stand with feet shoulder-width apart, dumbbell on the floor between your feet.","Hinge and grip the dumbbell with one hand.","Explosively extend hips, knees, and ankles to pull the dumbbell upward.","Punch the dumbbell overhead in one fluid motion.","Lock out your arm and stabilize at the top.","Complete reps on one side, then switch."],"images":{"start":"images/flat/dumbbell-snatch-start.webp","peak":"images/flat/dumbbell-snatch-peak.webp"}},{"id":"dumbbell-split-squat","name":"Dumbbell Split Squat","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in a split stance holding dumbbells at your sides.","Keep your torso upright and core braced.","Lower your back knee toward the floor by bending both knees.","Stop when your front thigh is parallel to the floor.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/dumbbell-split-squat-start.webp","peak":"images/flat/dumbbell-split-squat-peak.webp"}},{"id":"dumbbell-tricep-extension","name":"Dumbbell Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Stand holding a dumbbell in each hand with your arms extended overhead.","Lower the dumbbells behind your head by bending your elbows.","Extend your arms back to the starting position.","Keep your elbows close to your head.","Repeat for the planned number of reps."],"images":{"start":"images/flat/dumbbell-tricep-extension-start.webp","peak":"images/flat/dumbbell-tricep-extension-peak.webp"}},{"id":"dumbbell-upright-row","name":"Dumbbell Upright Row","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["lateral_deltoid","trapezius"],"steps":["Stand holding two dumbbells in front of your thighs, palms facing your body.","Pull the dumbbells straight up along your body, leading with your elbows.","Raise until the dumbbells reach chin height and elbows are above the wrists.","Pause briefly, then lower with control.","Repeat for the desired reps."],"images":{"start":"images/flat/dumbbell-upright-row-start.webp","peak":"images/flat/dumbbell-upright-row-peak.webp"}},{"id":"dumbbell-windmill","name":"Dumbbell Windmill","bodyPart":"full_body","category":"strength","equipment":"dumbbell","muscles":["lateral_deltoid","obliques"],"steps":["Stand with feet shoulder-width apart, holding a dumbbell overhead in one hand, arm locked.","Turn your feet slightly away from the dumbbell side, keeping the arm straight and eyes on the weight.","Hinge at your hips, pushing them out to the side of the dumbbell, and slowly lower your torso towards the floor.","Keep your back straight and the dumbbell arm vertical as you reach your free hand towards your foot or the floor.","Reverse the motion by driving through your hips and obliques to return to the starting position.","Complete all reps on one side, then switch and repeat for the other side."],"images":{"start":"images/flat/dumbbell-windmill-start.webp","peak":"images/flat/dumbbell-windmill-peak.webp"}},{"id":"dumbbell-wrist-curl","name":"Dumbbell Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"dumbbell","muscles":["forearm_flexors"],"steps":["Sit on a bench with the forearm resting on the thigh, palm up.","Hold a dumbbell with the wrist hanging off the knee.","Let the dumbbell roll down to the fingertips.","Curl the dumbbell up by flexing the wrist.","Lower under control. Complete reps per side."],"images":{"start":"images/flat/dumbbell-wrist-curl-start.webp","peak":"images/flat/dumbbell-wrist-curl-peak.webp"}},{"id":"eagle-pose","name":"Eagle Pose","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_medius","quadriceps"],"steps":["Stand tall, bend both knees slightly and shift the weight onto one foot.","Cross the other thigh over the standing thigh and hook the foot behind the calf if it reaches.","Cross the opposite arm underneath, wind the forearms and bring the palms towards each other.","Sit down a little into the standing leg and hold for the prescribed time with the elbows lifted.","Unwind and repeat on the other side."],"images":{"main":"images/flat/eagle-pose-main.webp"}},{"id":"easy-pose","name":"Easy Pose","bodyPart":"upper_legs","category":"stretching","muscles":["erector_spinae"],"steps":["Sit on the floor and cross the shins comfortably, each foot under the opposite knee.","Sit up on a folded blanket or cushion until the knees rest below the level of the hips.","Stack the ribs over the pelvis and let the hands rest on the thighs.","Hold the seat for the prescribed time, breathing slowly and evenly.","Switch which shin is in front on the next round so both sides get equal time."],"images":{"main":"images/flat/easy-pose-main.webp"}},{"id":"elliptical-trainer","name":"Elliptical Trainer","bodyPart":"full_body","category":"cardio","equipment":"elliptical","muscles":["gluteus_maximus","quadriceps"],"steps":["Step onto the foot plates one at a time, holding the fixed centre post until you are steady, then take a moving handle in each hand.","Start the pedals turning forward, keeping your whole foot down on the plate rather than lifting your heel.","Push one handle away as the opposite foot travels forward, and pull the other back, so the arms and legs work in opposition.","Stand tall with your hips over the pedals and your core braced instead of hanging back on the handles.","Set the resistance and ramp so you can hold a smooth stride, and continue for the desired time or distance."],"images":{"main":"images/flat/elliptical-trainer-main.webp"}},{"id":"extended-side-angle","name":"Extended Side Angle Pose","bodyPart":"upper_legs","category":"strength","muscles":["obliques","quadriceps"],"steps":["Stand wide with the front foot turned out and the back foot angled slightly in.","Bend the front knee until it stacks over the ankle and keep the back leg straight.","Rest the front forearm on the thigh, or the hand on the floor or a block, and reach the top arm over the ear.","Hold the position for the prescribed time, turning the chest towards the ceiling.","Straighten the front leg to come up and repeat on the other side."],"images":{"main":"images/flat/extended-side-angle-main.webp"}},{"id":"ez-bar-bench-press","name":"EZ-Bar Bench Press","bodyPart":"chest","category":"strength","equipment":"ez_bar","muscles":["pectoralis_major"],"steps":["Lie flat on a bench with your feet planted on the floor, gripping the EZ bar's angled bends over your chest.","Unrack the bar and hold it over your lower chest with your arms extended.","Lower the bar under control toward your lower chest.","Press the bar back up to full arm extension.","Repeat for the desired number of reps."],"images":{"start":"images/flat/ez-bar-bench-press-start.webp","peak":"images/flat/ez-bar-bench-press-peak.webp"}},{"id":"ez-bar-curl","name":"EZ-Bar Curl","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["biceps_brachii"],"steps":["Stand holding an EZ-bar with an underhand grip on the angled portions.","Curl the bar up toward your shoulders, keeping your elbows pinned.","Squeeze at the top, then lower under control.","Repeat."],"images":{"start":"images/flat/ez-bar-curl-start.webp","peak":"images/flat/ez-bar-curl-peak.webp"}},{"id":"ez-bar-front-raise","name":"EZ-Bar Front Raise","bodyPart":"shoulders","category":"strength","equipment":"ez_bar","muscles":["anterior_deltoid"],"steps":["Stand holding an EZ-bar with an overhand grip on the inner bends, arms hanging in front of the thighs.","Keep the elbows slightly bent and fixed throughout.","Raise the bar in a smooth arc up to shoulder height.","Pause briefly at the top, then lower under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/ez-bar-front-raise-start.webp","peak":"images/flat/ez-bar-front-raise-peak.webp"}},{"id":"ez-bar-lying-tricep-extension","name":"EZ-Bar Lying Triceps Extension","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["triceps_brachii"],"steps":["Lie on a flat bench holding an EZ bar over your chest with a narrow grip.","Lower the bar toward your forehead by bending at the elbows.","Extend your arms back to the start.","Repeat."],"images":{"start":"images/flat/ez-bar-lying-tricep-extension-start.webp","peak":"images/flat/ez-bar-lying-tricep-extension-peak.webp"}},{"id":"ez-bar-overhead-extension","name":"EZ-Bar Overhead Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["triceps_brachii"],"steps":["Stand or sit holding an EZ-bar overhead with an overhand grip on the inner bends.","Arms fully extended, bar above the head.","Bend only the elbows to lower the bar behind the head in an arc.","Keep the upper arms vertical and close to the head; only the forearms move.","Extend the elbows to return the bar overhead.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/ez-bar-overhead-extension-start.webp","peak":"images/flat/ez-bar-overhead-extension-peak.webp"}},{"id":"ez-bar-pullover","name":"EZ Bar Pullover","bodyPart":"back","category":"strength","equipment":"ez_bar","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie supine on a flat bench with your head slightly off the end, holding an EZ bar with a pronated grip.","Extend the bar straight above your chest, keeping a slight bend in your elbows.","Slowly lower the bar in an arc behind your head, feeling a stretch in your lats and chest.","Pull the bar back to the starting position using your lats and pectorals.","Maintain control throughout the movement, avoiding momentum."],"images":{"start":"images/flat/ez-bar-pullover-start.webp","peak":"images/flat/ez-bar-pullover-peak.webp"}},{"id":"ez-bar-reverse-curl","name":"EZ-Bar Reverse Curl","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["brachialis","forearm_extensors"],"steps":["Hold an EZ-bar with an overhand grip.","Curl the bar up toward your shoulders.","Lower under control.","Repeat."],"images":{"start":"images/flat/ez-bar-reverse-curl-start.webp","peak":"images/flat/ez-bar-reverse-curl-peak.webp"}},{"id":"ez-bar-reverse-grip-row","name":"EZ Bar Reverse Grip Row","bodyPart":"back","category":"strength","equipment":"ez_bar","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Stand with feet shoulder-width apart, holding an EZ bar with an underhand, shoulder-width grip.","Hinge at your hips, keeping a slight bend in your knees and your back straight, until your torso is nearly parallel to the floor.","Let the bar hang directly below your shoulders with arms fully extended.","Pull the bar towards your lower abdomen, squeezing your shoulder blades together and driving your elbows up.","Control the eccentric phase, slowly lowering the bar back to the starting position with full arm extension."],"images":{"start":"images/flat/ez-bar-reverse-grip-row-start.webp","peak":"images/flat/ez-bar-reverse-grip-row-peak.webp"}},{"id":"ez-bar-romanian-deadlift","name":"EZ-Bar Romanian Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"ez_bar","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand holding an EZ-bar at mid-thigh with an overhand grip on the inner bends.","Feet hip-width, soft bend in the knees, chest up, lats engaged.","Push the hips back while letting the bar slide down the front of the legs.","Go until you feel a deep hamstring stretch without rounding the lower back.","Drive the hips forward to return to standing, keeping the bar close to the body.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/ez-bar-romanian-deadlift-start.webp","peak":"images/flat/ez-bar-romanian-deadlift-peak.webp"}},{"id":"ez-bar-shrug","name":"EZ-Bar Shrug","bodyPart":"shoulders","category":"strength","equipment":"ez_bar","muscles":["trapezius"],"steps":["Stand holding an EZ-bar in front of you.","Shrug your shoulders straight up.","Hold at the top, then lower.","Repeat."],"images":{"start":"images/flat/ez-bar-shrug-start.webp","peak":"images/flat/ez-bar-shrug-peak.webp"}},{"id":"ez-bar-spider-curl","name":"EZ Bar Spider Curl","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["biceps_brachii"],"steps":["Lie chest down on an incline bench holding an EZ bar with underhand grip.","Let your arms hang straight down from your shoulders.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top of the movement.","Lower the bar back down with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/ez-bar-spider-curl-start.webp","peak":"images/flat/ez-bar-spider-curl-peak.webp"}},{"id":"ez-bar-upright-row","name":"EZ-Bar Upright Row","bodyPart":"shoulders","category":"strength","equipment":"ez_bar","muscles":["lateral_deltoid","trapezius"],"steps":["Stand holding an EZ-bar with a shoulder-width grip on the angled portions.","Pull the bar straight up along your body toward your chin.","Lead with your elbows, keeping them above your hands.","Lower with control.","Repeat."],"images":{"start":"images/flat/ez-bar-upright-row-start.webp","peak":"images/flat/ez-bar-upright-row-peak.webp"}},{"id":"ez-bar-wrist-curl","name":"EZ-Bar Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"ez_bar","muscles":["forearm_flexors"],"steps":["Sit on a bench with forearms resting on the thighs, palms up.","Grip an EZ-bar on the inner bends with hands shoulder-width.","Let the bar roll down to the fingertips.","Curl the bar up by flexing the wrists.","Lower under control."],"images":{"start":"images/flat/ez-bar-wrist-curl-start.webp","peak":"images/flat/ez-bar-wrist-curl-peak.webp"}},{"id":"face-pull","name":"Cable Face Pull","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["posterior_deltoid","rhomboids"],"steps":["Attach a rope to a high cable pulley.","Pull the rope toward your face, separating the ends.","Squeeze your rear deltoids and external rotators.","Return to the starting position with control.","Repeat."],"images":{"start":"images/flat/face-pull-start.webp","peak":"images/flat/face-pull-peak.webp"}},{"id":"fire-hydrant","name":"Fire Hydrant","bodyPart":"upper_legs","category":"strength","muscles":["abductors","gluteus_medius"],"steps":["Set up on hands and knees with the hands under the shoulders, the knees under the hips and the back flat.","Brace the trunk so the hips stay level and square to the floor.","Keeping the knee bent at about 90 degrees, lift one knee out to the side until the thigh is roughly parallel to the floor.","Pause briefly at the top without rotating the pelvis or leaning away from the working side.","Lower the knee back to the starting position under control.","Complete the repetitions on one side, then switch legs."],"images":{"start":"images/flat/fire-hydrant-start.webp","peak":"images/flat/fire-hydrant-peak.webp"}},{"id":"fish-pose","name":"Fish Pose","bodyPart":"chest","category":"stretching","muscles":["erector_spinae","pectoralis_major"],"steps":["Lie on your back with the legs straight and the arms alongside the body, palms down under the hips.","Press the forearms into the floor and lift the chest towards the ceiling.","Let the crown of the head rest lightly on the floor without putting weight through the neck.","Hold the position for the prescribed time, breathing into the upper chest.","Lift the head, then lower the back down."],"images":{"main":"images/flat/fish-pose-main.webp"}},{"id":"flexed-arm-hang","name":"Flexed Arm Hang","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Grip a pull-up bar with the palms facing away, a little wider than shoulder-width, or facing you for an easier version.","Pull yourself up, or step up on a box, until the chin is above the bar.","Keep the elbows bent and pointing down, with the shoulders pulled away from the ears.","Hold the position without swinging, keeping the legs together and the trunk tight.","Lower slowly to a full hang when the chin begins to drop."],"images":{"main":"images/flat/flexed-arm-hang-main.webp"}},{"id":"floor-ez-bar-press","name":"Floor EZ-Bar Press","bodyPart":"chest","category":"strength","equipment":"ez_bar","muscles":["pectoralis_major"],"steps":["Lie on the floor holding an EZ-bar over your chest.","Lower the bar until your elbows touch the floor.","Press back up to full extension.","Repeat."],"images":{"start":"images/flat/floor-ez-bar-press-start.webp","peak":"images/flat/floor-ez-bar-press-peak.webp"}},{"id":"floor-kettlebell-pullover","name":"Floor Kettlebell Pullover","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie face-up on the floor with knees bent and feet flat.","Hold a kettlebell by the handle with both hands above your chest, arms almost straight (slight elbow bend).","Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms touch the floor.","Pull the bell back above the chest along the same arc.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/floor-kettlebell-pullover-start.webp","peak":"images/flat/floor-kettlebell-pullover-peak.webp"}},{"id":"floor-press","name":"Floor Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Lie on the floor and position yourself under a barbell in a rack.","Unrack the bar and lower it to your chest until your upper arms touch the floor.","Press back up to lockout.","Repeat."],"images":{"start":"images/flat/floor-press-start.webp","peak":"images/flat/floor-press-peak.webp"}},{"id":"flutter-kicks","name":"Flutter Kicks","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie flat on your back with your legs extended.","Place your hands under your glutes for support.","Lift both legs a few inches off the floor.","Alternate kicking your legs up and down in a small range.","Keep your core braced and lower back pressed down.","Continue for the desired duration or reps."],"images":{"start":"images/flat/flutter-kicks-start.webp","peak":"images/flat/flutter-kicks-peak.webp"}},{"id":"frog-stretch","name":"Frog Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["adductors"],"steps":["Start on your hands and knees on the floor, with your wrists under your shoulders.","Slide your knees out to the sides as far as is comfortable and turn your feet out, keeping your shins in line with your knees.","Lower onto your forearms and keep your back straight, not rounded.","Rock your hips back toward your heels until you feel a strong stretch along your inner thighs.","Hold the position and breathe slowly, keeping your hips level.","Come out by sliding the knees together and sitting back before you stand."],"images":{"main":"images/flat/frog-stretch-main.webp"}},{"id":"front-lever","name":"Front Lever","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Grip the bar with an overhand grip and hang.","Tuck your knees to your chest and pull your straight arms down toward your hips, leaning back until your torso is horizontal and your chest faces up.","Extend your body horizontally with arms straight and chest facing the ceiling.","Keep your body rigid and parallel to the floor.","Hold for the desired duration, then tuck and lower under control."],"images":{"main":"images/flat/front-lever-main.webp"}},{"id":"front-squat","name":"Front Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Clean or rack the bar to your front deltoids with elbows high.","Squat down keeping torso upright until thighs are parallel.","Drive back up.","Repeat."],"images":{"start":"images/flat/front-squat-start.webp","peak":"images/flat/front-squat-peak.webp"}},{"id":"garland-pose","name":"Garland Pose","bodyPart":"upper_legs","category":"stretching","muscles":["adductors","gluteus_maximus"],"steps":["Stand with the feet a little wider than the hips and the toes turned slightly out.","Squat down as low as the ankles allow, keeping the heels on the floor.","Bring the palms together at the chest and press the elbows against the inner knees.","Hold the position for the prescribed time with the chest lifted and the spine long.","Press through the feet to stand back up."],"images":{"main":"images/flat/garland-pose-main.webp"}},{"id":"glute-bridge","name":"Glute Bridge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Lie on your back with knees bent and feet flat on the floor.","Drive your hips up by squeezing your glutes.","Hold briefly at the top with hips fully extended.","Lower your hips back down with control.","Repeat."],"images":{"start":"images/flat/glute-bridge-start.webp","peak":"images/flat/glute-bridge-peak.webp"}},{"id":"glute-bridge-hold","name":"Glute Bridge Hold","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Lie on your back with the knees bent and the feet flat, about hip-width apart and close enough to brush your fingertips with your heels.","Push through the heels and lift the hips until the body forms a straight line from the knees to the shoulders.","Squeeze the glutes and tuck the ribs down so the lower back does not take over.","Hold the top position for the prescribed time, keeping the weight in the heels.","Lower the hips under control to finish the set."],"images":{"main":"images/flat/glute-bridge-hold-main.webp"}},{"id":"glute-kickback","name":"Glute Kickback","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Begin on all fours with hands under shoulders and knees under hips.","Keeping the knee bent at 90 degrees, drive one heel toward the ceiling.","Squeeze the glute at the top of the movement.","Lower the leg back to the starting position with control.","Complete all reps, then switch sides."],"images":{"start":"images/flat/glute-kickback-start.webp","peak":"images/flat/glute-kickback-peak.webp"}},{"id":"glute-kickback-hold","name":"Glute Kickback Hold","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Start on all fours with the hands under the shoulders and the knees under the hips.","Brace the trunk and keep the pelvis level; do not let the working side rotate upwards.","Extend one leg back and up until the thigh is in line with the torso.","Hold that position for the prescribed time, keeping the neck long and the lower back flat.","Lower the leg under control and repeat on the other side."],"images":{"main":"images/flat/glute-kickback-hold-main.webp"}},{"id":"goblet-squat","name":"Goblet Squat","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Hold a kettlebell at chest height with both hands.","Squat down keeping the weight close to your chest.","Drive back up.","Repeat."],"images":{"start":"images/flat/goblet-squat-start.webp","peak":"images/flat/goblet-squat-peak.webp"}},{"id":"good-morning","name":"Good Morning","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["erector_spinae","gluteus_maximus","hamstrings"],"steps":["Stand with a barbell across your upper back.","Hinge at the hips, pushing them back while keeping your back flat.","Lower your torso until it's nearly parallel to the floor.","Drive your hips forward to return to standing.","Repeat."],"images":{"start":"images/flat/good-morning-start.webp","peak":"images/flat/good-morning-peak.webp"}},{"id":"hack-squat","name":"Hack Squat","bodyPart":"upper_legs","category":"strength","equipment":"hack_squat","muscles":["gluteus_maximus","quadriceps"],"steps":["Load the hack squat machine and step on, positioning your back and shoulders against the pads.","Place your feet shoulder-width on the platform with toes turned out slightly.","Unlock the safety handles and lower the sled by bending at the knees and hips.","Descend until your thighs are at least parallel to the platform.","Drive through your heels to extend the legs and push the sled back to the start.","Re-engage the safety handles after your final rep."],"images":{"start":"images/flat/hack-squat-start.webp","peak":"images/flat/hack-squat-peak.webp"}},{"id":"hack-squat-calf-raise","name":"Hack Squat Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"hack_squat","muscles":["gastrocnemius","soleus"],"steps":["Load yourself into a hack squat machine with shoulders under the pads.","Place the balls of your feet on the platform with heels hanging off.","Keep your legs straight with a slight knee bend.","Press through the balls of your feet to raise your heels.","Lower your heels back below the platform for a stretch.","Repeat for the desired number of reps."],"images":{"start":"images/flat/hack-squat-calf-raise-start.webp","peak":"images/flat/hack-squat-calf-raise-peak.webp"}},{"id":"half-kneeling-hip-flexor-rock","name":"Half-Kneeling Hip Flexor Rock","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors"],"steps":["Kneel on one knee with the other foot flat on the floor in front of you.","Tuck the tailbone slightly and brace the trunk so the lower back stays neutral.","Rock the hips forward until you feel the front of the back thigh lengthen.","Rock back out of the position under control and repeat rhythmically.","Switch sides and repeat for the same number of repetitions."],"images":{"start":"images/flat/half-kneeling-hip-flexor-rock-start.webp","peak":"images/flat/half-kneeling-hip-flexor-rock-peak.webp"}},{"id":"half-moon-pose","name":"Half Moon Pose","bodyPart":"core","category":"strength","muscles":["gluteus_medius","obliques"],"steps":["From a wide standing stance, bend the front knee and place the bottom hand on the floor or a block ahead of the front foot.","Shift the weight forward and lift the back leg until it is parallel to the floor.","Straighten the standing leg and stack the top hip over the bottom one, reaching the top arm to the ceiling.","Hold the balance for the prescribed time with the lifted foot flexed.","Lower the back foot down and repeat on the other side."],"images":{"main":"images/flat/half-moon-pose-main.webp"}},{"id":"hammer-curl","name":"Dumbbell Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii","brachialis"],"steps":["Stand holding dumbbells at your sides with palms facing each other.","Curl the weights up while keeping your palms facing inward.","Squeeze at the top, then lower under control.","Repeat."],"images":{"start":"images/flat/hammer-curl-start.webp","peak":"images/flat/hammer-curl-peak.webp"}},{"id":"handstand-hold","name":"Handstand Hold","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Place the hands about shoulder-width apart on the floor and kick up into an inverted position, one leg after the other.","Press tall through the shoulders and keep the arms locked.","Squeeze the glutes and abdominals so the body forms one straight line from the hands to the toes.","Keep the gaze between the hands and hold the position, making small corrections with the fingers.","Come down under control, one leg at a time, or step out of the hold."],"images":{"main":"images/flat/handstand-hold-main.webp"}},{"id":"handstand-push-ups","name":"Handstand Push Ups","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Set two parallettes shoulder-width apart and kick up into a freestanding handstand on them.","Brace your core and keep your body straight, legs together.","Bend your elbows to lower your head between the handles.","Go down until your head is about level with the handles.","Press through the handles back to straight arms, keeping your balance.","Repeat for the desired number of reps."],"images":{"start":"images/flat/handstand-push-ups-start.webp","peak":"images/flat/handstand-push-ups-peak.webp"}},{"id":"hang-clean","name":"Hang Clean","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["gluteus_maximus","quadriceps","trapezius"],"steps":["Stand holding a barbell with a shoulder-width grip at your thighs.","Hinge at the hips to lower the bar just above your knees.","Explosively extend your hips, knees, and ankles.","Shrug your shoulders and pull the bar up.","Pull yourself under the bar and catch it on your front shoulders in a full squat.","Stand up tall, then return to the hang position."],"images":{"start":"images/flat/hang-clean-start.webp","peak":"images/flat/hang-clean-peak.webp"}},{"id":"hang-power-clean","name":"Hang Power Clean","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["gluteus_maximus","quadriceps","trapezius"],"steps":["Stand with feet hip-width apart holding a barbell at your thighs.","Hinge at the hips to lower the bar to just above the knees.","Drive through your hips and legs explosively.","Pull the bar up and catch it on your front shoulders in a partial squat.","Stand tall with the bar racked on your shoulders.","Lower the bar back to the hang position."],"images":{"start":"images/flat/hang-power-clean-start.webp","peak":"images/flat/hang-power-clean-peak.webp"}},{"id":"hang-snatch","name":"Hang Snatch","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["gluteus_maximus","quadriceps","trapezius"],"steps":["Stand with a wide snatch grip on a barbell held at the thighs and the feet about hip-width apart.","Hinge at the hips to lower the bar to just above the knees, keeping the back flat and the shoulders over the bar.","Explosively extend the hips, knees and ankles, shrugging as the bar rises.","Pull yourself under the bar and catch it overhead with locked arms in a squat.","Stand up fully with the bar overhead and stable.","Lower the bar under control back to the thighs and reset."],"images":{"start":"images/flat/hang-snatch-start.webp","peak":"images/flat/hang-snatch-peak.webp"}},{"id":"hanging-knee-raise","name":"Hanging Knee Raise","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["hip_flexors","rectus_abdominis"],"steps":["Hang from a pull-up bar with an overhand grip, arms fully extended.","Engage your core and raise your knees toward your chest.","Hold briefly at the top.","Lower your legs slowly back to the starting position.","Repeat for the desired reps."],"images":{"start":"images/flat/hanging-knee-raise-start.webp","peak":"images/flat/hanging-knee-raise-peak.webp"}},{"id":"hanging-l-sit","name":"Hanging L-Sit","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["hip_flexors","rectus_abdominis"],"steps":["Hang from a pull-up bar with an overhand grip, arms straight and the shoulders pulled down.","Brace the abdominals and lift the straight legs until they are parallel to the floor.","Keep the knees locked and the toes pointed, with the legs together.","Hold the position without swinging, breathing steadily.","Lower the legs under control to a dead hang."],"images":{"main":"images/flat/hanging-l-sit-main.webp"}},{"id":"hanging-leg-raise","name":"Hanging Leg Raise","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["hip_flexors","rectus_abdominis"],"steps":["Hang from a pull-up bar with an overhand grip.","Raise your legs in front of you until they are parallel to the floor.","Hold briefly, then lower with control.","Avoid swinging.","Repeat."],"images":{"start":"images/flat/hanging-leg-raise-start.webp","peak":"images/flat/hanging-leg-raise-peak.webp"}},{"id":"hanging-pike","name":"Hanging Pike","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["rectus_abdominis"],"steps":["Hang from a pull-up bar with a shoulder-width overhand grip.","Engage the lats and brace the core to create a hollow body.","Keeping the legs perfectly straight, lift them in a smooth arc up to the bar.","Aim to touch the toes to the bar between the hands.","Lower the legs slowly back to the hanging position and repeat."],"images":{"start":"images/flat/hanging-pike-start.webp","peak":"images/flat/hanging-pike-peak.webp"}},{"id":"hanging-tuck-hold","name":"Hanging Tuck Hold","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["hip_flexors","rectus_abdominis"],"steps":["Hang from a pull-up bar with an overhand grip and the arms straight.","Brace the abdominals and pull the knees up toward the chest, rounding the lower back slightly.","Keep the knees together and the thighs at or above hip height.","Hold the tucked position without swinging and breathe steadily.","Lower the legs under control to a full hang."],"images":{"main":"images/flat/hanging-tuck-hold-main.webp"}},{"id":"happy-baby","name":"Happy Baby Pose","bodyPart":"upper_legs","category":"stretching","muscles":["adductors","gluteus_maximus"],"steps":["Lie on your back and draw both knees towards the chest.","Take hold of the outside edges of the feet, or the shins if the feet are out of reach.","Open the knees wider than the ribs and stack the ankles above the knees, soles facing up.","Press the feet gently into the hands and hold for the prescribed time with the lower back on the floor.","Release the feet and lower the legs."],"images":{"main":"images/flat/happy-baby-main.webp"}},{"id":"head-to-knee-pose","name":"Head-to-Knee Pose","bodyPart":"upper_legs","category":"stretching","muscles":["erector_spinae","hamstrings"],"steps":["Sit with one leg straight in front of you and the other knee bent out to the side, that foot at the inner thigh.","Turn the chest towards the straight leg so the navel lines up with the thigh.","Hinge from the hips and reach forward along the straight leg with a long spine.","Hold the fold for the prescribed time, breathing into the back of the leg.","Come up with a flat back and repeat on the other side."],"images":{"main":"images/flat/head-to-knee-pose-main.webp"}},{"id":"heel-elevated-squat","name":"Heel-Elevated Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Place weight plates or a wedge under your heels, feet shoulder-width apart.","Hold a barbell across your upper back or hold dumbbells at your sides.","Brace your core and descend into a squat, keeping your torso upright.","Squat until thighs are parallel to the floor or lower.","Drive through your feet to return to the starting position."],"images":{"start":"images/flat/heel-elevated-squat-start.webp","peak":"images/flat/heel-elevated-squat-peak.webp"}},{"id":"heel-flicks","name":"Heel Flicks","bodyPart":"full_body","category":"cardio","muscles":["hamstrings"],"steps":["Stand tall with the feet under the hips and the arms bent as for running.","Begin jogging lightly in place.","Flick one heel up towards the same-side glute without driving the knee forward.","Switch feet quickly and continue alternating at an even rhythm.","Stay light on the forefeet and keep the torso upright for the full interval."],"images":{"main":"images/flat/heel-flicks-main.webp"}},{"id":"heel-to-toe-walk","name":"Heel-to-Toe Walk","bodyPart":"lower_legs","category":"strength","muscles":["gluteus_medius","soleus"],"steps":["Pick a straight line on the floor and stand on it with your arms out to your sides at shoulder height.","Step forward and place your heel directly in front of — and touching — the toes of the standing foot.","Shift your weight onto the front foot under control, pausing for a moment before the next step.","Bring the back foot through and place it heel to toe again, staying on the line rather than stepping around it.","Look ahead at a fixed point instead of down at your feet, and use your arms to correct any wobble.","Walk the desired number of steps, then turn around and walk back."],"images":{"main":"images/flat/heel-to-toe-walk-main.webp"}},{"id":"heel-touches","name":"Heel Touches","bodyPart":"core","category":"strength","muscles":["obliques","rectus_abdominis"],"steps":["Lie on your back with the knees bent and the feet flat on the floor, about hip-width apart.","Lift the head and shoulders slightly off the floor and reach the arms down along your sides.","Crunch to one side and reach that hand toward the heel on the same side.","Return to the center and reach toward the opposite heel.","Keep alternating sides in a smooth rhythm while the lower back stays on the floor.","Continue for the desired number of repetitions."],"images":{"start":"images/flat/heel-touches-start.webp","peak":"images/flat/heel-touches-peak.webp"}},{"id":"hero-pose","name":"Hero Pose","bodyPart":"upper_legs","category":"stretching","muscles":["quadriceps"],"steps":["Kneel with the knees together and the feet slightly wider than the hips, tops of the feet flat.","Sit the hips back and down between the heels, using a block or cushion if the floor is out of reach.","Stack the ribs over the pelvis and rest the hands on the thighs.","Hold the seat for the prescribed time, keeping the weight even on both sit bones.","Come out by pressing into the hands and straightening one leg at a time."],"images":{"main":"images/flat/hero-pose-main.webp"}},{"id":"hex-bar-deadlift","name":"Hex Bar Deadlift","bodyPart":"back","category":"strength","equipment":"trap_bar","muscles":["erector_spinae","gluteus_maximus","quadriceps"],"steps":["Stand inside a loaded trap bar with feet shoulder-width apart.","Hinge at the hips and knees to grip the handles.","Brace your core and set your back flat.","Drive through your heels and extend hips and knees to stand up.","Lock out at the top with shoulders pulled back.","Lower the bar back to the floor under control."],"images":{"start":"images/flat/hex-bar-deadlift-start.webp","peak":"images/flat/hex-bar-deadlift-peak.webp"}},{"id":"high-foot-leg-press","name":"High-Foot Leg Press","bodyPart":"upper_legs","category":"strength","equipment":"leg_press","muscles":["gluteus_maximus"],"steps":["Set the back pad and seat so your lower back stays supported and your knees can bend without your pelvis rolling under.","Place both feet high on the platform at about shoulder width, with the toes tracking in the same direction as the knees.","Lower the sled by bending the hips and knees until you reach a comfortable depth without the lower back lifting from the pad.","Press through the whole foot and extend the hips and knees without locking the knees aggressively.","Lower the sled under control and repeat for the desired number of repetitions."],"images":{"start":"images/flat/high-foot-leg-press-start.webp","peak":"images/flat/high-foot-leg-press-peak.webp"}},{"id":"high-knees","name":"High Knees","bodyPart":"full_body","category":"cardio","muscles":["hip_flexors","quadriceps"],"steps":["Stand tall with feet hip-width apart.","Drive one knee up toward the chest while pumping the opposite arm.","Quickly switch legs, mirroring the arm action.","Continue alternating at a fast pace.","Continue for the prescribed work interval."],"images":{"main":"images/flat/high-knees-main.webp"}},{"id":"high-plank","name":"High Plank","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Start in a push-up position with arms fully extended.","Keep your body in a straight line from head to heels.","Brace your core and hold the position.","Breathe steadily throughout."],"images":{"main":"images/flat/high-plank-main.webp"}},{"id":"hip-abduction","name":"Machine Hip Abduction","bodyPart":"upper_legs","category":"strength","equipment":"hip_abduction_machine","muscles":["gluteus_medius"],"steps":["Sit in the hip abduction machine with pads against your outer thighs.","Push your legs apart against the resistance.","Hold briefly at the widest point.","Return to the starting position with control.","Repeat."],"images":{"start":"images/flat/hip-abduction-start.webp","peak":"images/flat/hip-abduction-peak.webp"}},{"id":"hip-adduction","name":"Hip Adduction","bodyPart":"upper_legs","category":"strength","equipment":"hip_adduction_machine","muscles":["adductors"],"steps":["Sit on the hip adduction machine with your back against the pad.","Place your legs against the pads with the machine set to a comfortable stretch.","Squeeze your legs together until the pads meet in the middle.","Hold the squeeze briefly in the fully closed position.","Let your legs open back out under control to the start.","Repeat for the desired number of reps."],"images":{"start":"images/flat/hip-adduction-start.webp","peak":"images/flat/hip-adduction-peak.webp"}},{"id":"hip-thrust","name":"Barbell Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","gluteus_medius"],"steps":["Sit on the floor with your upper back against a bench, barbell across your hips.","Drive your hips up until your thighs are parallel to the floor.","Squeeze your glutes at the top.","Lower your hips back down with control.","Repeat."],"images":{"start":"images/flat/hip-thrust-start.webp","peak":"images/flat/hip-thrust-peak.webp"}},{"id":"hollow-body-hold","name":"Hollow Body Hold","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Lie on your back with arms extended overhead and legs straight.","Press the lower back firmly into the floor.","Lift the shoulders, head, and legs slightly off the floor.","Hold the position with arms and legs extended, body in a shallow banana shape.","Hold for the prescribed time."],"images":{"main":"images/flat/hollow-body-hold-main.webp"}},{"id":"horizontal-leg-press","name":"Horizontal Leg Press","bodyPart":"upper_legs","category":"strength","equipment":"leg_press","muscles":["gluteus_maximus","quadriceps"],"steps":["Sit in a horizontal leg press with your back against the pad and your feet shoulder-width apart on the footplate.","Press through your feet to straighten your legs, stopping just short of locking the knees.","Bend your knees under control until they come toward your chest.","Repeat."],"images":{"start":"images/flat/horizontal-leg-press-start.webp","peak":"images/flat/horizontal-leg-press-peak.webp"}},{"id":"human-flag","name":"Human Flag","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi","obliques"],"steps":["Stand close to a sturdy vertical pole.","Grip the pole high with the top hand (overhand) and lower with the bottom hand (underhand).","Kick the legs up and out while pressing the bottom arm hard against the pole.","Extend the body horizontally so it forms a straight line parallel to the ground.","Hold the position with the body rigid for the target time.","Lower under control."],"images":{"main":"images/flat/human-flag-main.webp"}},{"id":"hyperextension-hold-bench","name":"Hyperextension Bench Hold","bodyPart":"back","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Adjust the bench so that the pad sits just below your hip bones and your heels are hooked firmly behind the roller or pad.","Cross your arms over your chest and lower your torso toward the floor with a straight back.","Raise your torso until your body is in one straight line from your head to your heels.","Stop in that line and hold, with your glutes squeezed and your neck in line with your spine.","Keep your breathing slow and do not arch your lower back past the straight line while you hold for the planned time.","Lower your torso under control and rest."],"images":{"main":"images/flat/hyperextension-hold-bench-main.webp"}},{"id":"inchworm","name":"Inchworm","bodyPart":"full_body","category":"strength","muscles":["hamstrings"],"steps":["Stand tall with your feet about hip-width apart.","Hinge forward at the hips and place your hands on the floor in front of your feet, bending the knees slightly if you need to.","Walk your hands forward one at a time, keeping your legs as straight as you comfortably can, until your body is in a straight line close to the floor.","Bend your elbows so your chest hovers just above the floor, as at the bottom of a push-up, and pause briefly with your trunk braced.","Walk your hands back toward your feet in small steps, raising your hips, until you are back in the forward fold.","Stand up, or go straight into the next repetition."],"images":{"start":"images/flat/inchworm-start.webp","peak":"images/flat/inchworm-peak.webp"}},{"id":"incline-bench-ez-bar-press","name":"Incline EZ-Bar Bench Press","bodyPart":"chest","category":"strength","equipment":"ez_bar","muscles":["pectoralis_major"],"steps":["Set bench to 30–45 degrees. Grip the EZ-bar with hands on the angled sections.","Lower the bar to your upper chest.","Press back up to full extension.","Repeat."],"images":{"start":"images/flat/incline-bench-ez-bar-press-start.webp","peak":"images/flat/incline-bench-ez-bar-press-peak.webp"}},{"id":"incline-bench-press","name":"Incline Barbell Bench Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Lie on an incline bench set to 30-45 degrees.","Grip the bar slightly wider than shoulder-width and unrack.","Lower the bar to your upper chest.","Press the bar back up to full extension.","Repeat."],"images":{"start":"images/flat/incline-bench-press-start.webp","peak":"images/flat/incline-bench-press-peak.webp"}},{"id":"incline-db-curl","name":"Incline Dumbbell Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Sit on an incline bench set to 45 degrees, holding dumbbells at your sides.","Let your arms hang straight down with palms forward.","Curl the dumbbells up toward your shoulders.","Lower with control to full extension.","Repeat."],"images":{"start":"images/flat/incline-db-curl-start.webp","peak":"images/flat/incline-db-curl-peak.webp"}},{"id":"incline-db-press","name":"Incline Dumbbell Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Set bench to 30-degree incline and sit back with dumbbells at shoulder level.","Press dumbbells up and together until arms are fully extended.","Lower dumbbells back to shoulder level with control.","Repeat."],"images":{"start":"images/flat/incline-db-press-start.webp","peak":"images/flat/incline-db-press-peak.webp"}},{"id":"incline-dumbbell-fly","name":"Incline Dumbbell Fly","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Lie back on an incline bench holding dumbbells above your chest.","Press the dumbbells up with palms facing each other.","Maintain a slight bend in your elbows throughout.","Lower the dumbbells in a wide arc until you feel a chest stretch.","Squeeze your chest to bring the dumbbells back together.","Repeat for the desired number of reps."],"images":{"start":"images/flat/incline-dumbbell-fly-start.webp","peak":"images/flat/incline-dumbbell-fly-peak.webp"}},{"id":"incline-hammer-curl","name":"Incline Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii","brachialis"],"steps":["Sit on an incline bench holding dumbbells with a neutral grip.","Allow arms to hang straight.","Curl the dumbbells up in a hammer motion.","Lower slowly.","Repeat."],"images":{"start":"images/flat/incline-hammer-curl-start.webp","peak":"images/flat/incline-hammer-curl-peak.webp"}},{"id":"incline-plank-hold","name":"Incline Plank Hold","bodyPart":"core","category":"strength","equipment":"flat_bench","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Place your forearms on a flat bench, with your elbows directly under your shoulders.","Step your feet back until your body forms a straight line from head to heels.","Squeeze your glutes and pull your belly button toward your spine to keep your hips level.","Keep your neck long and look at a point on the bench slightly ahead of your hands.","Hold the position for the planned time while breathing steadily.","Step your feet in to finish."],"images":{"main":"images/flat/incline-plank-hold-main.webp"}},{"id":"incline-push-ups","name":"Incline Push-Up","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Place your hands on a bench or elevated surface, shoulder-width apart.","Extend your legs behind you into a plank position.","Lower your chest toward the bench by bending your elbows.","Push back up to the starting position.","Repeat."],"images":{"start":"images/flat/incline-push-ups-start.webp","peak":"images/flat/incline-push-ups-peak.webp"}},{"id":"incline-treadmill-walk","name":"Incline Treadmill Walk","bodyPart":"full_body","category":"cardio","equipment":"treadmill","muscles":["gluteus_maximus","quadriceps"],"steps":["Start the belt at a slow walking speed and step on, then raise the incline to your target gradient.","Walk with a long, deliberate stride, rolling from heel to toe and pushing the belt away behind you with each step.","Stand tall and lean from the ankles with the hill rather than folding forward at the waist.","Keep at least one foot on the belt at all times — walk the hill, do not break into a jog.","Let your arms swing naturally, or rest them lightly on the rails for balance without carrying your weight on them.","Hold the gradient for the desired time, then lower the incline and walk level for a few minutes to finish."],"images":{"main":"images/flat/incline-treadmill-walk-main.webp"}},{"id":"inverted-row","name":"Inverted Row","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","rhomboids","trapezius"],"steps":["Set a barbell in a rack at about waist height.","Lie underneath and grip the bar slightly wider than shoulder-width with an overhand grip.","Hang with arms extended, heels on the floor, body straight from head to ankles.","Pull your chest to the bar, squeezing the shoulder blades together.","Lower yourself under control until arms are fully extended.","Repeat."],"images":{"start":"images/flat/inverted-row-start.webp","peak":"images/flat/inverted-row-peak.webp"}},{"id":"isometric-neck-side","name":"Isometric Neck Lateral Flexion","bodyPart":"shoulders","category":"strength","muscles":["trapezius"],"steps":["Sit or stand tall. Place the palm of one hand against the side of the head, above the ear.","Press the head into the hand while resisting equally with the hand — the head does not move.","Hold the isometric contraction for 5 to 10 seconds.","Release slowly, then repeat on the same side for the set.","Switch sides and repeat."],"images":{"main":"images/flat/isometric-neck-side-main.webp"}},{"id":"isometric-split-squat","name":"Isometric Split Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with one foot well forward and the other foot back, about a long stride apart, with your hands on your hips.","Keep your torso upright and lower straight down by bending both knees.","Lower until your front thigh is close to parallel with the floor and your back knee hovers just above the ground.","Keep your front heel flat and your front knee tracking over your toes.","Hold this position for the planned time, keeping your trunk tall and your weight spread through the front foot.","Press up to the top, then repeat on the other leg."],"images":{"main":"images/flat/isometric-split-squat-main.webp"}},{"id":"jackknife-sit-up","name":"Jackknife Sit-Up","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Lie face-up on the floor with arms extended overhead and legs extended straight.","Simultaneously lift the torso and the straight legs off the floor.","Reach the hands up toward the feet as the feet rise — meet above the hips.","Lower the torso and legs back to the floor under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/jackknife-sit-up-start.webp","peak":"images/flat/jackknife-sit-up-peak.webp"}},{"id":"jefferson-curl","name":"Jefferson Curl","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["erector_spinae","hamstrings"],"steps":["Stand tall holding a light dumbbell with straight arms, feet roughly hip-width.","Tuck your chin and begin rounding the spine from the top, one vertebra at a time.","Curl down slowly, letting the weight hang and keeping the legs mostly straight.","Reach the bottom with the back fully rounded and a stretch through the hamstrings.","Reverse it, restacking the spine from the bottom up back to standing."],"images":{"start":"images/flat/jefferson-curl-start.webp","peak":"images/flat/jefferson-curl-peak.webp"}},{"id":"jump-rope","name":"Jump Rope","bodyPart":"full_body","category":"cardio","equipment":"jump_rope","muscles":["gastrocnemius","soleus"],"steps":["Hold a jump rope handle in each hand with the rope behind you.","Swing the rope overhead and forward in a smooth arc.","Hop just high enough for the rope to pass under your feet.","Land softly on the balls of the feet, knees slightly bent.","Keep a steady rhythm for the prescribed interval."],"images":{"main":"images/flat/jump-rope-main.webp"}},{"id":"jump-squat","name":"Jump Squat","bodyPart":"upper_legs","category":"plyometrics","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet shoulder-width apart.","Drop into a quarter-squat with the arms back.","Explode upward, swinging the arms up and jumping as high as you can.","Land softly back into a quarter-squat to absorb impact.","Repeat without pausing for the prescribed reps."],"images":{"start":"images/flat/jump-squat-start.webp","peak":"images/flat/jump-squat-peak.webp"}},{"id":"jumping-jacks","name":"Jumping Jacks","bodyPart":"full_body","category":"cardio","muscles":["gastrocnemius","gluteus_medius","lateral_deltoid"],"steps":["Stand tall with feet together and arms at your sides.","Simultaneously jump your feet out wide and raise your arms overhead.","Ensure your arms meet or nearly meet above your head.","Jump your feet back together while lowering your arms to your sides.","Maintain a continuous, rhythmic motion."],"images":{"start":"images/flat/jumping-jacks-start.webp","peak":"images/flat/jumping-jacks-peak.webp"}},{"id":"kb-step-up-to-balance","name":"Kettlebell Step-Up to Balance","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing a low, stable step or bench with a kettlebell in each hand, arms hanging at your sides.","Place one foot flat on top of the step.","Press through the whole of the front foot and straighten that leg to lift your body onto the step.","As you rise, drive the other knee up in front of you until the thigh is about hip height.","Stand tall on the working leg and hold the knee-up position for a moment without leaning back.","Lower the free foot back to the floor under control, then step the working leg down as well and repeat; switch legs after the planned repetitions."],"images":{"start":"images/flat/kb-step-up-to-balance-start.webp","peak":"images/flat/kb-step-up-to-balance-peak.webp"}},{"id":"kettlebell-bottoms-up-hold","name":"Kettlebell Bottoms-Up Hold","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","forearm_flexors"],"steps":["Clean a kettlebell to your shoulder and flip it so that the bell points up and the handle sits in your fist.","Stand with your feet about shoulder-width apart and your free arm relaxed at your side.","Keep your forearm vertical and your elbow close to your ribs, with the bell directly above your hand.","Grip the handle firmly and keep your wrist straight, as if you were balancing a cup.","Hold the bell steady for the planned time, breathing slowly and keeping your shoulder down.","Lower the kettlebell with control, turn it the right way up and switch arms."],"images":{"main":"images/flat/kettlebell-bottoms-up-hold-main.webp"}},{"id":"kettlebell-bulgarian-split-squat","name":"Kettlebell Bulgarian Split Squat","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing away from a bench, placing one foot on it behind you, laces down. Hold a kettlebell in each hand at your sides.","Maintain an upright torso and engage your core.","Lower your body by bending both knees, allowing your front knee to track over your toes.","Descend until your front thigh is parallel to the floor or slightly below, keeping your rear knee close to the ground.","Drive through your front heel to return to the starting position, extending your hips and knees.","Complete all reps per side before switching."],"images":{"start":"images/flat/kettlebell-bulgarian-split-squat-start.webp","peak":"images/flat/kettlebell-bulgarian-split-squat-peak.webp"}},{"id":"kettlebell-close-grip-floor-press","name":"Kettlebell Close-Grip Floor Press","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["triceps_brachii"],"steps":["Lie on your back on the floor with the knees bent and feet flat.","Hold a single kettlebell by the handle with both hands, close together, the bell resting on the chest with elbows tucked tight to the ribs.","Brace the core and press the kettlebell straight up until the arms are fully extended.","Lower under control until the upper arms touch the floor and pause briefly.","Press back up to lockout.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-close-grip-floor-press-start.webp","peak":"images/flat/kettlebell-close-grip-floor-press-peak.webp"}},{"id":"kettlebell-concentration-curl","name":"Kettlebell Concentration Curl","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["biceps_brachii"],"steps":["Sit on a bench with your feet wide, holding a kettlebell in one hand.","Brace the back of your upper arm against the inside of your thigh, letting the kettlebell hang.","Curl the kettlebell up toward your shoulder, keeping the elbow pinned against your leg.","Squeeze the bicep at the top, then lower slowly under control.","Finish all reps on one side, then switch arms."],"images":{"start":"images/flat/kettlebell-concentration-curl-start.webp","peak":"images/flat/kettlebell-concentration-curl-peak.webp"}},{"id":"kettlebell-curl","name":"Kettlebell Curl","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["biceps_brachii"],"steps":["Stand with your feet about shoulder-width apart and hold the kettlebell by its handle with both hands, so it hangs in front of your thighs.","Keep your elbows close to your sides, your chest tall and your shoulders relaxed.","Bend your elbows and curl the kettlebell up toward your chest without letting your upper arms swing forward.","Squeeze your biceps at the top, with the kettlebell close to your chest.","Lower the kettlebell slowly until your arms are straight again, keeping control of the swing of the bell.","Repeat for the planned repetitions."],"images":{"start":"images/flat/kettlebell-curl-start.webp","peak":"images/flat/kettlebell-curl-peak.webp"}},{"id":"kettlebell-curl-iso-hold","name":"Kettlebell Curl Iso Hold","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["biceps_brachii","brachialis"],"steps":["Stand with your feet about shoulder-width apart and hold the kettlebell by its handle with both hands, so it hangs in front of your thighs.","Keep your elbows close to your sides and your shoulders relaxed.","Curl the kettlebell up until your forearms are level with the floor and the elbows are bent to about 90 degrees.","Stop there and hold the kettlebell steady, hanging in front of your body.","Keep your upper arms still, your chest tall and your breathing slow while you hold for the planned time.","Lower the kettlebell under control and rest."],"images":{"main":"images/flat/kettlebell-curl-iso-hold-main.webp"}},{"id":"kettlebell-deadlift","name":"Kettlebell Deadlift","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["erector_spinae","gluteus_maximus","hamstrings"],"steps":["Stand with feet shoulder-width apart and kettlebell between your feet.","Hinge at the hips and bend your knees to grip the handle.","Brace your core and set your back flat.","Drive through your heels to stand up with the kettlebell.","Lock out at the top with shoulders pulled back.","Lower the kettlebell back to the floor with control."],"images":{"start":"images/flat/kettlebell-deadlift-start.webp","peak":"images/flat/kettlebell-deadlift-peak.webp"}},{"id":"kettlebell-farmers-walk","name":"Kettlebell Farmer's Walk","bodyPart":"full_body","category":"strength","equipment":"kettlebell","muscles":["forearm_flexors","trapezius"],"steps":["Stand between two heavy kettlebells.","Hinge and grip the handles firmly with a neutral grip.","Stand tall with shoulders back and core braced.","Walk forward with short, controlled steps.","Maintain an upright posture throughout the walk.","Set the weights down at the end of the distance."],"images":{"main":"images/flat/kettlebell-farmers-walk-main.webp"}},{"id":"kettlebell-floor-press","name":"Kettlebell Floor Press","bodyPart":"chest","category":"strength","equipment":"kettlebell","muscles":["pectoralis_major"],"steps":["Lie on your back on the floor with knees bent, feet flat.","Hold a kettlebell in each hand at the chest, bells resting on the outer forearms.","Press both kettlebells straight up until the arms are fully extended.","Lower under control until the triceps touch the floor — do not bounce.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-floor-press-start.webp","peak":"images/flat/kettlebell-floor-press-peak.webp"}},{"id":"kettlebell-goblet-lunge","name":"Kettlebell Goblet Lunge","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall holding a kettlebell by its horns at chest height, elbows tucked, in the goblet position.","Take a controlled step forward with one leg, lowering your hips until both knees are bent at approximately 90 degrees.","Ensure your front knee is stacked over your ankle and your rear knee hovers just above the floor.","Drive through your front heel to return to the starting position, maintaining balance and core tension.","Complete all repetitions on one side before switching, or alternate legs per set."],"images":{"start":"images/flat/kettlebell-goblet-lunge-start.webp","peak":"images/flat/kettlebell-goblet-lunge-peak.webp"}},{"id":"kettlebell-halo","name":"Kettlebell Halo","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["lateral_deltoid"],"steps":["Stand tall, core braced, holding a light kettlebell by the horns (upside down) at chest height.","Raise the bell to one side of your head and pass it around the back in a smooth circle.","Bring it back to the starting position in front of your face.","Reverse direction every few reps.","Repeat for the recommended number of repetitions or time."],"images":{"start":"images/flat/kettlebell-halo-start.webp","peak":"images/flat/kettlebell-halo-peak.webp"}},{"id":"kettlebell-hammer-curl","name":"Kettlebell Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["biceps_brachii","brachialis"],"steps":["Stand holding a kettlebell in each hand, gripping the handles in a neutral position (palms facing the body).","Let the bells hang below your hands.","Keep the elbows tucked to the sides and curl both bells up toward the shoulders.","Squeeze at the top, then lower under control.","Repeat for the planned number of reps."],"images":{"start":"images/flat/kettlebell-hammer-curl-start.webp","peak":"images/flat/kettlebell-hammer-curl-peak.webp"}},{"id":"kettlebell-hip-thrust","name":"Kettlebell Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus"],"steps":["Sit on the floor with your upper back against a bench, knees bent, and feet flat.","Place a kettlebell across your hips, holding it securely with both hands.","Drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes forcefully at the top of the movement.","Slowly lower your hips back down to the starting position with control."],"images":{"start":"images/flat/kettlebell-hip-thrust-start.webp","peak":"images/flat/kettlebell-hip-thrust-peak.webp"}},{"id":"kettlebell-kickstand-deadlift","name":"Kettlebell Kickstand Deadlift","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Set a kettlebell on the floor beside the front foot and step the other foot back so only its toes touch the floor.","Hinge at the hips with a flat back and grip the kettlebell handle with one hand.","Drive through the front heel and extend the hips to stand tall, the kettlebell at your side.","Keep most of your weight on the front foot throughout.","Hinge back down, lowering the kettlebell toward the floor with a flat back. Switch sides after all reps."],"images":{"start":"images/flat/kettlebell-kickstand-deadlift-start.webp","peak":"images/flat/kettlebell-kickstand-deadlift-peak.webp"}},{"id":"kettlebell-lunge-press","name":"Kettlebell Lunge Press","bodyPart":"full_body","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","gluteus_maximus","quadriceps"],"steps":["Hold a kettlebell at shoulder height with one arm.","Step forward into a lunge with the opposite leg.","As you lunge, press the kettlebell overhead.","Lock out the arm at the top of the press.","Step back to standing while lowering the kettlebell.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-lunge-press-start.webp","peak":"images/flat/kettlebell-lunge-press-peak.webp"}},{"id":"kettlebell-offset-reverse-lunge-and-press","name":"Kettlebell Offset Reverse Lunge and Press","bodyPart":"full_body","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","gluteus_maximus","quadriceps"],"steps":["Hold a kettlebell at shoulder height on one side.","Step backward into a reverse lunge with the opposite leg.","As you reach the bottom of the lunge, press the kettlebell overhead.","Drive through your front heel to return to standing.","Lower the kettlebell back to shoulder height.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-offset-reverse-lunge-and-press-start.webp","peak":"images/flat/kettlebell-offset-reverse-lunge-and-press-peak.webp"}},{"id":"kettlebell-overhead-carry","name":"Kettlebell Overhead Carry","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Clean and press a kettlebell to lockout, letting the bell settle on the back of your forearm.","Straighten the elbow fully and turn the arm so the bell sits behind and above your wrist rather than off to the side.","Keep the shoulder active: push the weight up toward the ceiling and let the shoulder blade rotate up with it rather than forcing it down.","Brace your trunk and walk forward with even strides, keeping the bell stacked over your shoulder and hip.","Keep your wrist straight; letting it bend back is what makes an overhead bell feel unstable.","Carry for the desired distance, lower under control, then repeat on the other side."],"images":{"main":"images/flat/kettlebell-overhead-carry-main.webp"}},{"id":"kettlebell-overhead-hold","name":"Kettlebell Overhead Hold","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Clean or press a kettlebell up so that your arm is straight overhead with the bell resting against the back of your forearm.","Stand with your feet about shoulder-width apart and your free arm relaxed at your side.","Lock out your elbow and push your hand up toward the ceiling so that your upper arm stays next to your ear.","Squeeze your glutes and brace your core so that your ribs do not flare and your lower back stays neutral.","Hold the bell steady over your shoulder for the planned time, breathing slowly.","Lower the kettlebell back to the rack position with control and switch arms."],"images":{"main":"images/flat/kettlebell-overhead-hold-main.webp"}},{"id":"kettlebell-overhead-tricep-extension","name":"Kettlebell Overhead Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["triceps_brachii"],"steps":["Stand or sit holding a kettlebell by the horns (upside down) with both hands overhead.","Arms fully extended, bell above the head.","Bend only the elbows to lower the bell behind the head in a controlled arc.","Keep the upper arms vertical and close to the head; only the forearms move.","Extend the elbows to return the bell overhead.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-overhead-tricep-extension-start.webp","peak":"images/flat/kettlebell-overhead-tricep-extension-peak.webp"}},{"id":"kettlebell-pistol-squat","name":"Kettlebell Pistol Squat","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Hold a kettlebell at your chest with both hands.","Stand on one leg with the other leg extended forward.","Lower your hips down into a one-legged squat.","Keep your raised leg off the floor throughout.","Drive through your standing heel to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-pistol-squat-start.webp","peak":"images/flat/kettlebell-pistol-squat-peak.webp"}},{"id":"kettlebell-pullover","name":"Kettlebell Pullover","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie on a flat bench holding a kettlebell by the horns with both hands above the chest, arms nearly straight (slight elbow bend).","Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms are in line with the torso.","Pull the bell back above the chest along the same arc.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-pullover-start.webp","peak":"images/flat/kettlebell-pullover-peak.webp"}},{"id":"kettlebell-rack-hold","name":"Kettlebell Rack Hold","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid"],"steps":["Clean a kettlebell to your shoulder so that the bell rests against the back of your forearm and your upper arm, with the handle in your palm.","Stand with your feet about shoulder-width apart and your free arm relaxed at your side.","Keep your elbow close to your ribs and your wrist straight, so that the bell sits on your chest and shoulder, not on your wrist.","Stand tall, squeeze your glutes and brace your core without leaning away from the bell.","Hold the position for the planned time, breathing slowly.","Lower the kettlebell to the floor with control and switch arms."],"images":{"main":"images/flat/kettlebell-rack-hold-main.webp"}},{"id":"kettlebell-reverse-lunge","name":"Kettlebell Reverse Lunge","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall holding a kettlebell by the horns at your chest, elbows tucked in (goblet hold).","Step one leg straight back, lowering your hips until both knees are bent at approximately 90 degrees.","Keep your front shin vertical and your chest upright, ensuring your back knee hovers just above the floor.","Drive through your front heel to return to the starting position.","Complete all reps per side before switching to the other side."],"images":{"start":"images/flat/kettlebell-reverse-lunge-start.webp","peak":"images/flat/kettlebell-reverse-lunge-peak.webp"}},{"id":"kettlebell-reverse-wrist-curl","name":"Kettlebell Reverse Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"kettlebell","muscles":["forearm_extensors"],"steps":["Sit on a bench with your forearms on your thighs, palms down.","Hold one kettlebell by the handle with both hands, with the wrists hanging off the knees.","Let the wrists drop, lowering the kettlebell.","Lift the backs of the hands by extending the wrists.","Lower under control and repeat for the planned reps."],"images":{"start":"images/flat/kettlebell-reverse-wrist-curl-start.webp","peak":"images/flat/kettlebell-reverse-wrist-curl-peak.webp"}},{"id":"kettlebell-rotational-lunge","name":"Kettlebell Rotational Lunge","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Hold a kettlebell with both hands at your chest.","Step back into a lunge, lowering until both knees are bent.","Rotate your torso toward the front leg.","Move the kettlebell to that side at chest to shoulder height, arms almost straight.","Rotate back to the center and push through the front foot to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-rotational-lunge-start.webp","peak":"images/flat/kettlebell-rotational-lunge-peak.webp"}},{"id":"kettlebell-russian-twist","name":"Kettlebell Russian Twist","bodyPart":"core","category":"strength","equipment":"kettlebell","muscles":["obliques"],"steps":["Sit on the floor with your knees bent and feet lifted off the ground.","Hold a kettlebell with both hands in front of your chest.","Lean back slightly to engage your core.","Rotate your torso to one side, bringing the kettlebell next to your hip.","Rotate to the opposite side in a controlled motion.","Repeat for the desired number of reps."],"images":{"start":"images/flat/kettlebell-russian-twist-start.webp","peak":"images/flat/kettlebell-russian-twist-peak.webp"}},{"id":"kettlebell-shrug","name":"Kettlebell Shrug","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["trapezius"],"steps":["Stand tall with feet hip-width apart, holding a kettlebell in each hand with palms facing your body.","Keep your arms straight and shoulders relaxed.","Elevate your shoulders straight up towards your ears, squeezing your traps at the top.","Hold the contraction briefly.","Slowly lower your shoulders back to the starting position with control.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/kettlebell-shrug-start.webp","peak":"images/flat/kettlebell-shrug-peak.webp"}},{"id":"kettlebell-single-leg-deadlift","name":"Kettlebell Single Leg Deadlift","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Hold a kettlebell in one hand and stand on the opposite leg.","Hinge at the hip and lower the kettlebell toward the floor.","Extend your free leg straight back for balance.","Lower until your torso is parallel to the floor.","Drive through your standing heel to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-single-leg-deadlift-start.webp","peak":"images/flat/kettlebell-single-leg-deadlift-peak.webp"}},{"id":"kettlebell-skull-crusher","name":"Kettlebell Skull Crusher","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["triceps_brachii"],"steps":["Lie on your back on the floor with your knees bent and feet flat, holding a kettlebell by the horns with both hands, arms extended above the chest.","Bend the elbows to lower the bell in a controlled arc past your forehead to behind your head, until it nearly touches the floor.","Keep the upper arms still, angled slightly back toward your head; only the forearms move.","Extend the elbows to press the bell back up.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-skull-crusher-start.webp","peak":"images/flat/kettlebell-skull-crusher-peak.webp"}},{"id":"kettlebell-squat","name":"Kettlebell Squat","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["quadriceps"],"steps":["Stand with feet shoulder-width apart, holding a kettlebell with both hands in front of you.","Let the kettlebell hang naturally between your legs as you brace your core.","Bend your hips and knees to squat down, keeping the kettlebell close to your body.","Drive through your feet to stand back up to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/kettlebell-squat-start.webp","peak":"images/flat/kettlebell-squat-peak.webp"}},{"id":"kettlebell-sumo-deadlift","name":"Kettlebell Sumo Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in a wide stance with toes pointed slightly out, a kettlebell on the floor between the feet.","Hinge down with a flat back, knees tracking over the toes, and grip the handle with both hands.","Drive through the floor and extend the hips and knees together to stand up.","Squeeze the glutes at the top.","Lower the bell under control back to the floor by pushing the hips back.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-sumo-deadlift-start.webp","peak":"images/flat/kettlebell-sumo-deadlift-peak.webp"}},{"id":"kettlebell-sumo-high-pull","name":"Kettlebell Sumo High Pull","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["adductors","lateral_deltoid","trapezius"],"steps":["Stand with feet wider than shoulder-width, toes slightly turned out, a kettlebell on the floor between the feet.","Hinge down and grip the handle with both hands.","Drive through the feet and extend the hips explosively to pull the kettlebell up.","As it rises, pull the elbows up and out until the handle reaches chin height.","Lower the kettlebell back between the legs under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kettlebell-sumo-high-pull-start.webp","peak":"images/flat/kettlebell-sumo-high-pull-peak.webp"}},{"id":"kettlebell-svend-press","name":"Kettlebell Svend Press","bodyPart":"chest","category":"strength","equipment":"kettlebell","muscles":["pectoralis_major"],"steps":["Stand holding one kettlebell by the handle with both hands at chest height, the bell hanging below your hands.","Squeeze your hands together on the handle to tense the chest.","Press the kettlebell forward until your arms are almost straight.","Pull it back to the chest under control.","Repeat for the prescribed reps."],"images":{"start":"images/flat/kettlebell-svend-press-start.webp","peak":"images/flat/kettlebell-svend-press-peak.webp"}},{"id":"kettlebell-swing","name":"Kettlebell Swing","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with feet shoulder-width apart, kettlebell on the floor in front.","Hinge at the hips, grip the kettlebell, and hike it back between your legs.","Explosively drive your hips forward to swing the kettlebell to chest height.","Let the kettlebell swing back between your legs.","Repeat in a fluid motion."],"images":{"start":"images/flat/kettlebell-swing-start.webp","peak":"images/flat/kettlebell-swing-peak.webp"}},{"id":"kettlebell-swing-clean","name":"Kettlebell Swing Clean","bodyPart":"full_body","category":"olympic","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with feet shoulder-width apart, kettlebell between your feet.","Hinge at the hips and grip the handle with one hand.","Swing the kettlebell back between your legs.","Drive your hips forward to pull the kettlebell up to your shoulder.","Catch the kettlebell in the rack position on your shoulder.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-swing-clean-start.webp","peak":"images/flat/kettlebell-swing-clean-peak.webp"}},{"id":"kettlebell-tibialis-raise","name":"Kettlebell Tibialis Raise","bodyPart":"lower_legs","category":"strength","equipment":"kettlebell","muscles":["tibialis_anterior"],"steps":["Sit at the end of a flat bench with one leg extended and the heel resting on the floor.","Hang a kettlebell by its handle from the front of the foot, over the toes.","Pull the toes up toward the shin as far as is comfortable while the heel stays on the floor.","Hold briefly at the top.","Lower the foot slowly until the toes point toward the floor.","Complete the repetitions, then switch legs."],"images":{"start":"images/flat/kettlebell-tibialis-raise-start.webp","peak":"images/flat/kettlebell-tibialis-raise-peak.webp"}},{"id":"kettlebell-turkish-get-ups","name":"Kettlebell Turkish Get Ups","bodyPart":"full_body","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","gluteus_maximus","rectus_abdominis"],"steps":["Lie on your back holding a kettlebell pressed overhead in one hand.","Bend the knee on the same side and plant the foot flat.","Roll up onto your opposite elbow, then to your hand.","Drive your hips up and sweep your straight leg back into a lunge.","Stand up fully while keeping the kettlebell locked out overhead.","Reverse the sequence to return to the start."],"images":{"start":"images/flat/kettlebell-turkish-get-ups-start.webp","peak":"images/flat/kettlebell-turkish-get-ups-peak.webp"}},{"id":"kettlebell-windmills","name":"Kettlebell Windmills","bodyPart":"full_body","category":"strength","equipment":"kettlebell","muscles":["adductors","anterior_deltoid","obliques"],"steps":["Stand holding a kettlebell locked out overhead in one hand.","Turn your feet about 45 degrees away from the working arm.","Keeping the kettlebell up, hinge at the hips sideways.","Reach your opposite hand down toward your foot.","Drive your hips back to stand up tall.","Complete reps on one side, then switch."],"images":{"start":"images/flat/kettlebell-windmills-start.webp","peak":"images/flat/kettlebell-windmills-peak.webp"}},{"id":"kettlebell-wrist-curl","name":"Kettlebell Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"kettlebell","muscles":["forearm_flexors"],"steps":["Sit on a bench with your forearms on your thighs, palms up.","Hold a kettlebell by the handle in each hand, with the wrists hanging off the knees.","Let the kettlebells rotate down toward the fingertips.","Curl them up by flexing the wrists, controlling the offset weight.","Lower under control and repeat for the planned reps."],"images":{"start":"images/flat/kettlebell-wrist-curl-start.webp","peak":"images/flat/kettlebell-wrist-curl-peak.webp"}},{"id":"knee-push-ups","name":"Knee Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Start in a push-up position with your knees on the floor.","Place your hands shoulder-width apart on the ground.","Keep your body in a straight line from knees to shoulders.","Lower your chest toward the floor by bending your elbows.","Press through your hands to return to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/knee-push-ups-start.webp","peak":"images/flat/knee-push-ups-peak.webp"}},{"id":"knee-to-chest-stretch","name":"Knee-to-Chest Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["gluteus_maximus"],"steps":["Lie on your back with both legs straight.","Pull one knee in and hug it to your chest with both hands.","Keep the other leg relaxed on the floor.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/knee-to-chest-stretch-main.webp"}},{"id":"kneeling-cable-row","name":"Kneeling Cable Row","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi"],"steps":["Set a cable pulley to about chest height and attach a rope or double-D handle.","Kneel upright facing the stack far enough back that the weight stack doesn't bottom out.","Grab the handle with both hands and hold it out in front at chest height.","Row the handle to the sternum by driving the elbows back and squeezing the shoulder blades together.","Return under control to the stretched starting position.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/kneeling-cable-row-start.webp","peak":"images/flat/kneeling-cable-row-peak.webp"}},{"id":"kneeling-hip-flexor-stretch","name":"Kneeling Hip Flexor Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors"],"steps":["Kneel on one knee with the other foot flat in front.","Keep your torso upright and core gently braced.","Press your hips forward until the front of the rear hip stretches.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/kneeling-hip-flexor-stretch-main.webp"}},{"id":"kneeling-wrist-stretch","name":"Kneeling Wrist Stretch","bodyPart":"lower_arms","category":"stretching","muscles":["forearm_flexors"],"steps":["Kneel on all fours and place your palms flat on the floor.","Turn your hands so the fingers point back toward your knees.","Keep your palms down and rock your weight back gently.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/kneeling-wrist-stretch-main.webp"}},{"id":"l-sit","name":"L Sit","bodyPart":"full_body","category":"strength","equipment":"dip_station","muscles":["hip_flexors","rectus_abdominis"],"steps":["Sit on the floor or press up on parallel bars with arms straight.","Lock your elbows and depress your shoulders.","Lift your legs straight out in front of you parallel to the floor.","Form an L shape with your body.","Hold the position for the prescribed duration.","Lower your legs with control to exit."],"images":{"main":"images/flat/l-sit-main.webp"}},{"id":"landmine-press","name":"Landmine Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Load one end of a barbell into a landmine attachment and load the other end with a plate.","Stand in a staggered or square stance and cup the sleeve end of the barbell in both hands at chest height.","Brace your core and press the bar forward and upward along its natural arc.","Fully extend your arms without locking the elbows, then lower the bar back under control.","Keep both hands on the bar throughout and repeat for the desired number of reps."],"images":{"start":"images/flat/landmine-press-start.webp","peak":"images/flat/landmine-press-peak.webp"}},{"id":"landmine-single-arm-overhead-hold","name":"Landmine Single-Arm Overhead Hold","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid"],"steps":["Set one end of a barbell in a landmine post or in a corner and stand facing the free end in a staggered stance, feet about shoulder-width apart.","Hold the end of the bar with one hand at the shoulder and keep your other hand on your hip.","Press the bar up and forward until your arm is straight and your hand is above and slightly in front of your shoulder.","Lock out your elbow and push your shoulder blade around your ribs without shrugging.","Hold the bar steady for the planned time, with your trunk braced so that you do not lean to the side.","Lower the bar to your shoulder under control and switch arms."],"images":{"main":"images/flat/landmine-single-arm-overhead-hold-main.webp"}},{"id":"lat-pulldown","name":"Lat Pulldown","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi"],"steps":["Sit at the lat pulldown machine with thighs secured under the pads.","Grip the wide bar with an overhand grip.","Pull the bar down to your upper chest, squeezing your lats.","Slowly return the bar to the starting position.","Repeat."],"images":{"start":"images/flat/lat-pulldown-start.webp","peak":"images/flat/lat-pulldown-peak.webp"}},{"id":"lateral-leg-swing","name":"Lateral Leg Swing","bodyPart":"upper_legs","category":"stretching","muscles":["abductors","adductors"],"steps":["Stand tall and brace the trunk, using a stable support if needed.","Shift the weight onto one leg and lift the other foot slightly from the floor.","Swing the free leg across the front of the body.","Reverse the motion and swing it out to the side through a comfortable range.","Continue smoothly, then change legs."],"images":{"start":"images/flat/lateral-leg-swing-start.webp","peak":"images/flat/lateral-leg-swing-peak.webp"}},{"id":"lateral-raise","name":"Dumbbell Lateral Raise","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["lateral_deltoid"],"steps":["Stand holding dumbbells at your sides.","Raise the dumbbells out to the sides until arms are parallel to the floor.","Lower under control.","Repeat."],"images":{"start":"images/flat/lateral-raise-start.webp","peak":"images/flat/lateral-raise-peak.webp"}},{"id":"lean-back-90-90-hold","name":"Lean-Back 90/90 Hold","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors"],"steps":["Sit on the floor with your front leg bent in front of you to about 90 degrees and your back leg out to the side, also bent to about 90 degrees.","Place your hands on the floor behind your hips, fingers pointing back or to the side.","Lean your trunk back onto your hands, keeping your arms straight and your chest open.","Let both knees settle toward the floor without forcing them.","Hold the position, breathing slowly, feeling a mild stretch in the outer hip of the front leg and the front of the hip of the back leg.","Hold for the planned time, then switch the legs and hold on the other side."],"images":{"main":"images/flat/lean-back-90-90-hold-main.webp"}},{"id":"leg-curl","name":"Lying Leg Curl","bodyPart":"upper_legs","category":"strength","equipment":"leg_curl","muscles":["hamstrings"],"steps":["Lie face down on the leg curl machine with ankles under the pad.","Curl your heels toward your glutes.","Squeeze your hamstrings at the top.","Lower with control.","Repeat."],"images":{"start":"images/flat/leg-curl-start.webp","peak":"images/flat/leg-curl-peak.webp"}},{"id":"leg-extension","name":"Leg Extension","bodyPart":"upper_legs","category":"strength","equipment":"leg_extension","muscles":["quadriceps"],"steps":["Sit in the leg extension machine with ankles behind the pad.","Extend your legs until they are straight.","Squeeze your quads at the top.","Lower with control.","Repeat."],"images":{"start":"images/flat/leg-extension-start.webp","peak":"images/flat/leg-extension-peak.webp"}},{"id":"leg-press","name":"Leg Press","bodyPart":"upper_legs","category":"strength","equipment":"leg_press","muscles":["gluteus_maximus","quadriceps"],"steps":["Sit in the leg press machine with feet shoulder-width apart on the platform.","Release the safety catches and lower the platform by bending your knees.","Push the platform back up until legs are nearly straight.","Do not lock your knees at the top.","Repeat."],"images":{"start":"images/flat/leg-press-start.webp","peak":"images/flat/leg-press-peak.webp"}},{"id":"leg-swing-front-to-back","name":"Front-to-Back Leg Swing","bodyPart":"upper_legs","category":"stretching","muscles":["gluteus_maximus","hip_flexors"],"steps":["Stand tall beside a stable support and shift the weight onto the inside leg.","Brace the trunk and lift the outside foot slightly from the floor.","Swing the free leg forwards through a comfortable range.","Let it travel back behind the body without arching the lower back.","Continue smoothly, then repeat with the other leg."],"images":{"start":"images/flat/leg-swing-front-to-back-start.webp","peak":"images/flat/leg-swing-front-to-back-peak.webp"}},{"id":"legs-up-the-wall","name":"Legs-Up-the-Wall Pose","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings"],"steps":["Sit sideways next to a wall with one hip touching it.","Swing the legs up the wall as you lie back, so the hips end close to the base of the wall.","Let the legs rest against the wall with the feet relaxed and the arms open at the sides.","Stay for the prescribed time, breathing slowly.","Bend the knees and roll to one side to come out."],"images":{"main":"images/flat/legs-up-the-wall-main.webp"}},{"id":"lizard-stretch","name":"Lizard Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["adductors","hip_flexors"],"steps":["Step one foot forward into a deep lunge, foot placed wide.","Lower both forearms toward the floor inside the front foot.","Extend the back leg straight and let the hips sink.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/lizard-stretch-main.webp"}},{"id":"locust-pose","name":"Locust Pose","bodyPart":"back","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Lie face down with the arms alongside the body and the forehead on the mat.","Lengthen the back of the neck and reach the fingertips towards the feet.","Lift the chest, arms and both legs off the floor at the same time.","Hold the lifted position for the prescribed time, keeping the gaze down.","Lower everything down together and rest."],"images":{"main":"images/flat/locust-pose-main.webp"}},{"id":"low-lunge","name":"Low Lunge","bodyPart":"upper_legs","category":"stretching","muscles":["hip_flexors","quadriceps"],"steps":["From kneeling, step one foot forward so the knee stacks over the ankle.","Lower the back knee to the floor and untuck that foot.","Tuck the tailbone slightly and press the hips forward until you feel the front of the back thigh lengthen.","Lift the chest, raise the arms if it feels good, and hold for the prescribed time.","Step back and repeat on the other side."],"images":{"main":"images/flat/low-lunge-main.webp"}},{"id":"low-lunge-to-half-split","name":"Low Lunge to Half Split","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings"],"steps":["Start in a low lunge with the back knee on the floor and the front knee over the ankle.","Press the hands into the floor or onto blocks either side of the front foot.","Shift the hips back over the back knee and straighten the front leg, flexing that foot.","Hold the half split briefly, then glide the hips forward into the low lunge again.","Repeat for the desired number of repetitions and change sides."],"images":{"start":"images/flat/low-lunge-to-half-split-start.webp","peak":"images/flat/low-lunge-to-half-split-peak.webp"}},{"id":"lunge","name":"Lunge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall with your feet hip-width apart.","Step forward with one leg into a long stride.","Lower your back knee toward the floor until both knees form 90-degree angles.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/lunge-start.webp","peak":"images/flat/lunge-peak.webp"}},{"id":"lying-leg-raise","name":"Lying Leg Raise","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie flat on your back with legs straight and hands under your lower back or gripping a stable surface behind your head.","Keeping your legs together and core braced, raise them to vertical (or as high as flexibility allows).","Pause briefly at the top.","Lower your legs slowly toward the floor without letting them touch.","Repeat for the desired reps."],"images":{"start":"images/flat/lying-leg-raise-start.webp","peak":"images/flat/lying-leg-raise-peak.webp"}},{"id":"lying-quad-stretch","name":"Lying Quad Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["quadriceps"],"steps":["Lie on your side with your legs straight and your head resting on your lower arm.","Bend your top knee and take hold of that foot or ankle with your top hand.","Gently pull your heel toward your glute, keeping your knees close together.","Tuck your pelvis slightly so your lower back does not arch.","Hold the stretch for the planned time while breathing slowly.","Release the foot, roll to the other side and repeat."],"images":{"main":"images/flat/lying-quad-stretch-main.webp"}},{"id":"lying-tricep-extension","name":"Lying Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Lie flat on a bench and hold one dumbbell in both hands straight above your chest.","Keep your upper arms close to vertical, elbows pointing up toward the ceiling.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms back to the starting position.","Squeeze your triceps at the top.","Repeat for the desired number of reps."],"images":{"start":"images/flat/lying-tricep-extension-start.webp","peak":"images/flat/lying-tricep-extension-peak.webp"}},{"id":"machine-back-extension","name":"Machine Back Extension","bodyPart":"back","category":"strength","equipment":"back_extension_machine","muscles":["erector_spinae"],"steps":["Sit in the back extension machine with your feet flat on the foot platform and the roller pad set behind your upper back, just below the shoulder blades.","Grip the handles at your sides and let your torso come forward into a slight flexion — this is the starting position.","Push back against the pad by extending your spine until your torso is leaning back and your lower back is fully contracted.","Pause briefly at full extension, then return to the starting position under control, resisting the weight stack on the way back.","Repeat for the desired number of reps."],"images":{"start":"images/flat/machine-back-extension-start.webp","peak":"images/flat/machine-back-extension-peak.webp"}},{"id":"machine-bicep-curl","name":"Machine Bicep Curl","bodyPart":"upper_arms","category":"strength","equipment":"bicep_curl_machine","muscles":["biceps_brachii"],"steps":["Sit in the machine and adjust the pad to your arm length.","Grip the handles with an underhand grip.","Curl the handles toward your shoulders.","Lower with control.","Repeat."],"images":{"start":"images/flat/machine-bicep-curl-start.webp","peak":"images/flat/machine-bicep-curl-peak.webp"}},{"id":"machine-calf-raise","name":"Machine Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"standing_calf_raise_machine","muscles":["gastrocnemius","soleus"],"steps":["Stand in the calf raise machine with the balls of your feet on the platform.","Position the shoulder pads firmly.","Lower your heels below the platform for a full stretch.","Push through the balls of your feet to rise onto your toes.","Squeeze your calves at the top.","Lower with control and repeat."],"images":{"start":"images/flat/machine-calf-raise-start.webp","peak":"images/flat/machine-calf-raise-peak.webp"}},{"id":"machine-chest-fly","name":"Machine Chest Fly","bodyPart":"chest","category":"strength","equipment":"chest_fly_machine","muscles":["pectoralis_major"],"steps":["Sit in the chest fly machine and adjust the seat so the handles align with your chest.","Grip the handles with a slight bend in your elbows.","Bring the handles together in front of your chest in a smooth arc.","Squeeze your pectorals at the point of peak contraction.","Return under control to the starting position without slamming the weight.","Repeat for the desired number of reps."],"images":{"start":"images/flat/machine-chest-fly-start.webp","peak":"images/flat/machine-chest-fly-peak.webp"}},{"id":"machine-preacher-curl","name":"Machine Preacher Curl","bodyPart":"upper_arms","category":"strength","equipment":"preacher_curl_machine","muscles":["biceps_brachii"],"steps":["Sit at a preacher curl machine and adjust the seat so your armpits sit at the top of the pad.","Place the upper arms flat on the pad and grip the handles.","Start with the arms extended — but not locked — at the bottom.","Curl the handles up by flexing the elbows; squeeze hard at the top.","Lower slowly back to the starting position and repeat."],"images":{"start":"images/flat/machine-preacher-curl-start.webp","peak":"images/flat/machine-preacher-curl-peak.webp"}},{"id":"machine-reverse-fly","name":"Machine Reverse Fly","bodyPart":"shoulders","category":"strength","equipment":"reverse_fly_machine","muscles":["posterior_deltoid"],"steps":["Adjust the seat so the handles are at shoulder height, then sit facing the machine with your chest against the pad.","Grip the handles with your arms reaching forward and a slight bend in the elbows.","Keep your shoulders down and away from your ears and brace your trunk.","Sweep the handles out and back in a wide arc, leading with the elbows, until your arms are roughly in line with your shoulders.","Squeeze your shoulder blades together briefly without leaning back off the pad.","Return the handles forward slowly and repeat for the planned repetitions."],"images":{"start":"images/flat/machine-reverse-fly-start.webp","peak":"images/flat/machine-reverse-fly-peak.webp"}},{"id":"machine-seated-crunch","name":"Machine Seated Crunch","bodyPart":"core","category":"strength","equipment":"ab_crunch_machine","muscles":["rectus_abdominis"],"steps":["Sit in the abdominal crunch machine and grip the handles.","Position the chest pad against your upper body.","Contract your abs to crunch your torso forward and down.","Squeeze at the bottom of the movement.","Return to the starting position with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/machine-seated-crunch-start.webp","peak":"images/flat/machine-seated-crunch-peak.webp"}},{"id":"machine-shoulder-press","name":"Machine Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"shoulder_press_machine","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Sit in the machine with your back against the pad.","Grip the handles at shoulder level.","Press the handles overhead until arms are fully extended.","Lower with control to the starting position.","Repeat."],"images":{"start":"images/flat/machine-shoulder-press-start.webp","peak":"images/flat/machine-shoulder-press-peak.webp"}},{"id":"machine-triceps-extension","name":"Machine Triceps Extension","bodyPart":"upper_arms","category":"strength","equipment":"tricep_extension_machine","muscles":["triceps_brachii"],"steps":["Sit in the tricep extension machine with your back against the seat pad and your upper arms resting flat on the arm pad in front of your chest.","Take a handle in each hand with your elbows bent and your hands up near shoulder height.","Keeping your upper arms pressed into the pad, extend your elbows to drive the handles down and away until your arms are straight.","Squeeze your triceps at full extension, then bend your elbows to return to the start under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/machine-triceps-extension-start.webp","peak":"images/flat/machine-triceps-extension-peak.webp"}},{"id":"medicine-ball-side-throw","name":"Medicine Ball Side Throw","bodyPart":"core","category":"strength","equipment":"medicine_ball","muscles":["obliques"],"steps":["Stand with your feet a little wider than shoulder-width, holding a medicine ball with both hands in front of your torso.","Turn your torso and the ball toward your back hip, bending your knees slightly and keeping your chest up.","Start the throw by turning your back hip forward and pivoting on the ball of your back foot.","Let your torso and arms follow, throwing the ball out to the side with both hands.","Finish facing the direction of the throw with your arms extended.","Retrieve the ball, reset, and repeat for the planned repetitions, then switch sides."],"images":{"start":"images/flat/medicine-ball-side-throw-start.webp","peak":"images/flat/medicine-ball-side-throw-peak.webp"}},{"id":"medicine-ball-slam","name":"Medicine Ball Slam","bodyPart":"core","category":"strength","equipment":"slam_ball","muscles":["rectus_abdominis"],"steps":["Stand with feet shoulder-width apart, holding a slam ball in front of your hips.","Lift the ball overhead by extending the hips and reaching tall.","Forcefully slam the ball into the floor between your feet, crunching through the core.","Catch the ball on the bounce or pick it up from the floor.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/medicine-ball-slam-start.webp","peak":"images/flat/medicine-ball-slam-peak.webp"}},{"id":"mountain-climbers","name":"Mountain Climbers","bodyPart":"core","category":"cardio","muscles":["hip_flexors","rectus_abdominis"],"steps":["Start in a high plank position.","Drive one knee toward your chest.","Quickly switch legs, driving the other knee forward.","Continue alternating at a brisk pace.","Repeat."],"images":{"start":"images/flat/mountain-climbers-start.webp","peak":"images/flat/mountain-climbers-peak.webp"}},{"id":"mountain-pose","name":"Mountain Pose","bodyPart":"full_body","category":"stretching","muscles":["erector_spinae"],"steps":["Stand with the feet hip-width apart and spread the weight evenly across both feet.","Engage the thighs lightly and let the tailbone drop so the pelvis is neutral.","Stack the ribs over the pelvis and the head over the ribs, arms relaxed by the sides.","Hold the posture for the prescribed time, breathing evenly.","Notice where the weight sits and rebalance it towards the middle of each foot."],"images":{"main":"images/flat/mountain-pose-main.webp"}},{"id":"muscle-snatch","name":"Muscle Snatch","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["lateral_deltoid","trapezius"],"steps":["Stand with feet hip-width apart and grip the bar wide with a hook grip.","Pull the bar explosively from the floor, keeping it close to your body.","Shrug hard and pull the bar overhead without dipping under.","Lock out the bar overhead with straight arms.","Lower the bar under control to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/muscle-snatch-start.webp","peak":"images/flat/muscle-snatch-peak.webp"}},{"id":"muscle-ups","name":"Muscle Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi","triceps_brachii"],"steps":["Hang from a pull-up bar with a false grip.","Pull yourself up explosively toward the bar.","As your chest reaches the bar, rotate your elbows over and transition into a dip.","Press your body up until your arms are fully extended above the bar.","Lower back down with control through the same path.","Repeat for the desired number of reps."],"images":{"start":"images/flat/muscle-ups-start.webp","peak":"images/flat/muscle-ups-peak.webp"}},{"id":"neck-side-stretch","name":"Neck Side Stretch","bodyPart":"back","category":"stretching","muscles":["trapezius"],"steps":["Sit or stand tall with your shoulders relaxed.","Tilt your head so one ear drops toward that shoulder.","Rest that hand lightly over your head for gentle weight.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/neck-side-stretch-main.webp"}},{"id":"negative-pull-ups","name":"Negative Pull Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Use a box or jump to position yourself at the top of a pull-up.","Grip the bar with hands shoulder-width apart.","Hold your chin above the bar briefly.","Lower yourself slowly over 3-5 seconds with control.","Fully extend your arms at the bottom.","Reset and repeat for the desired number of reps."],"images":{"start":"images/flat/negative-pull-ups-start.webp","peak":"images/flat/negative-pull-ups-peak.webp"}},{"id":"neutral-grip-pull-ups","name":"Neutral Grip Pull Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Grip parallel bars with palms facing each other.","Hang with your arms fully extended.","Pull yourself up until your chin clears the bar.","Squeeze your lats at the top of the movement.","Lower yourself with control to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/neutral-grip-pull-ups-start.webp","peak":"images/flat/neutral-grip-pull-ups-peak.webp"}},{"id":"nordic-hamstring-curl","name":"Nordic Hamstring Curl","bodyPart":"upper_legs","category":"strength","equipment":"glute_ham_developer","muscles":["hamstrings"],"steps":["Kneel on a pad with your ankles anchored under a fixed support.","Keep your torso upright and your hips extended.","Slowly lower your body forward by resisting with your hamstrings.","Catch yourself with your hands just before hitting the floor.","Push back up and pull yourself to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/nordic-hamstring-curl-start.webp","peak":"images/flat/nordic-hamstring-curl-peak.webp"}},{"id":"ohp","name":"Barbell Overhead Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Stand with feet shoulder-width apart, bar at collarbone level.","Brace your core and press the bar overhead.","Lock out at the top with the bar over your mid-foot.","Lower the bar back to collarbone height.","Repeat."],"images":{"start":"images/flat/ohp-start.webp","peak":"images/flat/ohp-peak.webp"}},{"id":"one-arm-dumbbell-preacher-curl","name":"One Arm Dumbbell Preacher Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Sit at a preacher bench and rest the back of one upper arm flat on the pad.","Hold a dumbbell in that hand with the palm facing up and the arm almost fully extended.","Curl the dumbbell toward the shoulder without lifting the elbow off the pad.","Squeeze the biceps at the top of the movement.","Lower the dumbbell slowly until the arm is almost straight.","Complete the repetitions, then switch arms."],"images":{"start":"images/flat/one-arm-dumbbell-preacher-curl-start.webp","peak":"images/flat/one-arm-dumbbell-preacher-curl-peak.webp"}},{"id":"one-arm-dumbbell-push-press","name":"One-Arm Dumbbell Push Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid"],"steps":["Stand holding a dumbbell at one shoulder, palm facing inward (neutral).","Feet shoulder-width, core braced, free arm out to the side for balance.","Dip by bending the knees slightly, keeping the torso vertical.","Explosively extend the legs and press the dumbbell overhead in one motion.","Lock out overhead, then lower back to the shoulder under control.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/one-arm-dumbbell-push-press-start.webp","peak":"images/flat/one-arm-dumbbell-push-press-peak.webp"}},{"id":"one-arm-dumbbell-shoulder-press","name":"One Arm Dumbbell Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Stand with the feet hip-width apart and hold a dumbbell at one shoulder with the palm facing forward.","Brace the abdominals and keep the free arm relaxed at your side.","Press the dumbbell straight overhead until the arm is fully extended.","Pause briefly at the top with the upper arm next to the ear.","Lower the dumbbell back to the shoulder under control.","Complete the repetitions on one arm, then switch sides."],"images":{"start":"images/flat/one-arm-dumbbell-shoulder-press-start.webp","peak":"images/flat/one-arm-dumbbell-shoulder-press-peak.webp"}},{"id":"one-arm-dumbbell-swing","name":"One-Arm Dumbbell Swing","bodyPart":"full_body","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with feet shoulder-width apart, a dumbbell on the floor slightly in front of you.","Hinge at your hips, keeping a flat back, and grasp the dumbbell with one hand.","Hike the dumbbell back between your legs, then explosively drive your hips forward.","Swing the dumbbell up to chest height, keeping your arm relaxed and straight.","Allow the dumbbell to swing back down, hinging at the hips as it descends.","Repeat for desired reps per side, maintaining control."],"images":{"start":"images/flat/one-arm-dumbbell-swing-start.webp","peak":"images/flat/one-arm-dumbbell-swing-peak.webp"}},{"id":"one-arm-kettlebell-bicep-curl","name":"One Arm Kettlebell Bicep Curl","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["biceps_brachii"],"steps":["Stand tall holding a kettlebell in one hand.","Keep your elbow pinned to your side.","Curl the kettlebell toward your shoulder by flexing your bicep.","Squeeze at the top of the movement.","Lower the kettlebell with control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-bicep-curl-start.webp","peak":"images/flat/one-arm-kettlebell-bicep-curl-peak.webp"}},{"id":"one-arm-kettlebell-bottoms-up-press","name":"One-Arm Kettlebell Bottoms-Up Press","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid"],"steps":["Clean a light kettlebell to the rack position, then tilt it so the bell points up and the handle is at the palm.","Grip the handle hard; wrist absolutely straight and vertical.","Brace the core and press the bell straight up without letting it tip.","Lock out overhead with the bell still perfectly upright.","Lower slowly back to the rack position keeping the bell vertical the entire descent.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-bottoms-up-press-start.webp","peak":"images/flat/one-arm-kettlebell-bottoms-up-press-peak.webp"}},{"id":"one-arm-kettlebell-floor-glute-bridge-press","name":"One Arm Kettlebell Floor Glute Bridge Press","bodyPart":"chest","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","pectoralis_major"],"steps":["Lie on your back with knees bent and feet flat on the floor.","Hold a kettlebell in one hand at your shoulder.","Drive your hips up into a glute bridge.","Press the kettlebell straight up toward the ceiling.","Lower the kettlebell and your hips with control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-floor-glute-bridge-press-start.webp","peak":"images/flat/one-arm-kettlebell-floor-glute-bridge-press-peak.webp"}},{"id":"one-arm-kettlebell-floor-press","name":"One Arm Kettlebell Floor Press","bodyPart":"chest","category":"strength","equipment":"kettlebell","muscles":["pectoralis_major"],"steps":["Lie flat on the floor with knees bent.","Hold a kettlebell at your shoulder with one hand.","Press the kettlebell straight up until your arm is fully extended.","Lower the kettlebell until your upper arm touches the floor.","Keep your core braced throughout.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-floor-press-start.webp","peak":"images/flat/one-arm-kettlebell-floor-press-peak.webp"}},{"id":"one-arm-kettlebell-front-squat","name":"One Arm Kettlebell Front Squat","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","quadriceps"],"steps":["Hold a kettlebell in the racked position at one shoulder.","Stand with feet shoulder-width apart.","Squat down by bending your knees and hips.","Keep your chest up and torso upright throughout.","Drive through your heels to stand back up.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-front-squat-start.webp","peak":"images/flat/one-arm-kettlebell-front-squat-peak.webp"}},{"id":"one-arm-kettlebell-push-press","name":"One Arm Kettlebell Push Press","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid"],"steps":["Hold a kettlebell in the racked position at one shoulder.","Stand with feet shoulder-width apart.","Dip by bending your knees slightly.","Drive explosively through your legs and press the kettlebell overhead.","Lock out your arm at the top.","Lower the kettlebell to your shoulder with control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-push-press-start.webp","peak":"images/flat/one-arm-kettlebell-push-press-peak.webp"}},{"id":"one-arm-kettlebell-row","name":"One Arm Kettlebell Row","bodyPart":"back","category":"strength","equipment":"kettlebell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Place one hand and knee on a bench for support.","Hold a kettlebell in the opposite hand with your arm extended.","Pull the kettlebell toward your hip by driving your elbow back.","Squeeze your back at the top of the movement.","Lower the kettlebell with control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-row-start.webp","peak":"images/flat/one-arm-kettlebell-row-peak.webp"}},{"id":"one-arm-kettlebell-shoulder-press","name":"One Arm Kettlebell Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"kettlebell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Hold a kettlebell in the racked position at one shoulder.","Stand tall with feet hip-width apart.","Press the kettlebell straight overhead until your arm is locked out.","Keep your core tight throughout.","Lower the kettlebell back to the rack position with control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-shoulder-press-start.webp","peak":"images/flat/one-arm-kettlebell-shoulder-press-peak.webp"}},{"id":"one-arm-kettlebell-swing","name":"One Arm Kettlebell Swing","bodyPart":"full_body","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.","Hinge at the hips and grip the kettlebell with one hand.","Hike the kettlebell back between your legs.","Drive your hips forward to swing the kettlebell to chest height.","Let gravity bring the kettlebell back between your legs.","Complete reps on one side, then switch."],"images":{"start":"images/flat/one-arm-kettlebell-swing-start.webp","peak":"images/flat/one-arm-kettlebell-swing-peak.webp"}},{"id":"one-arm-kettlebell-tricep-kickback","name":"One-Arm Kettlebell Tricep Kickback","bodyPart":"upper_arms","category":"strength","equipment":"kettlebell","muscles":["triceps_brachii"],"steps":["Hinge forward at the hips with a flat back, knees softly bent.","Hold a kettlebell by the handle in one hand, palm facing the body.","Pin the upper arm to the side so it is parallel to the floor; the forearm hangs straight down.","Extend the elbow back to straighten the arm fully behind you, keeping the upper arm motionless.","Squeeze the tricep at lockout, then return under control to the starting position.","Complete all reps on one side, then switch hands."],"images":{"start":"images/flat/one-arm-kettlebell-tricep-kickback-start.webp","peak":"images/flat/one-arm-kettlebell-tricep-kickback-peak.webp"}},{"id":"one-arm-landmine-press","name":"One-Arm Landmine Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Anchor one end of a barbell in a landmine attachment and load the free end.","Kneel on one knee or stand and grip the sleeve end at shoulder height with one hand.","Press the bar upward and forward along its arc until the arm is fully extended.","Lower the bar back to shoulder height under control.","Complete all reps before switching sides."],"images":{"start":"images/flat/one-arm-landmine-press-start.webp","peak":"images/flat/one-arm-landmine-press-peak.webp"}},{"id":"one-arm-lat-pulldown","name":"One-Arm Lat Pulldown","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi"],"steps":["Attach a single-handle to the cable pulldown station and sit with your thighs secured under the pad.","Reach up and grasp the handle with one hand, arm fully extended.","Pull the handle down toward your shoulder, driving your elbow toward your hip.","Pause briefly at full contraction, then return to the starting position with control.","Complete all reps on one side before switching."],"images":{"start":"images/flat/one-arm-lat-pulldown-start.webp","peak":"images/flat/one-arm-lat-pulldown-peak.webp"}},{"id":"one-arm-seated-cable-row","name":"One-Arm Seated Cable Row","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi","rhomboids"],"steps":["Sit at the cable row station and hold one handle with the working arm extended.","Plant the feet, sit tall and brace the trunk without leaning back.","Pull the handle towards the lower ribs while drawing the shoulder blade back.","Pause briefly without rotating the torso or shrugging the shoulder.","Extend the arm under control, finish the set and repeat on the other side."],"images":{"start":"images/flat/one-arm-seated-cable-row-start.webp","peak":"images/flat/one-arm-seated-cable-row-peak.webp"}},{"id":"one-arm-single-leg-dumbbell-romanian-deadlift","name":"One-Arm Single-Leg Dumbbell Romanian Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on one leg holding a dumbbell in the opposite hand.","Free arm out to the side for balance, free leg hovering just off the floor.","Hinge at the standing hip, pushing it back while the free leg extends behind to counterbalance.","Keep the hips square to the floor — do not open them to the side.","Lower the dumbbell toward the foot of the standing leg, feeling a deep hamstring stretch.","Drive the hip forward to return to standing under control.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/one-arm-single-leg-dumbbell-romanian-deadlift-start.webp","peak":"images/flat/one-arm-single-leg-dumbbell-romanian-deadlift-peak.webp"}},{"id":"one-arm-single-leg-kettlebell-romanian-deadlift","name":"One-Arm Single-Leg Kettlebell Romanian Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"kettlebell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on one leg holding a kettlebell in the opposite hand by the handle.","Free arm out to the side for balance, free leg hovering behind.","Hinge at the standing hip, pushing it back while the free leg extends to counterbalance.","Keep hips square to the floor; the kettlebell tracks straight down the shin.","Feel a deep hamstring stretch on the standing leg at the bottom.","Drive the hip forward to return to standing.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/one-arm-single-leg-kettlebell-romanian-deadlift-start.webp","peak":"images/flat/one-arm-single-leg-kettlebell-romanian-deadlift-peak.webp"}},{"id":"overhead-squat","name":"Overhead Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Hold a barbell overhead with a wide snatch grip and arms locked out.","Stand with feet slightly wider than shoulder-width.","Squat down by pushing your hips back and bending your knees.","Keep the bar directly over the middle of your feet.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],"images":{"start":"images/flat/overhead-squat-start.webp","peak":"images/flat/overhead-squat-peak.webp"}},{"id":"overhead-tricep-extension","name":"Overhead Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Stand or sit holding a dumbbell overhead with both hands.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms back to the starting position.","Keep your elbows close to your head throughout.","Repeat."],"images":{"start":"images/flat/overhead-tricep-extension-start.webp","peak":"images/flat/overhead-tricep-extension-peak.webp"}},{"id":"overhead-triceps-stretch","name":"Overhead Triceps Stretch","bodyPart":"upper_arms","category":"stretching","muscles":["triceps_brachii"],"steps":["Raise one arm overhead and bend the elbow.","Let your hand drop down behind your head.","Use the other hand to press the bent elbow back.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/overhead-triceps-stretch-main.webp"}},{"id":"pause-deadlift","name":"Pause Deadlift","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["erector_spinae","gluteus_maximus","hamstrings"],"steps":["Set up for a conventional deadlift.","Pull the bar off the floor and pause when it passes your knees.","Hold for 2–3 seconds, then complete the lift.","Lower under control.","Repeat."],"images":{"start":"images/flat/pause-deadlift-start.webp","peak":"images/flat/pause-deadlift-peak.webp"}},{"id":"pause-pull-up","name":"Pause Pull-Up","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Hang from a pull-up bar with an overhand grip, arms fully extended.","Pull yourself up until your chin clears the bar.","Pause and hold that top position for a moment.","Lower yourself back down under control to a full hang.","Repeat for the desired number of reps."],"images":{"start":"images/flat/pause-pull-up-start.webp","peak":"images/flat/pause-pull-up-peak.webp"}},{"id":"pause-squat","name":"Pause Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Unrack a barbell and rest it across your upper back.","Stand with feet shoulder-width apart.","Squat down until your thighs are parallel to the floor.","Hold the bottom position for 2-3 seconds.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],"images":{"start":"images/flat/pause-squat-start.webp","peak":"images/flat/pause-squat-peak.webp"}},{"id":"paused-bench-press","name":"Paused Bench Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Lie on a flat bench and grip the barbell slightly wider than shoulder-width.","Unrack the bar and lower it to your chest.","Pause on your chest for 1-2 seconds.","Press the bar back up until your arms are fully extended.","Control the descent on every rep.","Repeat for the desired number of reps."],"images":{"start":"images/flat/paused-bench-press-start.webp","peak":"images/flat/paused-bench-press-peak.webp"}},{"id":"paused-incline-bench-press","name":"Paused Incline Bench Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Lie on an incline bench and grip the barbell slightly wider than shoulder-width.","Unrack the bar and lower it to your upper chest.","Pause on your chest for 1-2 seconds.","Press the bar back up until your arms are fully extended.","Keep your shoulder blades retracted throughout.","Repeat for the desired number of reps."],"images":{"start":"images/flat/paused-incline-bench-press-start.webp","peak":"images/flat/paused-incline-bench-press-peak.webp"}},{"id":"paused-ohp","name":"Paused Overhead Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Set up with a barbell racked at shoulder height, feet shoulder-width apart, and the core braced.","Press the bar straight overhead until the elbows are fully locked out.","Lower the bar under control back down to the front of the shoulders.","Hold a full one-second pause at the shoulders, keeping tension and eliminating any bounce.","Press back up from the dead stop without using leg drive."],"images":{"start":"images/flat/paused-ohp-start.webp","peak":"images/flat/paused-ohp-peak.webp"}},{"id":"pec-deck","name":"Pec Deck","bodyPart":"chest","category":"strength","equipment":"pec_deck","muscles":["pectoralis_major"],"steps":["Sit in the pec deck machine and grip the handles with your arms out to the sides, elbows slightly bent.","Adjust the seat so the handles align with mid-chest height.","Squeeze the handles together in front of your chest.","Hold the contraction briefly at the center.","Return under control to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/pec-deck-start.webp","peak":"images/flat/pec-deck-peak.webp"}},{"id":"pendlay-row","name":"Pendlay Row","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","rhomboids","trapezius"],"steps":["Load a barbell and set it on the floor.","Hinge at the hips until your torso is parallel to the ground, knees slightly bent.","Grip the bar slightly wider than shoulder-width with an overhand grip.","Explosively pull the bar to your lower chest.","Lower the bar back to the floor under control and pause before the next rep.","Repeat."],"images":{"start":"images/flat/pendlay-row-start.webp","peak":"images/flat/pendlay-row-peak.webp"}},{"id":"pigeon-stretch","name":"Pigeon Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["gluteus_maximus"],"steps":["From all fours, bring one knee forward and lay the shin across in front.","Extend the other leg straight back, top of the foot down.","Sink your hips toward the floor and keep them square.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/pigeon-stretch-main.webp"}},{"id":"pike-push-ups","name":"Pike Push Ups","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Start in a downward dog position with hips high and hands shoulder-width apart.","Walk your feet closer to your hands.","Bend your elbows and lower your head toward the floor.","Keep your hips high throughout.","Press back up until your arms are fully extended.","Repeat for the desired number of reps."],"images":{"start":"images/flat/pike-push-ups-start.webp","peak":"images/flat/pike-push-ups-peak.webp"}},{"id":"pilates-kneeling-side-kick","name":"Pilates Kneeling Side Kick","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_medius","obliques"],"steps":["Kneel on one knee and place the same-side hand on the floor under the shoulder, the other hand on the hip.","Extend the top leg out to the side, the foot a little below hip height.","Keeping the trunk perfectly still, lift the leg up to hip height.","Lower it back down under control without letting the pelvis tip or the lower back arch.","Repeat for the desired number of repetitions and change sides."],"images":{"start":"images/flat/pilates-kneeling-side-kick-start.webp","peak":"images/flat/pilates-kneeling-side-kick-peak.webp"}},{"id":"pilates-leg-pull-back","name":"Pilates Leg Pull Back","bodyPart":"core","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.","Press into the hands and heels and lift the hips into a reverse plank.","Keeping the hips level and high, lift one straight leg as far as the pelvis stays still.","Lower the leg under control and repeat with the other one.","Finish the set and lower the hips to the floor."],"images":{"start":"images/flat/pilates-leg-pull-back-start.webp","peak":"images/flat/pilates-leg-pull-back-peak.webp"}},{"id":"pilates-leg-pull-front","name":"Pilates Leg Pull Front","bodyPart":"core","category":"strength","muscles":["gluteus_maximus","rectus_abdominis"],"steps":["Set up in a high plank with the hands under the shoulders and the body in one line.","Brace the trunk and squeeze the glutes so the hips cannot rotate.","Lift one straight leg a few centimetres above hip height without letting the pelvis tilt.","Lower it under control and repeat with the other leg.","Keep alternating for the desired number of repetitions."],"images":{"start":"images/flat/pilates-leg-pull-front-start.webp","peak":"images/flat/pilates-leg-pull-front-peak.webp"}},{"id":"pilates-roll-down","name":"Pilates Roll Down","bodyPart":"back","category":"stretching","muscles":["erector_spinae"],"steps":["Stand tall with the feet hip-width apart and the arms hanging at the sides.","Drop the chin to the chest and start rolling down one vertebra at a time.","Let the arms and head hang heavy once the spine is fully rolled down.","Roll back up the same way, stacking the vertebrae one by one, head last.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/pilates-roll-down-start.webp","peak":"images/flat/pilates-roll-down-peak.webp"}},{"id":"pilates-roll-over","name":"Pilates Roll Over","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Lie on your back with the legs straight and the arms pressed into the mat beside you.","Lift both legs to vertical without letting the lower back arch.","Press the arms down and take the legs overhead until they are parallel to the floor behind you.","Open the legs slightly, flex the feet, and roll the spine down one vertebra at a time.","Return the legs to vertical and repeat for the desired number of repetitions."],"images":{"start":"images/flat/pilates-roll-over-start.webp","peak":"images/flat/pilates-roll-over-peak.webp"}},{"id":"pilates-saw","name":"Pilates Saw","bodyPart":"back","category":"stretching","muscles":["erector_spinae","obliques"],"steps":["Sit tall with the legs straight and slightly wider than the hips, arms out to the sides.","Rotate the torso to one side, keeping both sit bones on the floor.","Fold forward over that leg and reach the opposite hand past the little toe.","Roll back up through the spine and return to the centre.","Repeat to the other side and continue alternating."],"images":{"start":"images/flat/pilates-saw-start.webp","peak":"images/flat/pilates-saw-peak.webp"}},{"id":"pilates-side-bend","name":"Pilates Side Bend","bodyPart":"core","category":"strength","muscles":["gluteus_medius","obliques"],"steps":["Sit on one hip with the legs bent to the side and the supporting hand on the floor under the shoulder.","Press into the hand and the lower leg to lift the hips off the floor.","Reach the top arm overhead so the body forms a long arc from the hand to the feet.","Lower the hips under control back towards the mat.","Complete the repetitions and change sides."],"images":{"start":"images/flat/pilates-side-bend-start.webp","peak":"images/flat/pilates-side-bend-peak.webp"}},{"id":"pilates-spine-stretch-forward","name":"Pilates Spine Stretch Forward","bodyPart":"back","category":"stretching","muscles":["erector_spinae","rectus_abdominis"],"steps":["Sit tall with the legs straight and slightly wider than the hips, feet flexed.","Reach the arms forward at shoulder height.","Drop the chin and curl the spine forward one vertebra at a time, reaching past the toes.","Restack the spine from the base upwards until you are sitting tall again.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/pilates-spine-stretch-forward-start.webp","peak":"images/flat/pilates-spine-stretch-forward-peak.webp"}},{"id":"pilates-spine-twist","name":"Pilates Spine Twist","bodyPart":"core","category":"stretching","muscles":["obliques"],"steps":["Sit tall with the legs straight and together, feet flexed, arms out to the sides at shoulder height.","Grow tall through the spine and press both sit bones into the floor.","Rotate the trunk to one side as far as the hips stay square, then return to the centre.","Rotate to the other side in the same way.","Keep alternating for the desired number of repetitions."],"images":{"start":"images/flat/pilates-spine-twist-start.webp","peak":"images/flat/pilates-spine-twist-peak.webp"}},{"id":"pistol-squat","name":"Pistol Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand on one leg with the other extended forward, arms out for balance.","Hinge at the hips and bend the standing knee, keeping the chest up.","Descend slowly until the back of the thigh touches the calf.","Drive through the standing heel to return to standing.","Complete reps per side, then switch legs."],"images":{"start":"images/flat/pistol-squat-start.webp","peak":"images/flat/pistol-squat-peak.webp"}},{"id":"planche","name":"Planche","bodyPart":"chest","category":"strength","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Begin in a push-up position with your hands turned outward on the floor, or on parallettes.","Lean forward until your center of mass is over your hands.","Lift your feet off the ground keeping the body horizontal.","Hold the position.","Return to the floor with control."],"images":{"main":"images/flat/planche-main.webp"}},{"id":"planche-lean-floor","name":"Planche Lean","bodyPart":"chest","category":"strength","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Start in a high plank with your hands on the floor, a little below your hips and turned out slightly.","Lock your elbows and protract your shoulder blades so your upper back is slightly rounded and strong.","Lean your body forward until your shoulders are well in front of your hands.","Keep your whole body in a straight line, with your glutes squeezed and your core braced.","Hold the lean for the planned time while breathing steadily.","Shift back to the neutral plank to finish."],"images":{"main":"images/flat/planche-lean-floor-main.webp"}},{"id":"plank","name":"Plank","bodyPart":"core","category":"strength","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Place your forearms on the floor with elbows under your shoulders.","Extend your legs back and rise onto your toes.","Keep your body in a straight line from head to heels.","Brace your core and squeeze your glutes.","Hold the position for the desired duration.","Lower your knees to exit the hold."],"images":{"main":"images/flat/plank-main.webp"}},{"id":"plank-knee-tuck","name":"Plank Knee Tuck","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Set up in a high plank with the hands under the shoulders and the body in a straight line from head to heels.","Press the floor away and brace the trunk so the hips neither sag nor pike.","Draw one knee in towards the chest without letting the hips rise.","Extend the leg back to the starting position under control.","Repeat with the other leg and keep alternating for the desired number of repetitions."],"images":{"start":"images/flat/plank-knee-tuck-start.webp","peak":"images/flat/plank-knee-tuck-peak.webp"}},{"id":"plate-loaded-donkey-calf-raise","name":"Plate-Loaded Donkey Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"donkey_calf_raise_machine","muscles":["gastrocnemius"],"steps":["Load the plate horns and step onto the platform with the balls of your feet on the edge and your heels hanging free.","Bend forward at the hips and settle the pad across your hips, then rest your forearms on the support in front of you.","Keep your knees straight and your back flat, with your torso close to parallel to the floor.","Push through the balls of your feet and raise your heels as high as you can, pausing briefly at the top.","Lower your heels below the platform until you feel a strong calf stretch, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/plate-loaded-donkey-calf-raise-start.webp","peak":"images/flat/plate-loaded-donkey-calf-raise-peak.webp"}},{"id":"plate-loaded-glute-drive","name":"Plate-Loaded Glute Drive","bodyPart":"upper_legs","category":"strength","equipment":"hip_thrust_machine","muscles":["gluteus_maximus"],"steps":["Load the plate horns evenly and sit into the machine with your upper back against the pad and your feet flat on the platform.","Pull the hip pad or lap bar across your hips and adjust it so it sits on the crease of the hips, not on your stomach.","Set your feet so that your shins will be roughly vertical when your hips are at the top, and take hold of the handles.","Drive your hips up by squeezing the glutes until your thighs are level with your torso, and hold briefly at the top.","Lower under control until your hips are just short of the bottom of the range, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/plate-loaded-glute-drive-start.webp","peak":"images/flat/plate-loaded-glute-drive-peak.webp"}},{"id":"plate-loaded-lateral-raise","name":"Plate-Loaded Lateral Raise","bodyPart":"shoulders","category":"strength","equipment":"plate_loaded_lateral_raise_machine","muscles":["lateral_deltoid"],"steps":["Set the seat height so that the pivot of the arm pads lines up with the point of your shoulders when you sit down.","Load the plate horns evenly on both sides and sit with your back flat against the pad.","Place the outside of your upper arms against the pads with your elbows bent and your arms hanging down.","Push out and up against the pads until your upper arms are roughly level with your shoulders.","Lower under control until your arms are back at your sides, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/plate-loaded-lateral-raise-start.webp","peak":"images/flat/plate-loaded-lateral-raise-peak.webp"}},{"id":"plate-loaded-seated-dip-machine","name":"Plate-Loaded Seated Dip Machine","bodyPart":"upper_arms","category":"strength","equipment":"plate_loaded_dip_machine","muscles":["triceps_brachii"],"steps":["Load the plates evenly on the sleeve and adjust the seat so the handles are at about shoulder height when you are seated.","Sit upright with your back against the pad and grip the handles at your sides with your elbows bent.","Keep your shoulders down and your chest up, then press the handles down by straightening your elbows.","Squeeze your triceps at the bottom, with your arms straight but not locked out hard.","Let the handles rise back up under control until your elbows are bent to about 90 degrees.","Repeat for the planned repetitions, then return the lever to its safety stop before you stand up."],"images":{"start":"images/flat/plate-loaded-seated-dip-machine-start.webp","peak":"images/flat/plate-loaded-seated-dip-machine-peak.webp"}},{"id":"plate-loaded-shrug","name":"Plate-Loaded Shrug","bodyPart":"back","category":"strength","equipment":"shrug_machine","muscles":["trapezius"],"steps":["Load the plate horns evenly and stand on the machine platform, facing away from the frame.","Take a handle in each hand with your arms hanging straight down at your sides and your shoulders relaxed.","Stand tall with your chest up, your chin level and your knees soft.","Shrug your shoulders straight up toward your ears as high as they will go, and hold for a moment at the top.","Lower under control until your shoulders are fully down, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/plate-loaded-shrug-start.webp","peak":"images/flat/plate-loaded-shrug-peak.webp"}},{"id":"plate-pinch","name":"Plate Pinch","bodyPart":"lower_arms","category":"strength","equipment":"plates","muscles":["forearm_flexors"],"steps":["Stand a weight plate on its edge on the floor.","Squat down and pinch the plate by its rim between the fingers and thumb of one hand — no handles, just pinch.","Stand up and hold the plate at the side for time, keeping the arm straight.","Set it back down under control.","Repeat on the other hand."],"images":{"start":"images/flat/plate-pinch-start.webp","peak":"images/flat/plate-pinch-peak.webp"}},{"id":"plate-pullover","name":"Plate Pullover","bodyPart":"back","category":"strength","equipment":"plates","muscles":["latissimus_dorsi","pectoralis_major"],"steps":["Lie flat on a bench holding a plate with both hands.","Press the plate over the chest with arms nearly straight.","Lower the plate back in an arc behind the head until you feel a stretch.","Pull the plate back over the chest along the same arc.","Repeat for the prescribed reps."],"images":{"start":"images/flat/plate-pullover-start.webp","peak":"images/flat/plate-pullover-peak.webp"}},{"id":"plow-pose","name":"Plow Pose","bodyPart":"back","category":"stretching","muscles":["erector_spinae","hamstrings"],"steps":["Lie on your back with the arms alongside the body, palms down.","Lift both legs overhead and support the lower back with the hands.","Lower the toes towards the floor behind the head, keeping the legs as straight as comfort allows.","Hold the position for the prescribed time, breathing steadily and keeping the head still.","Roll down one vertebra at a time with the hands supporting the back."],"images":{"main":"images/flat/plow-pose-main.webp"}},{"id":"plyo-lunge","name":"Plyo Lunge","bodyPart":"upper_legs","category":"plyometrics","muscles":["gluteus_maximus","quadriceps"],"steps":["Start in a forward lunge with one foot ahead of the other.","Drop into a deep lunge with the back knee almost touching the floor.","Drive both feet off the floor, switching legs in mid-air.","Land softly in a lunge with the opposite leg forward.","Continue alternating without pausing."],"images":{"start":"images/flat/plyo-lunge-start.webp","peak":"images/flat/plyo-lunge-peak.webp"}},{"id":"plyo-push-up","name":"Plyo Push-Up","bodyPart":"chest","category":"plyometrics","muscles":["pectoralis_major","triceps_brachii"],"steps":["Set up in a standard push-up position with hands shoulder-width.","Lower yourself with control until the chest nearly touches the floor.","Drive up explosively so the hands leave the floor.","Land softly with the elbows slightly bent.","Repeat without pausing for the prescribed reps."],"images":{"start":"images/flat/plyo-push-up-start.webp","peak":"images/flat/plyo-push-up-peak.webp"}},{"id":"preacher-curl","name":"Preacher Curl","bodyPart":"upper_arms","category":"strength","equipment":"ez_bar","muscles":["biceps_brachii"],"steps":["Sit at a preacher bench with your upper arms resting on the pad.","Hold an EZ-bar with an underhand grip.","Curl the bar up toward your shoulders.","Lower with control until arms are nearly straight.","Repeat."],"images":{"start":"images/flat/preacher-curl-start.webp","peak":"images/flat/preacher-curl-peak.webp"}},{"id":"preacher-hammer-curl","name":"Preacher Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["brachialis","brachioradialis"],"steps":["Sit at a preacher bench with a dumbbell in each hand.","Rest your upper arms on the pad with palms facing each other.","Curl the dumbbells up while keeping your wrists neutral.","Squeeze your biceps at the top of the movement.","Lower the dumbbells with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/preacher-hammer-curl-start.webp","peak":"images/flat/preacher-hammer-curl-peak.webp"}},{"id":"pseudo-planche-push-ups","name":"Pseudo Planche Push Ups","bodyPart":"chest","category":"strength","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Start in a push-up position with your hands turned so fingers point back.","Lean your shoulders forward past your wrists.","Lower your chest toward the floor by bending your elbows.","Keep your body in a straight line.","Press back up while maintaining the forward lean.","Repeat for the desired number of reps."],"images":{"start":"images/flat/pseudo-planche-push-ups-start.webp","peak":"images/flat/pseudo-planche-push-ups-peak.webp"}},{"id":"pull-up","name":"Pull-Up","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Hang from a bar with an overhand grip, slightly wider than shoulder-width.","Pull yourself up until your chin is over the bar.","Lower yourself under control to a dead hang.","Repeat."],"images":{"start":"images/flat/pull-up-start.webp","peak":"images/flat/pull-up-peak.webp"}},{"id":"puppy-pose","name":"Puppy Pose","bodyPart":"shoulders","category":"stretching","muscles":["latissimus_dorsi","posterior_deltoid"],"steps":["Kneel on all fours with the hips over the knees and the hands under the shoulders.","Walk the hands forward and lower the chest towards the floor, keeping the hips high.","Rest the forehead or the chin on the mat and let the armpits soften downwards.","Hold the position for the prescribed time, breathing into the upper back.","Walk the hands back and sit onto the heels to come out."],"images":{"main":"images/flat/puppy-pose-main.webp"}},{"id":"push-jerk","name":"Push Jerk","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["anterior_deltoid","triceps_brachii"],"steps":["Hold a barbell in the front rack position at your shoulders.","Stand with feet hip-width apart.","Dip by bending your knees slightly.","Drive explosively through your legs and press the bar overhead.","Drop into a quarter-squat under the bar and lock out your arms.","Stand up fully and lower the bar to repeat."],"images":{"start":"images/flat/push-jerk-start.webp","peak":"images/flat/push-jerk-peak.webp"}},{"id":"push-press","name":"Push Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Stand with a barbell racked on your front deltoids.","Dip slightly at the knees.","Drive up with your legs and press the bar overhead.","Lock out fully.","Lower to the start.","Repeat."],"images":{"start":"images/flat/push-press-start.webp","peak":"images/flat/push-press-peak.webp"}},{"id":"push-up","name":"Push-Up","bodyPart":"chest","category":"strength","muscles":["pectoralis_major","triceps_brachii"],"steps":["Start in a high plank position with hands shoulder-width apart.","Lower your body until your chest nearly touches the floor.","Push back up to the starting position.","Keep your body in a straight line throughout.","Repeat."],"images":{"start":"images/flat/push-up-start.webp","peak":"images/flat/push-up-peak.webp"}},{"id":"pyramid-pose","name":"Pyramid Pose","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings"],"steps":["Step one foot back about a leg's length and turn the back foot out slightly.","Square both hip points towards the front of the mat and keep both legs straight.","Hinge from the hips and fold over the front leg, bringing the hands to the floor, blocks or the shin.","Hold the fold for the prescribed time with the spine long rather than rounded.","Press into the feet to come up and repeat on the other side."],"images":{"main":"images/flat/pyramid-pose-main.webp"}},{"id":"rack-pull","name":"Rack Pull","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["erector_spinae","gluteus_maximus","hamstrings","trapezius"],"steps":["Set the safety pins in a power rack at knee height and place a loaded barbell on them.","Stand with feet hip-width apart and grip the bar just outside your legs.","Brace your core, retract your shoulder blades, and drive through your legs to lift the bar.","Lock out your hips and knees fully at the top.","Return the bar to the pins under control and reset before the next rep."],"images":{"start":"images/flat/rack-pull-start.webp","peak":"images/flat/rack-pull-peak.webp"}},{"id":"rear-delt-fly","name":"Rear Delt Fly","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["posterior_deltoid","rhomboids"],"steps":["Hold dumbbells and hinge forward at the hips.","With a slight bend in elbows, raise the dumbbells out to the sides.","Squeeze your shoulder blades at the top.","Lower with control.","Repeat."],"images":{"start":"images/flat/rear-delt-fly-start.webp","peak":"images/flat/rear-delt-fly-peak.webp"}},{"id":"reclined-butterfly","name":"Reclined Butterfly","bodyPart":"upper_legs","category":"stretching","muscles":["adductors"],"steps":["Lie on your back with your knees bent and the soles of your feet flat on the floor.","Bring the soles of your feet together and let both knees fall out to the sides.","Rest your arms on the floor with your palms up, or place your hands on your belly.","Keep your lower back resting on the floor and your shoulders relaxed.","Breathe slowly and let your knees sink toward the floor for the planned time.","Bring your knees together with your hands to finish."],"images":{"main":"images/flat/reclined-butterfly-main.webp"}},{"id":"renegade-row","name":"Renegade Row","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Start in a high plank with a hand on each of two dumbbells, shoulder-width apart, and the feet set wide for stability.","Brace the trunk so the body forms a straight line from head to heels.","Row one dumbbell up toward the hip, driving the elbow back along the ribs.","Keep the hips square to the floor and do not let the body twist.","Lower the dumbbell to the floor under control.","Repeat on the other side and keep alternating."],"images":{"start":"images/flat/renegade-row-start.webp","peak":"images/flat/renegade-row-peak.webp"}},{"id":"reverse-crunches","name":"Reverse Crunches","bodyPart":"core","category":"strength","muscles":["rectus_abdominis"],"steps":["Lie on your back with your arms at your sides.","Raise your legs with knees bent to 90 degrees.","Curl your hips off the floor by contracting your lower abs.","Bring your knees toward your chest.","Lower your hips with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/reverse-crunches-start.webp","peak":"images/flat/reverse-crunches-peak.webp"}},{"id":"reverse-curl","name":"Reverse Curl","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["brachialis","forearm_extensors"],"steps":["Stand and hold a barbell with an overhand grip.","Curl the bar up toward your shoulders.","Lower under control.","Repeat."],"images":{"start":"images/flat/reverse-curl-start.webp","peak":"images/flat/reverse-curl-peak.webp"}},{"id":"reverse-grip-bent-over-row","name":"Reverse Grip Bent Over Row","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Stand with feet shoulder-width apart and grip a barbell underhand.","Hinge forward at the hips with a slight knee bend.","Let the bar hang with your arms extended.","Pull the bar to your lower abdomen by driving your elbows back.","Squeeze your back at the top.","Lower the bar with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/reverse-grip-bent-over-row-start.webp","peak":"images/flat/reverse-grip-bent-over-row-peak.webp"}},{"id":"reverse-grip-lat-pulldown","name":"Reverse Grip Lat Pulldown","bodyPart":"back","category":"strength","equipment":"cable","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Attach a straight bar to a lat pulldown machine.","Grip the bar with an underhand grip, shoulder-width apart.","Sit and secure your thighs under the pad.","Pull the bar down to your upper chest.","Squeeze your lats and biceps at the bottom.","Return the bar to the starting position with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/reverse-grip-lat-pulldown-start.webp","peak":"images/flat/reverse-grip-lat-pulldown-peak.webp"}},{"id":"reverse-lunge","name":"Reverse Lunge","bodyPart":"upper_legs","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand holding dumbbells at your sides.","Step one leg back and lower your knee toward the floor.","Lower until your front thigh is parallel to the floor.","Push through your front heel to return to standing.","Repeat on both sides."],"images":{"start":"images/flat/reverse-lunge-start.webp","peak":"images/flat/reverse-lunge-peak.webp"}},{"id":"reverse-nordic-curl","name":"Reverse Nordic Curl","bodyPart":"upper_legs","category":"strength","muscles":["quadriceps"],"steps":["Kneel on a pad with your knees hip-width apart, shins and the tops of your feet on the floor, and your torso upright.","Keep your hips extended and core braced.","Slowly lean your torso backward while keeping your body in a straight line.","Lower as far as you can control with your quadriceps.","Pull yourself back up to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/reverse-nordic-curl-start.webp","peak":"images/flat/reverse-nordic-curl-peak.webp"}},{"id":"reverse-plank","name":"Reverse Plank","bodyPart":"core","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Sit on the floor with your legs extended in front of you.","Place your hands behind you with fingers pointing toward your feet.","Lift your hips off the floor to form a straight line from head to heels.","Squeeze your glutes and brace your core.","Hold the position for the desired duration.","Lower your hips with control to exit."],"images":{"main":"images/flat/reverse-plank-main.webp"}},{"id":"reverse-plank-dips","name":"Reverse Plank Dips","bodyPart":"upper_arms","category":"strength","muscles":["triceps_brachii"],"steps":["Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.","Press into the hands and heels and lift the hips into a straight-leg reverse plank.","Bend the elbows straight back and lower the hips a short way towards the floor.","Push back up until the arms lock out, keeping the hips high.","Repeat for the desired number of repetitions."],"images":{"start":"images/flat/reverse-plank-dips-start.webp","peak":"images/flat/reverse-plank-dips-peak.webp"}},{"id":"reverse-tabletop-hip-pulses","name":"Reverse Tabletop Hip Pulses","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Sit with the knees bent, the feet flat and the hands on the floor behind you.","Press into the hands and feet and lift the hips until the trunk is level with the knees.","Keeping the elbows straight, lower the hips a few centimetres.","Squeeze the glutes to lift them back to level.","Pulse for the desired number of repetitions and lower down."],"images":{"start":"images/flat/reverse-tabletop-hip-pulses-start.webp","peak":"images/flat/reverse-tabletop-hip-pulses-peak.webp"}},{"id":"reverse-tabletop-hold","name":"Reverse Tabletop Hold","bodyPart":"core","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.","Press into the hands and feet and lift the hips until the trunk is level with the knees.","Open the chest, draw the shoulders away from the ears and look straight ahead.","Hold the position for the prescribed time with the hips high.","Lower the hips under control to finish."],"images":{"main":"images/flat/reverse-tabletop-hold-main.webp"}},{"id":"revolved-chair-pose","name":"Revolved Chair Pose","bodyPart":"core","category":"strength","muscles":["obliques","quadriceps"],"steps":["Set up in chair pose with the knees bent, the hips back and the palms together at the chest.","Keep the knees level with each other so the hips do not open into the twist.","Rotate the chest to one side and hook the opposite elbow outside that thigh.","Press the palms together and hold for the prescribed time, lengthening the spine on each inhale.","Come back to centre and repeat on the other side."],"images":{"main":"images/flat/revolved-chair-pose-main.webp"}},{"id":"revolved-crescent-lunge","name":"Revolved Crescent Lunge","bodyPart":"core","category":"strength","muscles":["obliques","quadriceps"],"steps":["Step into a high lunge with the front knee over the ankle and the back heel lifted.","Bring the palms together at the chest and square both hips towards the front of the mat.","Rotate the chest towards the front leg and hook the opposite elbow outside the thigh.","Hold the twist for the prescribed time, pressing the back heel towards the wall behind you.","Unwind and repeat on the other side."],"images":{"main":"images/flat/revolved-crescent-lunge-main.webp"}},{"id":"ring-dead-hang","name":"Ring Dead Hang","bodyPart":"back","category":"strength","equipment":"rings","muscles":["forearm_flexors"],"steps":["Grip a pair of gymnastic rings with a neutral grip, palms facing each other.","Hang with your arms fully extended and feet off the ground.","Let the rings rotate naturally; do not fight the grip.","Keep your shoulders engaged (no shrug to the ears) and core lightly braced.","Hold for the desired duration."],"images":{"main":"images/flat/ring-dead-hang-main.webp"}},{"id":"ring-dips","name":"Ring Dips","bodyPart":"chest","category":"strength","equipment":"rings","muscles":["pectoralis_major","triceps_brachii"],"steps":["Support yourself on the rings with arms locked out.","Lower your body by bending the elbows until upper arms are parallel to the ground.","Press back up to the starting position.","Repeat."],"images":{"start":"images/flat/ring-dips-start.webp","peak":"images/flat/ring-dips-peak.webp"}},{"id":"ring-face-pull","name":"Ring Face Pull","bodyPart":"back","category":"strength","equipment":"rings","muscles":["posterior_deltoid","rhomboids"],"steps":["Grip the rings and lean back so your body is at an angle.","Pull the rings toward your face, flaring elbows to the sides.","Hold briefly, then return.","Repeat."],"images":{"start":"images/flat/ring-face-pull-start.webp","peak":"images/flat/ring-face-pull-peak.webp"}},{"id":"ring-l-sit","name":"Ring L-Sit","bodyPart":"core","category":"strength","equipment":"rings","muscles":["hip_flexors","rectus_abdominis"],"steps":["Set the rings at about hip height and grip them with the arms straight beside the body.","Press down on the rings and lift the body into the support position, with the shoulders pushed down and away from the ears.","Turn the rings out slightly, brace the abdominals and raise the straight legs until they are parallel to the floor.","Hold the position, keeping the rings steady and the knees locked.","Lower the legs, then the body, under control."],"images":{"main":"images/flat/ring-l-sit-main.webp"}},{"id":"ring-muscle-up","name":"Ring Muscle-Up","bodyPart":"back","category":"strength","equipment":"rings","muscles":["latissimus_dorsi","pectoralis_major","triceps_brachii"],"steps":["Hang from the rings with a false grip, palms facing each other.","Pull explosively, driving the chest up to the rings.","Transition the elbows over the rings as the chest rises.","Press to full arm extension at the top.","Lower under control through the transition back to the hang."],"images":{"start":"images/flat/ring-muscle-up-start.webp","peak":"images/flat/ring-muscle-up-peak.webp"}},{"id":"ring-plank","name":"Ring Plank","bodyPart":"core","category":"strength","equipment":"rings","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Set the rings at about knee height and take hold of them with the arms straight under the shoulders.","Step the feet back into a plank, with the body in a straight line from head to heels.","Brace the abdominals and glutes and press the rings down and slightly out to keep them steady.","Hold the position without letting the hips sag or the rings drift apart.","Step the feet in and stand up to finish."],"images":{"main":"images/flat/ring-plank-main.webp"}},{"id":"ring-push-up","name":"Ring Push-Up","bodyPart":"chest","category":"strength","equipment":"rings","muscles":["pectoralis_major","triceps_brachii"],"steps":["Set the rings just above floor height.","Grip the rings and assume a plank position with arms straight.","Lower the chest toward the rings, keeping the elbows close to the body.","Press back up to full arm extension.","Repeat for the prescribed reps."],"images":{"start":"images/flat/ring-push-up-start.webp","peak":"images/flat/ring-push-up-peak.webp"}},{"id":"ring-row","name":"Ring Row","bodyPart":"back","category":"strength","equipment":"rings","muscles":["latissimus_dorsi","rhomboids"],"steps":["Set the rings at hip to chest height.","Grip the rings with palms facing each other, lean back at an angle with arms straight.","Brace the core and pull the chest toward the rings.","Squeeze the shoulder blades together at the top.","Lower under control to a full-arm extension."],"images":{"start":"images/flat/ring-row-start.webp","peak":"images/flat/ring-row-peak.webp"}},{"id":"ring-support-hold","name":"Ring Support Hold","bodyPart":"chest","category":"strength","equipment":"rings","muscles":["pectoralis_major","triceps_brachii"],"steps":["Hang the rings at about hip height and take one ring in each hand, with your thumbs wrapped around the ring.","Press up so that your arms are straight and your body is lifted off the floor above the rings.","Turn your palms slightly outward so the rings sit beside your hips, with your elbows locked.","Push down on the rings and keep your shoulders away from your ears, with your chest lifted.","Squeeze your glutes and keep your legs together, with your feet pointed.","Hold the position for the planned time, then lower down under control."],"images":{"main":"images/flat/ring-support-hold-main.webp"}},{"id":"rings-inverted-row","name":"Rings Inverted Row","bodyPart":"back","category":"strength","equipment":"rings","muscles":["latissimus_dorsi","rhomboids","trapezius"],"steps":["Set the rings just above hip height.","Lie under the rings and grip them with palms facing each other.","Walk the feet forward so the body forms a straight line.","Pull the chest toward the rings, squeezing the shoulder blades.","Lower under control to a full-arm extension."],"images":{"start":"images/flat/rings-inverted-row-start.webp","peak":"images/flat/rings-inverted-row-peak.webp"}},{"id":"romanian-deadlift","name":"Romanian Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand holding a barbell at hip level with an overhand grip.","Hinge at the hips, pushing them back while keeping legs nearly straight.","Lower the bar along your legs until you feel a hamstring stretch.","Drive your hips forward to return to standing.","Repeat."],"images":{"start":"images/flat/romanian-deadlift-start.webp","peak":"images/flat/romanian-deadlift-peak.webp"}},{"id":"rope-climb","name":"Rope Climb","bodyPart":"back","category":"strength","equipment":"climbing_rope","muscles":["latissimus_dorsi"],"steps":["Grip the rope as high as you can with both hands.","Either wrap the rope around one foot (S-hook or J-hook) or pinch it between both feet.","Pull with your arms and bring your knees up, then clamp the rope with your feet and stand up on the foot lock.","Reach higher with one hand, then the other, release the feet, and clamp the rope again higher up.","Repeat until you reach the top of the rope.","Descend hand-under-hand with the feet controlling the speed — never slide."],"images":{"main":"images/flat/rope-climb-main.webp"}},{"id":"rowing-machine","name":"Rowing Machine","bodyPart":"full_body","category":"cardio","equipment":"rower","muscles":["latissimus_dorsi","quadriceps"],"steps":["Sit on the rower, strap your feet into the footplates and take the handle with an overhand grip.","Slide forward into the catch: shins vertical, torso leaning slightly ahead of the hips, arms straight out toward the flywheel.","Drive through your legs first, pushing the seat back until your knees are almost straight.","Swing your torso back past vertical, then pull the handle in to your lower ribs with your elbows travelling past your sides.","Reverse the order on the recovery — arms away, torso forward, then bend the knees — and slide back to the catch for the next stroke.","Continue for the desired time, distance or number of strokes."],"images":{"start":"images/flat/rowing-machine-start.webp","peak":"images/flat/rowing-machine-peak.webp"}},{"id":"running","name":"Running","bodyPart":"full_body","category":"cardio","muscles":["gastrocnemius","quadriceps"],"steps":["Start from an easy jog and build into your pace over the first few minutes rather than setting off at target speed.","Land with your foot under your hips, not out in front, and keep the contact with the ground short and quiet.","Run tall through the hips with a slight forward lean from the ankles, not a fold at the waist.","Bend your elbows to about ninety degrees and drive your arms forward and back, keeping them off your chest.","Breathe rhythmically and keep your shoulders, jaw and hands loose.","Hold the pace for the desired time or distance, then jog and walk for a few minutes to finish."],"images":{"main":"images/flat/running-main.webp"}},{"id":"russian-twist","name":"Russian Twist","bodyPart":"core","category":"strength","muscles":["obliques","rectus_abdominis"],"steps":["Sit on the floor with knees bent, lean back slightly.","Hold your hands together or hold a weight at chest level.","Rotate your torso to one side, then the other.","Keep your core braced throughout.","Repeat."],"images":{"start":"images/flat/russian-twist-start.webp","peak":"images/flat/russian-twist-peak.webp"}},{"id":"sandbag-carry","name":"Sandbag Carry","bodyPart":"full_body","category":"strength","equipment":"sandbag","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand over a sandbag, squat down and wrap both arms around it, with your hands or forearms locked together underneath it.","Lift the sandbag by standing up, and hold it tight against your chest.","Brace your trunk and keep your chest tall, with the bag high enough that it does not pull your shoulders forward.","Walk forward with short, controlled steps for the planned distance or time.","Keep squeezing the bag throughout the walk.","Lower the bag to the floor with a straight back by squatting down."],"images":{"main":"images/flat/sandbag-carry-main.webp"}},{"id":"savasana","name":"Corpse Pose","bodyPart":"full_body","category":"stretching","muscles":[],"steps":["Lie on your back with the legs a comfortable distance apart and the feet falling open.","Rest the arms slightly away from the body with the palms facing up.","Let the whole body soften into the floor, including the jaw, the eyes and the hands.","Stay for the prescribed time, breathing naturally without controlling the breath.","Bend the knees and roll to one side before sitting up slowly."],"images":{"main":"images/flat/savasana-main.webp"}},{"id":"scapular-pull-ups","name":"Scapular Pull Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi","trapezius"],"steps":["Hang from a pull-up bar with arms fully extended.","Keep your arms straight throughout the movement.","Depress and retract your shoulder blades to lift your chest.","Pause briefly at the top of the movement.","Return to a fully hanging position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/scapular-pull-ups-start.webp","peak":"images/flat/scapular-pull-ups-peak.webp"}},{"id":"scissor-kicks","name":"Scissor Kicks","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie flat on your back with your hands under your glutes.","Lift both legs a few inches off the floor.","Alternate crossing one leg over the other in a scissor motion.","Keep your lower back pressed into the floor.","Maintain a steady rhythm throughout.","Repeat for the desired number of reps."],"images":{"start":"images/flat/scissor-kicks-start.webp","peak":"images/flat/scissor-kicks-peak.webp"}},{"id":"seated-barbell-overhead-press","name":"Seated Barbell Overhead Press","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid"],"steps":["Set an upright bench inside a rack with the pins at about shoulder height when seated.","Sit with your back flat against the pad and unrack the barbell at the front of the shoulders.","Press the bar overhead until the arms are fully extended, tucking the head through at the top.","Lower the bar back to the collarbones under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/seated-barbell-overhead-press-start.webp","peak":"images/flat/seated-barbell-overhead-press-peak.webp"}},{"id":"seated-cable-row","name":"Seated Cable Row","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi","rhomboids"],"steps":["Sit at the cable row station and place your feet on the footrests.","Grip the handle and sit upright with a slight forward lean.","Drive your elbows back and pull the handle toward your lower abdomen.","Squeeze your shoulder blades together at the end of the pull.","Extend your arms under control back to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/seated-cable-row-start.webp","peak":"images/flat/seated-cable-row-peak.webp"}},{"id":"seated-calf-raise","name":"Seated Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"seated_calf_raise_machine","muscles":["soleus"],"steps":["Sit at a calf raise machine with the pads resting on your thighs.","Lower your heels as far as possible.","Raise up onto your toes.","Lower under control.","Repeat."],"images":{"start":"images/flat/seated-calf-raise-start.webp","peak":"images/flat/seated-calf-raise-peak.webp"}},{"id":"seated-db-press","name":"Seated Dumbbell Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Sit on a bench with back support, holding dumbbells at shoulder height.","Press the dumbbells overhead until arms are fully extended.","Lower the dumbbells back to shoulder level.","Repeat."],"images":{"start":"images/flat/seated-db-press-start.webp","peak":"images/flat/seated-db-press-peak.webp"}},{"id":"seated-dip-machine","name":"Seated Dip Machine","bodyPart":"upper_arms","category":"strength","equipment":"dip_machine","muscles":["triceps_brachii"],"steps":["Select your weight on the stack and adjust the seat so the handles are at about shoulder height when you are seated.","Sit upright with your back against the pad and grip the handles at your sides with your elbows bent.","Keep your shoulders down and your chest up, then press the handles down by straightening your elbows.","Squeeze your triceps at the bottom, with your arms straight but not locked out hard.","Let the handles rise back up under control until your elbows are bent to about 90 degrees.","Repeat for the planned repetitions, keeping your back against the pad."],"images":{"start":"images/flat/seated-dip-machine-start.webp","peak":"images/flat/seated-dip-machine-peak.webp"}},{"id":"seated-dumbbell-curl","name":"Seated Dumbbell Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Sit on a bench with a dumbbell in each hand.","Let your arms hang at your sides with palms facing forward.","Curl both dumbbells toward your shoulders by flexing your biceps.","Squeeze at the top of the movement.","Lower the dumbbells with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/seated-dumbbell-curl-start.webp","peak":"images/flat/seated-dumbbell-curl-peak.webp"}},{"id":"seated-dumbbell-lateral-raise","name":"Seated Dumbbell Lateral Raise","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["lateral_deltoid"],"steps":["Sit on a bench with a dumbbell in each hand at your sides.","Keep your back upright and core braced.","Raise both dumbbells out to the sides until they reach shoulder height.","Keep a slight bend in your elbows.","Lower the dumbbells with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/seated-dumbbell-lateral-raise-start.webp","peak":"images/flat/seated-dumbbell-lateral-raise-peak.webp"}},{"id":"seated-dumbbell-tricep-extension","name":"Seated Dumbbell Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Sit on a bench with a dumbbell held overhead in both hands.","Keep your upper arms vertical next to your ears.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms to press the dumbbell back overhead.","Squeeze your triceps at the top.","Repeat for the desired number of reps."],"images":{"start":"images/flat/seated-dumbbell-tricep-extension-start.webp","peak":"images/flat/seated-dumbbell-tricep-extension-peak.webp"}},{"id":"seated-forward-fold","name":"Seated Forward Fold","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings"],"steps":["Sit on the floor with both legs straight out in front.","Keep your back long and hinge forward from the hips.","Reach your hands toward your feet.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/seated-forward-fold-main.webp"}},{"id":"seated-leg-curl","name":"Seated Leg Curl","bodyPart":"upper_legs","category":"strength","equipment":"leg_curl","muscles":["hamstrings"],"steps":["Adjust the seat back and ankle pad so your knees align with the machine's pivot point.","Sit upright, place the backs of your ankles on top of the pad, and grip the handles.","Curl your lower legs down and back under the seat as far as the machine allows.","Pause at peak contraction, then return the weight slowly to the starting position.","Repeat for the desired reps."],"images":{"start":"images/flat/seated-leg-curl-start.webp","peak":"images/flat/seated-leg-curl-peak.webp"}},{"id":"seated-smith-machine-shoulder-press","name":"Seated Smith Machine Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"smith_machine","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Position a bench inside a Smith machine.","Sit facing forward with the bar at shoulder height.","Grip the bar slightly wider than shoulder-width.","Unrack and press the bar straight up until your arms are extended.","Lower the bar back to shoulder height with control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/seated-smith-machine-shoulder-press-start.webp","peak":"images/flat/seated-smith-machine-shoulder-press-peak.webp"}},{"id":"seated-spinal-twist","name":"Seated Spinal Twist","bodyPart":"back","category":"stretching","muscles":["erector_spinae","obliques"],"steps":["Sit with one leg straight and cross the other foot over it.","Brace the opposite elbow against the outside of the bent knee.","Rotate your torso toward the bent knee and look over your shoulder.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/seated-spinal-twist-main.webp"}},{"id":"seated-straddle-stretch","name":"Seated Straddle Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["adductors","hamstrings"],"steps":["Sit with your legs straight and spread wide in a V.","Keep your back long and hinge forward from the hips.","Walk your hands forward along the floor.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/seated-straddle-stretch-main.webp"}},{"id":"shrimp-squat","name":"Shrimp Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand on one leg, bend the other knee and hold that foot behind you with the same-side hand.","Hold your arms and chest steady and begin to bend the standing knee, sitting your hips down and slightly back.","Lower until the back knee lightly touches the floor behind the standing foot.","Keep your chest up and your standing heel on the floor throughout the descent.","Press through the whole standing foot and straighten that leg to return to standing without letting go of the rear foot.","Complete the planned repetitions, then repeat on the other leg."],"images":{"start":"images/flat/shrimp-squat-start.webp","peak":"images/flat/shrimp-squat-peak.webp"}},{"id":"shrug","name":"Barbell Shrug","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["trapezius"],"steps":["Stand holding a barbell at arm's length with an overhand grip.","Shrug your shoulders straight up toward your ears.","Hold briefly at the top.","Lower your shoulders back down with control.","Repeat."],"images":{"start":"images/flat/shrug-start.webp","peak":"images/flat/shrug-peak.webp"}},{"id":"side-lunge","name":"Side Lunge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet hip-width apart and hands at your chest.","Step one leg wide to the side, keeping the other leg straight.","Bend the stepping knee and push your hips back into a lateral squat.","Keep your chest up and the working heel planted.","Drive through the bent leg to return to standing.","Complete reps on one side, then switch."],"images":{"start":"images/flat/side-lunge-start.webp","peak":"images/flat/side-lunge-peak.webp"}},{"id":"side-lying-hip-abduction","name":"Side-Lying Hip Abduction","bodyPart":"upper_legs","category":"strength","muscles":["abductors","gluteus_medius"],"steps":["Lie on your side with legs stacked.","Keep the bottom leg slightly bent.","Raise the top leg toward the ceiling.","Lower under control.","Repeat on both sides."],"images":{"start":"images/flat/side-lying-hip-abduction-start.webp","peak":"images/flat/side-lying-hip-abduction-peak.webp"}},{"id":"side-lying-hip-abduction-hold","name":"Side-Lying Hip Abduction Hold","bodyPart":"upper_legs","category":"strength","muscles":["abductors","gluteus_medius"],"steps":["Lie on one side with the legs stacked and straight, and support the head on the lower arm.","Brace the trunk so the torso stays square and does not roll backwards.","Lift the top leg to about 30 to 45 degrees, keeping the toes pointing forward.","Hold the leg there for the prescribed time, breathing normally.","Lower the leg under control and repeat on the other side."],"images":{"main":"images/flat/side-lying-hip-abduction-hold-main.webp"}},{"id":"side-lying-hip-adduction","name":"Side Lying Hip Adduction","bodyPart":"upper_legs","category":"strength","muscles":["adductors"],"steps":["Lie on your side with your bottom leg straight.","Bend your top leg and place its foot flat in front of the bottom thigh.","Support your head with your bottom arm.","Lift the bottom leg upward toward the ceiling.","Lower the leg back down under control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/side-lying-hip-adduction-start.webp","peak":"images/flat/side-lying-hip-adduction-peak.webp"}},{"id":"side-lying-hip-adduction-hold","name":"Side-Lying Hip Adduction Hold","bodyPart":"upper_legs","category":"strength","muscles":["adductors"],"steps":["Lie on one side with the bottom leg straight and the top leg crossed over it, foot flat on the floor.","Support the head on the lower arm and keep the hips stacked vertically.","Lift the bottom leg as high as it will go with the knee straight and the toes pointing forward.","Hold that lifted position for the prescribed time without rolling the hips back.","Lower the leg under control and repeat on the other side."],"images":{"main":"images/flat/side-lying-hip-adduction-hold-main.webp"}},{"id":"side-lying-lateral-raise","name":"Side-Lying Lateral Raise","bodyPart":"shoulders","category":"strength","equipment":"dumbbell","muscles":["lateral_deltoid"],"steps":["Lie on your side on a flat bench with your bottom arm supporting your head or gripping the bench edge.","Hold a dumbbell in your top hand with your arm resting along your side.","Keeping your elbow slightly bent, raise the dumbbell upward until your arm is perpendicular to the floor.","Pause briefly at the top, then lower the dumbbell slowly back to your side.","Complete all reps on one side before switching."],"images":{"start":"images/flat/side-lying-lateral-raise-start.webp","peak":"images/flat/side-lying-lateral-raise-peak.webp"}},{"id":"side-plank","name":"Side Plank","bodyPart":"core","category":"strength","muscles":["obliques","transverse_abdominis"],"steps":["Lie on your side with your forearm on the floor, elbow under your shoulder.","Lift your hips off the floor, forming a straight line from head to feet.","Hold the position, keeping your core tight.","Breathe steadily.","Repeat on both sides."],"images":{"main":"images/flat/side-plank-main.webp"}},{"id":"side-plank-leg-lift","name":"Side Plank with Leg Lift","bodyPart":"core","category":"strength","muscles":["gluteus_medius","obliques"],"steps":["Lie on your side with the forearm on the floor, elbow under the shoulder.","Stack the feet and lift the hips into a side plank.","From this stable side plank, raise the top leg straight up toward the ceiling.","Lower the leg back down with control without dropping the hips.","Complete reps on one side, then switch."],"images":{"start":"images/flat/side-plank-leg-lift-start.webp","peak":"images/flat/side-plank-leg-lift-peak.webp"}},{"id":"side-plank-leg-lift-hold","name":"Side Plank Leg Lift Hold","bodyPart":"core","category":"strength","muscles":["gluteus_medius","obliques"],"steps":["Set up in a side plank on the forearm with the elbow under the shoulder and the feet stacked.","Lift the hips until the body forms a straight line from the ankles to the head.","Raise the top leg to roughly hip height, keeping the toes pointing forward.","Hold the position for the prescribed time, keeping the hips high and the supporting shoulder stacked over the elbow.","Lower the leg and the hips under control and repeat on the other side."],"images":{"main":"images/flat/side-plank-leg-lift-hold-main.webp"}},{"id":"single-arm-chest-supported-dumbbell-row","name":"Single-Arm Chest-Supported Dumbbell Row","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Lie face-down on an incline bench holding a dumbbell in one hand, arm hanging straight down.","Row the dumbbell up to your side, driving your elbow past your torso.","Squeeze your shoulder blade at the top, then lower under control.","Complete all reps on one side before switching arms."],"images":{"start":"images/flat/single-arm-chest-supported-dumbbell-row-start.webp","peak":"images/flat/single-arm-chest-supported-dumbbell-row-peak.webp"}},{"id":"single-arm-db-row","name":"Single-Arm Dumbbell Row","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Place one knee and hand on a bench for support.","Hold a dumbbell in the other hand with arm extended.","Pull the dumbbell up toward your hip, squeezing your shoulder blade.","Lower the dumbbell with control.","Repeat on both sides."],"images":{"start":"images/flat/single-arm-db-row-start.webp","peak":"images/flat/single-arm-db-row-peak.webp"}},{"id":"single-arm-dumbbell-bench-press","name":"Single Arm Dumbbell Bench Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major","triceps_brachii"],"steps":["Lie back on a flat bench with the feet planted on the floor and a dumbbell held at chest level in one hand.","Rest the free hand on your stomach or hold it out to the side for balance.","Press the dumbbell up over the chest until the arm is straight.","Pause briefly at the top without letting the body roll toward the pressing arm.","Lower the dumbbell slowly to the side of the chest.","Complete the repetitions on one side, then switch arms."],"images":{"start":"images/flat/single-arm-dumbbell-bench-press-start.webp","peak":"images/flat/single-arm-dumbbell-bench-press-peak.webp"}},{"id":"single-arm-dumbbell-overhead-tricep-extension","name":"Single-Arm Dumbbell Overhead Tricep Extension","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Stand or sit holding a dumbbell in one hand overhead, arm fully extended.","The palm faces forward; the other hand can hold your waist or an upright for stability.","Bend the elbow to lower the dumbbell behind the head in a controlled arc.","Keep the upper arm vertical and close to the head throughout.","Extend the elbow to return the dumbbell overhead.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/single-arm-dumbbell-overhead-tricep-extension-start.webp","peak":"images/flat/single-arm-dumbbell-overhead-tricep-extension-peak.webp"}},{"id":"single-arm-hammer-curl","name":"Single-Arm Hammer Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["brachialis","brachioradialis"],"steps":["Stand with your feet about hip-width apart and hold one dumbbell at your side with the palm facing inward.","Brace your trunk and keep the working upper arm beside your ribs as the arm hangs straight.","Curl the dumbbell toward your shoulder without rotating the palm or swinging the torso.","Squeeze the elbow flexors at the top, then lower the dumbbell under control until the arm is straight.","Complete the repetitions on one side, then switch arms and repeat."],"images":{"start":"images/flat/single-arm-hammer-curl-start.webp","peak":"images/flat/single-arm-hammer-curl-peak.webp"}},{"id":"single-arm-machine-shoulder-press","name":"Single-Arm Machine Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"shoulder_press_machine","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Adjust the seat so the working handle starts around shoulder height and sit with your back firmly against the pad.","Grip one handle with the wrist straight and keep the free hand on the support or resting comfortably.","Press the handle upward without leaning away from the back pad or rotating the torso.","Lower the handle under control until the elbow is just below the starting line, then repeat.","Complete the repetitions on one side, adjust the seat if needed, and train the other side."],"images":{"start":"images/flat/single-arm-machine-shoulder-press-start.webp","peak":"images/flat/single-arm-machine-shoulder-press-peak.webp"}},{"id":"single-arm-plank","name":"Single-Arm Plank","bodyPart":"core","category":"strength","muscles":["obliques","rectus_abdominis","transverse_abdominis"],"steps":["Set up in a high plank with your hands under your shoulders and your feet a little wider than hip-width.","Brace your trunk and squeeze your glutes to keep your body in one straight line.","Shift your weight onto one arm and lift the other hand off the floor, resting it on your hip or behind your back.","Keep your hips and shoulders level and square to the floor.","Hold for the planned time, then replace the hand and rest.","Repeat on the other arm."],"images":{"main":"images/flat/single-arm-plank-main.webp"}},{"id":"single-arm-plate-loaded-lateral-raise","name":"Single-Arm Plate-Loaded Lateral Raise","bodyPart":"shoulders","category":"strength","equipment":"plate_loaded_lateral_raise_machine","muscles":["lateral_deltoid"],"steps":["Set the seat height so the pad pivot lines up with your shoulder, and load only the side you are about to work.","Sit with your back flat against the pad and place the outside of your working upper arm against its pad.","Hold the handle on the free side or rest that hand in your lap, and keep your torso square to the seat.","Push the working arm out and up against the pad until the upper arm is level with your shoulder, then lower it under control.","Complete all the repetitions on that side, then load and work the other side."],"images":{"start":"images/flat/single-arm-plate-loaded-lateral-raise-start.webp","peak":"images/flat/single-arm-plate-loaded-lateral-raise-peak.webp"}},{"id":"single-arm-tricep-pushdown","name":"Single Arm Tricep Pushdown","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["triceps_brachii"],"steps":["Attach a single handle to a high cable pulley.","Grasp the handle with one hand and keep your elbow pinned to your side.","Press the handle down until your arm is fully extended.","Squeeze the triceps at the bottom.","Slowly return to the start position.","Complete reps on one side, then switch."],"images":{"start":"images/flat/single-arm-tricep-pushdown-start.webp","peak":"images/flat/single-arm-tricep-pushdown-peak.webp"}},{"id":"single-db-svend-press","name":"Single Dumbbell Svend Press","bodyPart":"chest","category":"strength","equipment":"dumbbell","muscles":["pectoralis_major"],"steps":["Stand tall and hold a single dumbbell upright in front of your sternum, the handle running vertically between your flat palms.","Squeeze your palms hard into the dumbbell so the chest takes the tension and the weight cannot slip.","Press the dumbbell straight forward until your arms are almost straight, keeping it at chest height the whole way out.","Pause briefly without letting the squeeze go, then draw the dumbbell back to your chest under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/single-db-svend-press-start.webp","peak":"images/flat/single-db-svend-press-peak.webp"}},{"id":"single-leg-box-squat","name":"Single-Leg Box Squat","bodyPart":"upper_legs","category":"strength","equipment":"plyo_box","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in front of a sturdy box or bench that is about knee height, with your back to it.","Shift your weight onto one leg and lift the other leg out in front of you, with your arms stretched forward for balance.","Push your hips back and bend the standing knee, lowering yourself under control toward the box.","Sit lightly on the box without dropping onto it, keeping your chest up and the free leg off the floor.","Press through the whole standing foot and straighten that leg to stand up again.","Complete the planned repetitions, then repeat on the other leg."],"images":{"start":"images/flat/single-leg-box-squat-start.webp","peak":"images/flat/single-leg-box-squat-peak.webp"}},{"id":"single-leg-calf-raise","name":"Single Leg Calf Raise","bodyPart":"lower_legs","category":"strength","muscles":["gastrocnemius"],"steps":["Stand on one foot on the floor and lift the other foot off the ground, knee bent.","Keep the arms relaxed at your sides and brace your core to hold your balance.","Drive up onto the ball of the foot as high as possible.","Lower the heel back to the floor under control.","Complete all reps on one side, then switch."],"images":{"start":"images/flat/single-leg-calf-raise-start.webp","peak":"images/flat/single-leg-calf-raise-peak.webp"}},{"id":"single-leg-extension","name":"Single Leg Extension","bodyPart":"upper_legs","category":"strength","equipment":"leg_extension","muscles":["quadriceps"],"steps":["Sit on a leg extension machine and place one foot under the pad.","Rest the other foot on the floor or let it hang.","Extend the working leg until it is nearly straight.","Squeeze the quadriceps at the top.","Lower the leg back down under control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/single-leg-extension-start.webp","peak":"images/flat/single-leg-extension-peak.webp"}},{"id":"single-leg-glute-bridge","name":"Single Leg Glute Bridge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Lie on your back with one knee bent, foot flat, the other leg extended straight.","Brace the core and squeeze the glute on the working side.","Drive the hips up by pressing through the working heel.","Pause at the top with the body in a straight line from shoulders to knee.","Lower under control. Complete reps per side, then switch."],"images":{"start":"images/flat/single-leg-glute-bridge-start.webp","peak":"images/flat/single-leg-glute-bridge-peak.webp"}},{"id":"single-leg-glute-bridge-hold","name":"Single-Leg Glute Bridge Hold","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus"],"steps":["Lie on your back with one knee bent and that foot flat, and lift the other leg so the thigh is roughly vertical.","Push through the heel of the planted foot and lift the hips until the body is straight from the knee to the shoulders.","Level the pelvis so the lifted side does not drop, and tuck the ribs down.","Hold the top position for the prescribed time, keeping the lifted knee still.","Lower the hips under control and repeat on the other side."],"images":{"main":"images/flat/single-leg-glute-bridge-hold-main.webp"}},{"id":"single-leg-hip-thrust","name":"Single-Leg Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"flat_bench","muscles":["gluteus_maximus"],"steps":["Sit on the floor with your back to a flat bench and rest your upper back against its edge, just below your shoulder blades.","Plant both feet flat on the floor with your knees bent, then lift one knee toward your chest and keep it there.","Keep your chin tucked toward your chest and your arms resting along the bench.","Drive through the heel of the planted foot and push your hips up until your body is level from your shoulders to your knee.","Squeeze your glute at the top without arching your lower back, then lower your hips under control.","Complete the planned repetitions, then switch legs."],"images":{"start":"images/flat/single-leg-hip-thrust-start.webp","peak":"images/flat/single-leg-hip-thrust-peak.webp"}},{"id":"single-leg-hip-thrust-hold","name":"Single-Leg Hip Thrust Hold","bodyPart":"upper_legs","category":"strength","equipment":"flat_bench","muscles":["gluteus_maximus"],"steps":["Sit on the floor with your back to a flat bench and rest your upper back against its edge, just below your shoulder blades.","Plant both feet flat on the floor with your knees bent, then lift one knee toward your chest.","Keep the other foot planted under that knee and your chin tucked toward your chest.","Drive through the planted heel and push your hips up until your body is flat from shoulders to knee.","Keep your ribs down and hold the top position for the planned time.","Lower your hips under control and repeat on the other leg."],"images":{"main":"images/flat/single-leg-hip-thrust-hold-main.webp"}},{"id":"single-leg-lying-leg-curl","name":"Single Leg Lying Leg Curl","bodyPart":"upper_legs","category":"strength","equipment":"leg_curl","muscles":["hamstrings"],"steps":["Lie face down on a lying leg curl machine.","Position one ankle under the pad, keeping the other foot off the machine.","Curl the working leg by bringing your heel toward your glute.","Squeeze the hamstring at the top.","Lower the leg back down under control.","Complete reps on one side, then switch."],"images":{"start":"images/flat/single-leg-lying-leg-curl-start.webp","peak":"images/flat/single-leg-lying-leg-curl-peak.webp"}},{"id":"single-leg-press","name":"Single Leg Press","bodyPart":"upper_legs","category":"strength","equipment":"leg_press","muscles":["gluteus_maximus","quadriceps"],"steps":["Sit in a leg press machine with one foot placed on the platform.","Keep the other leg off the platform, resting to the side.","Release the safeties and lower the platform by bending your knee.","Stop when your knee is near a 90-degree angle.","Drive through the heel to press the platform back up.","Complete reps on one side, then switch."],"images":{"start":"images/flat/single-leg-press-start.webp","peak":"images/flat/single-leg-press-peak.webp"}},{"id":"single-leg-rdl-hold","name":"Single Leg RDL Hold","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on one leg with a slight bend in the knee and the arms hanging in front of you.","Hinge at the hip, sending the free leg straight back as the torso tips forward.","Keep the back flat and the hips square to the floor.","Stop when the torso and the free leg are roughly parallel to the floor and hold the position.","Return to standing under control, then switch legs."],"images":{"main":"images/flat/single-leg-rdl-hold-main.webp"}},{"id":"single-leg-romanian-deadlift","name":"Single Leg Romanian Deadlift","bodyPart":"back","category":"strength","equipment":"dumbbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on one leg holding a dumbbell in each hand in front of your thighs.","Keep a slight bend in the standing knee.","Hinge at the hip while extending the free leg behind you.","Lower the dumbbells along your standing leg until you feel a hamstring stretch.","Drive through the heel to return to upright.","Complete reps on one side, then switch."],"images":{"start":"images/flat/single-leg-romanian-deadlift-start.webp","peak":"images/flat/single-leg-romanian-deadlift-peak.webp"}},{"id":"sissy-squat","name":"Sissy Squat","bodyPart":"upper_legs","category":"strength","muscles":["quadriceps"],"steps":["Stand tall with your feet about hip-width apart and your arms stretched out in front of you for balance.","Rise onto the balls of your feet and keep your hips extended so that your body forms a straight line.","Bend your knees and let them travel forward and down while you lean your upper body back, keeping the line from knees to shoulders.","Lower until your knees are close to the floor, or as far as you can control.","Press through the front of your feet and push your knees back to straighten your legs and stand up again.","Complete the planned repetitions."],"images":{"start":"images/flat/sissy-squat-start.webp","peak":"images/flat/sissy-squat-peak.webp"}},{"id":"sit-ups","name":"Sit-Ups","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie on your back with knees bent and feet anchored.","Cross your arms over your chest or place hands behind your head.","Sit all the way up until your torso is upright.","Lower back down with control.","Repeat."],"images":{"start":"images/flat/sit-ups-start.webp","peak":"images/flat/sit-ups-peak.webp"}},{"id":"six-inch-hold","name":"Six Inch Hold","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie on your back with the legs straight and the arms resting along your sides.","Press the lower back into the floor and brace the abdominals.","Lift the head, shoulders and straight legs about six inches off the floor.","Hold the position while breathing steadily.","Lower slowly to rest."],"images":{"main":"images/flat/six-inch-hold-main.webp"}},{"id":"ski-erg","name":"SkiErg","bodyPart":"full_body","category":"cardio","equipment":"ski_erg","muscles":["latissimus_dorsi","rectus_abdominis","triceps_brachii"],"steps":["Stand facing the SkiErg with the handles overhead and the feet about hip-width apart.","Brace the trunk and drive the handles down by pulling with the lats while hinging slightly at the hips.","Finish with the hands beside the thighs and the knees softly bent.","Let the cords retract as you return the arms overhead and stand tall.","Repeat smoothly while keeping the heels planted and the torso controlled."],"images":{"start":"images/flat/ski-erg-start.webp","peak":"images/flat/ski-erg-peak.webp"}},{"id":"skull-crusher","name":"Skull Crusher","bodyPart":"upper_arms","category":"strength","equipment":"barbell","muscles":["triceps_brachii"],"steps":["Lie on a flat bench holding a barbell over your chest with a narrow grip.","Lower the bar toward your forehead by bending at the elbows.","Extend your arms back to the start.","Repeat."],"images":{"start":"images/flat/skull-crusher-start.webp","peak":"images/flat/skull-crusher-peak.webp"}},{"id":"sled-push","name":"Sled Push","bodyPart":"full_body","category":"strength","equipment":"sled","muscles":["gastrocnemius","gluteus_maximus","quadriceps"],"steps":["Load the sled and stand behind it, holding the uprights with your hands at about chest height.","Lean forward so your body forms a straight diagonal line from your head to your back heel, with your arms extended.","Brace your trunk and drive one knee forward, pushing the floor away with the ball of your back foot.","Keep taking short, powerful steps, driving each leg back hard to move the sled forward.","Keep your hips low and your back flat, and look a short distance ahead of the sled.","Push for the planned distance or time, then stop under control and rest before the next push."],"images":{"main":"images/flat/sled-push-main.webp"}},{"id":"sled-row","name":"Sled Row","bodyPart":"back","category":"strength","equipment":"sled","muscles":["latissimus_dorsi"],"steps":["Load a sled with two straps attached and take one strap handle in each hand.","Stand facing the sled with the arms extended and the torso leaned back slightly against the load.","Pull the sled toward you by driving the elbows back, and take a short step backwards as you do.","Extend the arms again, step back once more, and repeat the pull.","Continue for distance or time, keeping a steady pull-and-step rhythm."],"images":{"start":"images/flat/sled-row-start.webp","peak":"images/flat/sled-row-peak.webp"}},{"id":"smith-machine-bench-press","name":"Smith Machine Bench Press","bodyPart":"chest","category":"strength","equipment":"smith_machine","muscles":["pectoralis_major"],"steps":["Lie on a flat bench set inside a Smith machine.","Grip the bar slightly wider than shoulder-width and unrack it.","Lower the bar under control to your mid-chest.","Pause briefly without bouncing.","Press the bar back up until your arms are fully extended.","Repeat for the desired number of reps."],"images":{"start":"images/flat/smith-machine-bench-press-start.webp","peak":"images/flat/smith-machine-bench-press-peak.webp"}},{"id":"smith-machine-bent-over-row","name":"Smith Machine Bent Over Row","bodyPart":"back","category":"strength","equipment":"smith_machine","muscles":["latissimus_dorsi","rhomboids"],"steps":["Stand inside a Smith machine with feet shoulder-width apart.","Grip the bar with an overhand grip slightly wider than shoulders.","Hinge at the hips until your torso is roughly 45 degrees.","Pull the bar toward your lower chest by driving your elbows back.","Squeeze your shoulder blades at the top.","Lower the bar under control and repeat."],"images":{"start":"images/flat/smith-machine-bent-over-row-start.webp","peak":"images/flat/smith-machine-bent-over-row-peak.webp"}},{"id":"smith-machine-bulgarian-split","name":"Smith Machine Bulgarian Split Squat","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["gluteus_maximus","quadriceps"],"steps":["Set up a bench behind the Smith machine. Rest the bar on your traps.","Place the rear foot on the bench and front foot forward.","Lower your back knee toward the floor.","Push through the front heel to return.","Repeat on both sides."],"images":{"start":"images/flat/smith-machine-bulgarian-split-start.webp","peak":"images/flat/smith-machine-bulgarian-split-peak.webp"}},{"id":"smith-machine-calf-raise","name":"Smith Machine Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"smith_machine","muscles":["gastrocnemius"],"steps":["Stand in the Smith machine with your back to the bar, set just below hip height.","Reach back and grip the bar behind your thighs with both hands, arms straight.","Unrack the bar and raise up onto the balls of your feet.","Squeeze your calves hard at the top.","Lower your heels to the floor under control (below the edge if you stand on a low platform).","Repeat for the desired number of reps."],"images":{"start":"images/flat/smith-machine-calf-raise-start.webp","peak":"images/flat/smith-machine-calf-raise-peak.webp"}},{"id":"smith-machine-decline-bench-press","name":"Smith Machine Decline Bench Press","bodyPart":"chest","category":"strength","equipment":"smith_machine","muscles":["pectoralis_major"],"steps":["Set a decline bench in the machine so the bar lines up with your lower chest when you lie down, and hook your legs under the pads.","Lie back with your head at the low end, take an overhand grip slightly wider than your shoulders and unrack the bar.","Lower the bar under control until it touches your lower chest, keeping your elbows at roughly forty-five degrees from your torso.","Press the bar back up until your arms are extended, without locking the elbows out hard.","Repeat for the desired number of repetitions, then rack the bar before releasing your legs."],"images":{"start":"images/flat/smith-machine-decline-bench-press-start.webp","peak":"images/flat/smith-machine-decline-bench-press-peak.webp"}},{"id":"smith-machine-front-squat","name":"Smith Machine Front Squat","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["gluteus_maximus","quadriceps"],"steps":["Set the bar at upper-chest height and step under it so it rests across the front of your shoulders, against your collarbones.","Cross your arms over the bar or take an open front-rack grip, and drive your elbows up until your upper arms are close to parallel with the floor.","Unrack the bar and stand with your feet about shoulder-width apart and slightly forward of it.","Sit straight down, keeping your elbows high and your torso upright, until your thighs are at least parallel to the floor.","Drive through the middle of your feet to stand back up, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/smith-machine-front-squat-start.webp","peak":"images/flat/smith-machine-front-squat-peak.webp"}},{"id":"smith-machine-good-morning","name":"Smith Machine Good Morning","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["erector_spinae","hamstrings"],"steps":["Set the bar at upper-back height, step under it and settle it across your traps, then unrack it with your feet about hip-width apart.","Soften your knees slightly and keep them there -- this is a hinge, not a squat.","Push your hips straight back and let your torso tip forward, keeping your back flat and your head in line with your spine.","Stop when you feel a strong stretch in your hamstrings, with your torso somewhere near parallel to the floor.","Drive your hips forward to stand back up, squeezing the glutes at the top, and repeat for the desired reps."],"images":{"start":"images/flat/smith-machine-good-morning-start.webp","peak":"images/flat/smith-machine-good-morning-peak.webp"}},{"id":"smith-machine-hip-thrust","name":"Smith Machine Hip Thrust","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["gluteus_maximus","gluteus_medius"],"steps":["Set a flat bench inside the Smith machine, parallel to the bar and positioned so the bar will sit over your hip crease.","Set the bar low enough that you can get under it while seated on the floor, then sit with your upper back against the bench.","Slide your hips under the bar so it sits over your hip crease, pad it if you need to, and unhook it with your feet flat and about hip-width apart.","Drive through your heels and extend your hips until your thighs and torso form a straight line, squeezing the glutes at the top.","Lower your hips under control until they are just off the floor, and repeat for the desired number of repetitions."],"images":{"start":"images/flat/smith-machine-hip-thrust-start.webp","peak":"images/flat/smith-machine-hip-thrust-peak.webp"}},{"id":"smith-machine-incline-bench-press","name":"Smith Machine Incline Bench Press","bodyPart":"chest","category":"strength","equipment":"smith_machine","muscles":["anterior_deltoid","pectoralis_major"],"steps":["Set an incline bench at 30-45 degrees inside a Smith machine.","Lie back and grip the bar slightly wider than shoulder-width.","Unrack and lower the bar to your upper chest.","Pause briefly at the bottom.","Press the bar back up until your arms are extended.","Repeat for the desired number of reps."],"images":{"start":"images/flat/smith-machine-incline-bench-press-start.webp","peak":"images/flat/smith-machine-incline-bench-press-peak.webp"}},{"id":"smith-machine-rdl","name":"Smith Machine Romanian Deadlift","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["hamstrings"],"steps":["Set the Smith machine bar at mid-thigh height and stand facing it, feet hip-width, close enough that the bar touches your thighs.","Unrack the bar with an overhand grip just outside the hips.","Push the hips back while letting the bar slide down the front of the legs.","Go until you feel a deep hamstring stretch, with a flat back and a soft knee bend.","Drive the hips forward to return to standing, keeping the bar close to the body.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/smith-machine-rdl-start.webp","peak":"images/flat/smith-machine-rdl-peak.webp"}},{"id":"smith-machine-reverse-grip-bent-over-row","name":"Smith Machine Reverse Grip Bent Over Row","bodyPart":"back","category":"strength","equipment":"smith_machine","muscles":["biceps_brachii","latissimus_dorsi"],"steps":["Stand inside a Smith machine and grip the bar with an underhand grip.","Hinge forward at the hips until your torso is about 45 degrees.","Keep your back flat and core braced.","Pull the bar toward your lower abdomen.","Squeeze your lats and shoulder blades at the top.","Lower the bar under control and repeat."],"images":{"start":"images/flat/smith-machine-reverse-grip-bent-over-row-start.webp","peak":"images/flat/smith-machine-reverse-grip-bent-over-row-peak.webp"}},{"id":"smith-machine-reverse-lunge","name":"Smith Machine Reverse Lunge","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["gluteus_maximus","quadriceps"],"steps":["Set the bar so it sits across your upper traps when you stand, then unrack it with your feet under your hips.","Step one foot straight back and lower the rear knee toward the floor, keeping the front shin vertical and most of your weight on the front foot.","Stop when the rear knee is just short of the floor and the front thigh is roughly parallel to it.","Push through the front heel and bring the rear foot back to standing under the bar.","Complete all the repetitions on one side, then switch legs, or alternate legs on every repetition."],"images":{"start":"images/flat/smith-machine-reverse-lunge-start.webp","peak":"images/flat/smith-machine-reverse-lunge-peak.webp"}},{"id":"smith-machine-shoulder-press","name":"Smith Machine Shoulder Press","bodyPart":"shoulders","category":"strength","equipment":"smith_machine","muscles":["anterior_deltoid","lateral_deltoid"],"steps":["Stand inside a Smith machine with your feet hip-width apart and the bar at shoulder level.","Grip the bar slightly wider than shoulder-width at shoulder level.","Unrack the bar and press it overhead until your arms are extended.","Lower the bar back to shoulder level under control.","Keep your core tight throughout.","Repeat for the desired number of reps."],"images":{"start":"images/flat/smith-machine-shoulder-press-start.webp","peak":"images/flat/smith-machine-shoulder-press-peak.webp"}},{"id":"smith-machine-shrug","name":"Smith Machine Shrug","bodyPart":"back","category":"strength","equipment":"smith_machine","muscles":["trapezius"],"steps":["Stand upright inside a Smith machine with the bar at thigh height.","Grip the bar slightly wider than shoulder-width with an overhand grip.","Unrack the bar and let it hang in front of your thighs.","Shrug your shoulders straight up toward your ears.","Hold the top for a moment, then lower slowly.","Repeat for the desired number of reps."],"images":{"start":"images/flat/smith-machine-shrug-start.webp","peak":"images/flat/smith-machine-shrug-peak.webp"}},{"id":"smith-machine-split-squat","name":"Smith Machine Split Squat","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["gluteus_maximus","quadriceps"],"steps":["Set the bar on the hooks just below shoulder height, then step under it and rest it across your upper traps.","Unrack the bar and take a long stride forward with one foot, leaving the rear foot planted on the floor with the heel lifted.","Check that your front shin will stay roughly vertical when you descend; adjust the stride length before you start loading it.","Lower straight down by bending both knees until the rear knee is just above the floor and the front thigh is close to parallel.","Drive through the front heel to return to the start, keeping both feet in place, and repeat for the desired reps before switching sides."],"images":{"start":"images/flat/smith-machine-split-squat-start.webp","peak":"images/flat/smith-machine-split-squat-peak.webp"}},{"id":"smith-machine-squat","name":"Smith Machine Squat","bodyPart":"upper_legs","category":"strength","equipment":"smith_machine","muscles":["gluteus_maximus","quadriceps"],"steps":["Set the Smith machine bar at shoulder height and step under it.","Position the bar across your upper traps and unrack it.","Stand with feet shoulder-width apart, slightly forward of the bar.","Descend until your thighs are parallel to the floor.","Drive through your heels to return to standing.","Repeat for the desired number of reps."],"images":{"start":"images/flat/smith-machine-squat-start.webp","peak":"images/flat/smith-machine-squat-peak.webp"}},{"id":"smith-machine-upright-row","name":"Smith Machine Upright Row","bodyPart":"shoulders","category":"strength","equipment":"smith_machine","muscles":["lateral_deltoid","trapezius"],"steps":["Set the bar at hip height, take an overhand grip a little wider than shoulder-width and stand close to it with your arms straight.","Unrack the bar and stand tall with your shoulders back and your core braced.","Pull the bar straight up the front of your body, leading with your elbows and keeping the bar close.","Stop when the bar reaches your lower chest and your elbows are level with your shoulders, then pause briefly.","Lower the bar under control until your arms are straight again, and repeat for the desired reps."],"images":{"start":"images/flat/smith-machine-upright-row-start.webp","peak":"images/flat/smith-machine-upright-row-peak.webp"}},{"id":"snatch","name":"Snatch","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["gluteus_maximus","quadriceps","trapezius"],"steps":["Stand with feet hip-width apart and grip the bar wide.","Hinge down, keeping your back flat and chest up.","Explosively extend hips, knees, and ankles to drive the bar up.","Pull yourself under the bar into an overhead squat.","Stand up with the bar locked out overhead.","Return the bar to the floor and repeat."],"images":{"start":"images/flat/snatch-start.webp","peak":"images/flat/snatch-peak.webp"}},{"id":"sphinx-pose","name":"Sphinx Pose","bodyPart":"core","category":"stretching","muscles":["erector_spinae"],"steps":["Lie face down and place the forearms on the floor with the elbows directly under the shoulders.","Press the forearms and the tops of the feet down and lift the chest.","Draw the shoulders away from the ears and lengthen the back of the neck.","Hold the position for the prescribed time, breathing into the front of the chest.","Lower the chest to the floor and rest."],"images":{"main":"images/flat/sphinx-pose-main.webp"}},{"id":"spider-curl","name":"Spider Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Lie face down on an incline bench with arms hanging straight down.","Hold a dumbbell in each hand with an underhand grip.","Keep your upper arms vertical as you curl the weights up.","Squeeze the biceps hard at the top.","Lower the dumbbells under control to full extension.","Repeat for the desired number of reps."],"images":{"start":"images/flat/spider-curl-start.webp","peak":"images/flat/spider-curl-peak.webp"}},{"id":"spiderman-push-up","name":"Spiderman Push-Up","bodyPart":"chest","category":"strength","muscles":["pectoralis_major","triceps_brachii"],"steps":["Start in a high plank with the hands slightly wider than the shoulders and the body in a straight line.","Begin to lower the chest toward the floor and at the same time lift one foot off the floor.","Draw that knee out and up toward the elbow on the same side, keeping the hips low.","Press back up to the plank while returning the leg to the starting position.","Repeat on the other side and keep alternating."],"images":{"start":"images/flat/spiderman-push-up-start.webp","peak":"images/flat/spiderman-push-up-peak.webp"}},{"id":"split-jerk","name":"Split Jerk","bodyPart":"full_body","category":"olympic","equipment":"barbell","muscles":["anterior_deltoid","quadriceps"],"steps":["Hold the barbell across your front rack with elbows high.","Dip straight down by bending your knees slightly.","Explosively drive the bar overhead with your legs and arms.","Split your feet forward and back as the bar locks out.","Stand up by bringing your feet back together under the bar.","Lower the bar and repeat."],"images":{"start":"images/flat/split-jerk-start.webp","peak":"images/flat/split-jerk-peak.webp"}},{"id":"split-squat","name":"Split Squat","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand in a split stance with one foot forward and one back.","Keep your torso upright and core braced.","Lower your hips straight down by bending both knees.","Stop when the back knee is just above the floor.","Drive through the front heel to return to the start.","Complete reps on one side, then switch."],"images":{"start":"images/flat/split-squat-start.webp","peak":"images/flat/split-squat-peak.webp"}},{"id":"spoto-press","name":"Spoto Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Lie on a flat bench and grip the barbell slightly wider than shoulders.","Unrack the bar and hold it over your chest with arms extended.","Lower the bar until it is one inch above your chest.","Pause there for a full second without touching the chest.","Press the bar back up until your arms are extended.","Repeat for the desired number of reps."],"images":{"start":"images/flat/spoto-press-start.webp","peak":"images/flat/spoto-press-peak.webp"}},{"id":"squat","name":"Barbell Back Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Position the bar on your upper traps.","Unrack and step back, feet shoulder-width apart.","Brace your core and squat down until thighs are parallel.","Drive through your heels to stand back up.","Repeat."],"images":{"start":"images/flat/squat-start.webp","peak":"images/flat/squat-peak.webp"}},{"id":"squat-hold","name":"Squat Hold","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with the feet shoulder-width apart and the toes turned slightly out.","Reach the arms straight forward to counterbalance.","Squat down until the thighs are parallel to the floor, keeping the chest up and the heels down.","Hold the position, keeping the knees in line with the toes.","Stand up to finish."],"images":{"main":"images/flat/squat-hold-main.webp"}},{"id":"squat-pulse","name":"Squat Pulse","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with the feet about shoulder-width apart and the toes turned slightly out, arms reaching forward for balance.","Squat down until the thighs are at least parallel to the floor, keeping the chest up and the heels down.","From the bottom, rise only a short way, a few inches, then sink back down.","Keep pulsing in the lower range without locking out or resting at the top.","Stand up fully when the set is finished."],"images":{"start":"images/flat/squat-pulse-start.webp","peak":"images/flat/squat-pulse-peak.webp"}},{"id":"stability-ball-hip-bridge","name":"Stability Ball Hip Bridge","bodyPart":"upper_legs","category":"strength","equipment":"stability_ball","muscles":["gluteus_maximus"],"steps":["Lie face-up on the floor and place both feet on top of a stability ball.","Arms rest at the sides on the floor for balance.","Squeeze the glutes and press the heels into the ball to raise the hips.","Finish with a straight line from shoulders to knees.","Lower the hips under control without the ball rolling away.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/stability-ball-hip-bridge-start.webp","peak":"images/flat/stability-ball-hip-bridge-peak.webp"}},{"id":"stability-ball-knee-tuck","name":"Stability Ball Knee Tuck","bodyPart":"core","category":"strength","equipment":"stability_ball","muscles":["rectus_abdominis"],"steps":["Start in a high plank with both shins or the tops of the feet on top of a stability ball.","Hands are under the shoulders, body in a straight line.","Brace the core and pull the ball toward the chest by tucking the knees in.","Roll it back out by extending the legs fully back to the plank position.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/stability-ball-knee-tuck-start.webp","peak":"images/flat/stability-ball-knee-tuck-peak.webp"}},{"id":"stability-ball-push-up","name":"Stability Ball Push-Up","bodyPart":"chest","category":"strength","equipment":"stability_ball","muscles":["pectoralis_major"],"steps":["Kneel in front of a stability ball and place your shins or feet on top of it.","Set the hands on the floor under the shoulders in a high-plank position.","Brace the core hard — the ball will want to roll sideways.","Lower the chest to the floor by bending the elbows.","Press back up to the starting position without letting the ball wobble.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/stability-ball-push-up-start.webp","peak":"images/flat/stability-ball-push-up-peak.webp"}},{"id":"stability-ball-push-up-hands-on-ball","name":"Stability Ball Push-Up (Hands on Ball)","bodyPart":"chest","category":"strength","equipment":"stability_ball","muscles":["pectoralis_major"],"steps":["Place both hands on top of a stability ball and walk your feet back into a straight-arm plank, body in a straight line from head to heels.","Brace your core and keep the ball steady beneath your hands.","Bend your elbows to lower your chest toward the ball under control.","Press back up to full arm extension without letting the ball roll.","Repeat for the desired number of reps."],"images":{"start":"images/flat/stability-ball-push-up-hands-on-ball-start.webp","peak":"images/flat/stability-ball-push-up-hands-on-ball-peak.webp"}},{"id":"stability-ball-wall-squat","name":"Stability Ball Wall Squat","bodyPart":"upper_legs","category":"strength","equipment":"stability_ball","muscles":["gluteus_maximus","quadriceps"],"steps":["Place a stability ball between your lower back and a wall.","Step the feet forward about a foot, slightly wider than shoulder-width.","Squat down, letting the ball roll up the back as you descend.","Stop when thighs are parallel to the floor.","Drive through the heels to stand back up."],"images":{"start":"images/flat/stability-ball-wall-squat-start.webp","peak":"images/flat/stability-ball-wall-squat-peak.webp"}},{"id":"stair-climber","name":"Stair Climber","bodyPart":"upper_legs","category":"cardio","equipment":"stair_climber","muscles":["gluteus_maximus","quadriceps"],"steps":["Step onto the bottom stair with the machine at its slowest setting and take the rails lightly for balance.","Climb one step at a time, placing the whole foot on each stair rather than just the toes.","Stand upright with your chest open and your hips under your shoulders instead of hunching over the console.","Push the step down through the heel of the front foot, letting the glute of that leg do the work.","Set the pace so you can hold your posture, and keep climbing for the desired time or number of floors."],"images":{"main":"images/flat/stair-climber-main.webp"}},{"id":"standing-adductor-stretch","name":"Standing Adductor Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["adductors"],"steps":["Stand with your feet about twice shoulder-width apart and your toes pointing forward.","Put your hands on the bent knee or in front of you for support.","Bend one knee and shift your hips sideways over that leg, keeping the other leg straight.","Keep your chest up and both feet flat on the floor.","Sink down until you feel a stretch along the inner thigh of the straight leg and hold it.","Shift to the other side and repeat."],"images":{"main":"images/flat/standing-adductor-stretch-main.webp"}},{"id":"standing-calf-raise","name":"Standing Calf Raise","bodyPart":"lower_legs","category":"strength","equipment":"standing_calf_raise_machine","muscles":["gastrocnemius"],"steps":["Stand on the edge of a platform or calf raise machine.","Lower heels below the platform.","Push up onto your toes.","Lower slowly.","Repeat."],"images":{"start":"images/flat/standing-calf-raise-start.webp","peak":"images/flat/standing-calf-raise-peak.webp"}},{"id":"standing-calf-stretch","name":"Standing Calf Stretch","bodyPart":"lower_legs","category":"stretching","muscles":["gastrocnemius"],"steps":["Step one foot back into a staggered stance.","Keep the back leg straight and the heel pressed down.","Bend the front knee and lean your weight forward.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/standing-calf-stretch-main.webp"}},{"id":"standing-forward-fold","name":"Standing Forward Fold","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings"],"steps":["Stand tall with your feet hip-width apart and legs straight.","Hinge at your hips and fold your torso down toward the floor.","Let your hands and head hang toward your feet.","Hold for 20 to 30 seconds, breathing steadily."],"images":{"main":"images/flat/standing-forward-fold-main.webp"}},{"id":"standing-forward-fold-to-half-lift","name":"Standing Forward Fold to Half Lift","bodyPart":"upper_legs","category":"stretching","muscles":["erector_spinae","hamstrings"],"steps":["Stand with the feet hip-width apart and fold forward from the hips.","Rest the hands on the shins, the floor or blocks.","Slide the hands up the shins and lift the chest until the back is flat and the spine is long.","Fold back down, letting the head and neck release.","Continue alternating between the two for the desired number of repetitions."],"images":{"start":"images/flat/standing-forward-fold-to-half-lift-start.webp","peak":"images/flat/standing-forward-fold-to-half-lift-peak.webp"}},{"id":"standing-hip-abduction","name":"Standing Hip Abduction","bodyPart":"upper_legs","category":"strength","muscles":["abductors","gluteus_medius"],"steps":["Stand tall with your hands on your hips and your feet close together.","Shift your weight onto one leg and keep that knee slightly bent.","Lift the other leg straight out to the side, keeping the toes pointing forward and your trunk upright.","Raise the leg only as high as you can without leaning your upper body away from it.","Lower the leg slowly back next to the standing foot.","Complete the planned repetitions, then repeat on the other leg."],"images":{"start":"images/flat/standing-hip-abduction-start.webp","peak":"images/flat/standing-hip-abduction-peak.webp"}},{"id":"standing-quad-stretch","name":"Standing Quad Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["quadriceps"],"steps":["Stand on one leg, holding a wall for balance if needed.","Bend the other knee and grab that ankle behind you.","Pull the heel toward your glute, keeping knees together.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/standing-quad-stretch-main.webp"}},{"id":"standing-side-bend","name":"Standing Side Bend","bodyPart":"core","category":"stretching","muscles":["obliques"],"steps":["Stand with feet hip-width and reach both arms overhead.","Clasp your hands and lengthen up tall.","Bend smoothly to one side in a long curve.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/standing-side-bend-main.webp"}},{"id":"standing-side-bend-flow","name":"Standing Side Bend Flow","bodyPart":"core","category":"stretching","muscles":["obliques"],"steps":["Stand with the feet hip-width apart and reach both arms overhead.","Bend the trunk to one side, keeping both feet planted and the hips level.","Return through the centre with the ribs stacked over the pelvis.","Bend to the other side in the same way.","Keep alternating for the desired number of repetitions."],"images":{"start":"images/flat/standing-side-bend-flow-start.webp","peak":"images/flat/standing-side-bend-flow-peak.webp"}},{"id":"standing-split","name":"Standing Split","bodyPart":"upper_legs","category":"stretching","muscles":["gluteus_maximus","hamstrings"],"steps":["From a forward fold, place both hands on the floor or on blocks beside the standing foot.","Shift the weight onto one leg and lift the other leg behind you.","Keep the standing leg straight and the hips as level as the lift allows.","Hold the position for the prescribed time, drawing the chest towards the standing shin.","Lower the lifted foot down and repeat on the other side."],"images":{"main":"images/flat/standing-split-main.webp"}},{"id":"stationary-bike","name":"Stationary Bike","bodyPart":"upper_legs","category":"cardio","equipment":"stationary_bike","muscles":["quadriceps"],"steps":["Set the saddle height so your knee stays slightly bent at the bottom of the pedal stroke, then sit down and place the balls of your feet on the pedals.","Take the handlebars with a relaxed grip and sit tall, with your back neutral and your shoulders down.","Push one pedal down and forward while the other rises, keeping the effort in your legs rather than pulling on the bars.","Keep pedalling in a smooth, even circle at a steady cadence, breathing in rhythm with the stroke.","Adjust the resistance to hold your target effort, and continue for the desired time or distance."],"images":{"main":"images/flat/stationary-bike-main.webp"}},{"id":"step-up-to-balance","name":"Step-Up to Balance","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing a low, stable step or bench and place one foot flat on top of it.","Press through the whole of the front foot and straighten that leg to lift your body onto the step.","As you rise, drive the other knee up in front of you until the thigh is about hip height.","Stand tall on the working leg and hold the knee-up position for a moment without leaning back.","Lower the free foot back to the floor under control, then step the working leg down as well.","Complete the planned repetitions on one leg, then switch to the other."],"images":{"start":"images/flat/step-up-to-balance-start.webp","peak":"images/flat/step-up-to-balance-peak.webp"}},{"id":"step-ups","name":"Step Ups","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing a sturdy box or bench.","Place one foot fully on the box surface.","Drive through that heel to lift your body onto the box.","Bring your trailing foot up to stand fully on the box.","Step back down leading with the same foot.","Alternate legs or complete all reps on one side before switching."],"images":{"start":"images/flat/step-ups-start.webp","peak":"images/flat/step-ups-peak.webp"}},{"id":"stiff-leg-deadlift","name":"Stiff Leg Deadlift","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand with feet hip-width apart and hinge at the hips, legs nearly straight, holding a barbell low in front of your shins with a flat back.","Keep your legs nearly straight with only a slight knee bend throughout.","Drive the hips forward and stand upright, the bar travelling along your legs.","Hinge at the hips again and lower the bar along your legs.","Go as low as your hamstring flexibility allows with a flat back.","Repeat for the desired number of reps."],"images":{"start":"images/flat/stiff-leg-deadlift-start.webp","peak":"images/flat/stiff-leg-deadlift-peak.webp"}},{"id":"straight-arm-pulldown","name":"Straight-Arm Pulldown","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi"],"steps":["Stand facing a cable machine with a straight bar attached to the high pulley.","With arms nearly straight, push the bar down in an arc toward your thighs.","Squeeze your lats at the bottom.","Slowly return the bar to the starting position.","Repeat."],"images":{"start":"images/flat/straight-arm-pulldown-start.webp","peak":"images/flat/straight-arm-pulldown-peak.webp"}},{"id":"straight-bar-cable-front-raise","name":"Straight-Bar Cable Front Raise","bodyPart":"shoulders","category":"strength","equipment":"cable","muscles":["anterior_deltoid"],"steps":["Attach a straight bar to a low cable pulley and stand facing away from the machine with the cable running forward past your legs.","Hold the bar with an overhand grip, hands about shoulder-width apart, arms hanging straight down in front of your thighs.","Keep the elbows almost straight and the core braced so the torso does not lean back.","Raise the bar forward in a smooth arc until it reaches shoulder height.","Lower it under control back to the thighs and repeat for the desired number of repetitions."],"images":{"start":"images/flat/straight-bar-cable-front-raise-start.webp","peak":"images/flat/straight-bar-cable-front-raise-peak.webp"}},{"id":"straight-bar-dips","name":"Straight Bar Dips","bodyPart":"chest","category":"strength","equipment":"pull_up_bar","muscles":["pectoralis_major"],"steps":["Grip a straight bar overhand, slightly wider than shoulder-width, and jump into a straight-arm support on top of it with the bar at your hips.","Lean your chest slightly forward and bend your elbows to lower yourself toward the bar, keeping the elbows pointing back.","Stop when the bar is close to your upper chest or at the deepest point you can control.","Press down through the bar to straighten your arms and return to the support position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/straight-bar-dips-start.webp","peak":"images/flat/straight-bar-dips-peak.webp"}},{"id":"strict-curl","name":"Strict Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Stand tall with a dumbbell in each hand, arms at your sides and palms facing forward.","Pin your elbows against your sides and brace your core so your torso cannot swing.","Curl both dumbbells up by bending only at the elbows.","Lower them under control until your arms are straight.","Repeat for the desired number of reps."],"images":{"start":"images/flat/strict-curl-start.webp","peak":"images/flat/strict-curl-peak.webp"}},{"id":"suitcase-carry","name":"Suitcase Carry","bodyPart":"core","category":"strength","equipment":"kettlebell","muscles":["forearm_flexors","obliques","quadratus_lumborum"],"steps":["Stand beside a single kettlebell or dumbbell with your feet under your hips.","Hinge at the hips, take the handle in one hand and stand up with the weight hanging at your side.","Pull that shoulder down and back, and brace as if you were about to be pushed sideways.","Walk forward with normal, even strides, keeping your torso upright and square rather than leaning away from the weight.","Keep the free arm relaxed at your side instead of sticking it out as a counterweight.","Carry for the desired distance or time, set the weight down under control, then repeat on the other side."],"images":{"main":"images/flat/suitcase-carry-main.webp"}},{"id":"sumo-deadlift","name":"Sumo Deadlift","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet wider than shoulder-width, toes pointed outward.","Grip the bar between your legs.","Brace your core and drive through your heels to stand.","Lower under control.","Repeat."],"images":{"start":"images/flat/sumo-deadlift-start.webp","peak":"images/flat/sumo-deadlift-peak.webp"}},{"id":"sumo-squat","name":"Sumo Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with feet wider than shoulder-width and toes turned out.","Hold a barbell across your upper back.","Brace your core and keep your chest up.","Bend at the hips and knees to lower into a deep squat.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],"images":{"start":"images/flat/sumo-squat-start.webp","peak":"images/flat/sumo-squat-peak.webp"}},{"id":"superman","name":"Superman","bodyPart":"back","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Lie face down with arms extended overhead.","Simultaneously lift your arms, chest, and legs off the floor.","Hold briefly at the top.","Lower under control.","Repeat."],"images":{"start":"images/flat/superman-start.webp","peak":"images/flat/superman-peak.webp"}},{"id":"supine-spinal-twist","name":"Supine Spinal Twist","bodyPart":"back","category":"stretching","muscles":["erector_spinae","obliques"],"steps":["Lie on your back and bend one knee toward your chest.","Guide that knee across your body toward the floor.","Stretch your arms out wide and turn your head away.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"images":{"main":"images/flat/supine-spinal-twist-main.webp"}},{"id":"supine-windshield-wipers","name":"Supine Windshield Wipers","bodyPart":"core","category":"strength","muscles":["obliques","rectus_abdominis"],"steps":["Lie on your back with the arms out to the sides and the knees bent over the hips.","Brace the trunk so the lower back does not lift off the floor.","Lower both legs together towards one side as far as the shoulders stay down.","Bring them back through the centre and lower to the other side.","Keep alternating for the desired number of repetitions."],"images":{"start":"images/flat/supine-windshield-wipers-start.webp","peak":"images/flat/supine-windshield-wipers-peak.webp"}},{"id":"supported-shoulderstand","name":"Supported Shoulderstand","bodyPart":"core","category":"strength","muscles":["erector_spinae","rectus_abdominis"],"steps":["Lie on your back, ideally with a folded blanket under the shoulders and the head off it.","Lift the legs overhead and support the lower back with both hands, elbows shoulder-width apart.","Walk the hands up the back and stack the hips over the shoulders until the body is vertical.","Hold the position for the prescribed time, keeping the head and neck completely still.","Lower the legs overhead and roll down slowly with the hands supporting the back."],"images":{"main":"images/flat/supported-shoulderstand-main.webp"}},{"id":"supported-single-leg-stand","name":"Supported Single-Leg Stand","bodyPart":"lower_legs","category":"strength","muscles":["gastrocnemius","gluteus_medius"],"steps":["Stand tall beside a sturdy chair, wall or rail and rest one hand lightly on it.","Shift your weight onto the leg nearer the support and keep that knee soft.","Lift the other knee in front of you until your thigh is about hip height.","Keep your chest tall, your hips level and your eyes on a fixed point ahead.","Hold the position for the planned time, using the support only as much as needed.","Lower the foot, rest briefly and repeat on the other leg."],"images":{"main":"images/flat/supported-single-leg-stand-main.webp"}},{"id":"svend-press","name":"Svend Press","bodyPart":"chest","category":"strength","equipment":"plates","muscles":["pectoralis_major"],"steps":["Stand upright holding a single weight plate (or two pressed together) between your palms at chest height.","Squeeze the plates hard to generate tension through the pecs.","Press the plates straight out in front of you until the arms are fully extended.","Pause briefly, keeping the squeeze, then return the plates to the chest.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/svend-press-start.webp","peak":"images/flat/svend-press-peak.webp"}},{"id":"t-bar-row","name":"T-Bar Row","bodyPart":"back","category":"strength","equipment":"barbell","muscles":["latissimus_dorsi","rhomboids"],"steps":["Straddle the loaded T-bar with feet shoulder-width apart.","Hinge at the hips until your torso is around 45 degrees.","Grip the handles and keep your back flat.","Pull the bar up toward your chest by driving your elbows back.","Squeeze your shoulder blades at the top.","Lower the bar under control and repeat."],"images":{"start":"images/flat/t-bar-row-start.webp","peak":"images/flat/t-bar-row-peak.webp"}},{"id":"tandem-stance","name":"Tandem Stance","bodyPart":"lower_legs","category":"strength","muscles":["gastrocnemius","soleus"],"steps":["Stand tall with your feet together and your arms out to the sides at shoulder height.","Step one foot forward and place it directly in front of the other, heel against toes.","Spread your weight evenly over both feet and keep your knees soft.","Look at a fixed point ahead of you and keep your hips and shoulders level.","Hold the position for the planned time, using your arms to correct small sways.","Swap the front foot and repeat."],"images":{"main":"images/flat/tandem-stance-main.webp"}},{"id":"thoracic-bridge","name":"Thoracic Bridge","bodyPart":"core","category":"strength","muscles":["erector_spinae","gluteus_maximus"],"steps":["Sit on the floor with knees bent and hands behind you, fingers pointing back.","Press through your hands and feet to lift your hips off the floor.","Continue pressing until your chest opens and your arms are extended.","Drop your head back and hold the position.","Breathe steadily while maintaining the bridge.","Lower back down under control."],"images":{"main":"images/flat/thoracic-bridge-main.webp"}},{"id":"thread-the-needle","name":"Thread the Needle","bodyPart":"back","category":"stretching","muscles":["posterior_deltoid","trapezius"],"steps":["Start on all fours with the hands under the shoulders and the knees under the hips.","Slide one arm underneath the body, palm facing up, until the shoulder and the side of the head rest on the mat.","Keep the hips stacked over the knees and walk the top hand forward or wrap it behind the back.","Hold the twist for the prescribed time, breathing into the upper back.","Press the top hand into the floor to come up and repeat on the other side."],"images":{"main":"images/flat/thread-the-needle-main.webp"}},{"id":"thread-the-needle-flow","name":"Thread the Needle Flow","bodyPart":"back","category":"stretching","muscles":["obliques","trapezius"],"steps":["Start on all fours with the hands under the shoulders and the knees under the hips.","Slide one arm under the body until the shoulder approaches the mat.","Reverse the motion and open that arm up towards the ceiling, following the hand with the eyes.","Return through the centre and repeat for the desired number of repetitions.","Change sides and repeat."],"images":{"start":"images/flat/thread-the-needle-flow-start.webp","peak":"images/flat/thread-the-needle-flow-peak.webp"}},{"id":"three-legged-dog","name":"Three-Legged Downward Dog","bodyPart":"shoulders","category":"strength","muscles":["anterior_deltoid","gluteus_maximus"],"steps":["Set up in downward dog with the hands shoulder-width apart and the hips high.","Press both hands evenly into the floor and shift the weight slightly forward.","Lift one leg behind you until it is in line with the spine, keeping both hip points level.","Hold the position for the prescribed time with the standing heel reaching down.","Lower the leg and repeat on the other side."],"images":{"main":"images/flat/three-legged-dog-main.webp"}},{"id":"thruster","name":"Thruster","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["anterior_deltoid","quadriceps"],"steps":["Hold a barbell in a front rack position with elbows high.","Stand with feet shoulder-width apart.","Squat down to parallel while keeping your torso upright.","Drive up out of the squat and press the bar overhead in one motion.","Lock out your arms at the top with the bar overhead.","Lower the bar back to the front rack and repeat."],"images":{"start":"images/flat/thruster-start.webp","peak":"images/flat/thruster-peak.webp"}},{"id":"toes-to-bar","name":"Toes to Bar","bodyPart":"core","category":"strength","equipment":"pull_up_bar","muscles":["hip_flexors","rectus_abdominis"],"steps":["Hang from a pull-up bar with an overhand grip, arms fully extended and body still.","Engage your lats and core to prevent swinging.","Raise your legs with straight knees, reaching your toes up toward the bar.","Touch the bar with your toes, then lower your legs under control.","Repeat for the desired reps."],"images":{"start":"images/flat/toes-to-bar-start.webp","peak":"images/flat/toes-to-bar-peak.webp"}},{"id":"torso-twists","name":"Torso Twists","bodyPart":"core","category":"stretching","muscles":["obliques","transverse_abdominis"],"steps":["Stand with the feet about shoulder-width apart and the knees softly bent.","Brace lightly and hold the hands together in front of the chest.","Rotate the rib cage to one side without shifting the feet.","Return through centre and rotate to the other side.","Continue alternating smoothly through a comfortable range."],"images":{"main":"images/flat/torso-twists-main.webp"}},{"id":"treadmill-running","name":"Treadmill Running","bodyPart":"full_body","category":"cardio","equipment":"treadmill","muscles":["gastrocnemius","quadriceps"],"steps":["Step onto the treadmill with a foot on each side rail, start the belt at a walking speed and step on once it is moving.","Build up to your running pace, landing under your hips rather than reaching out in front of you.","Run tall with your shoulders relaxed, your elbows bent at about ninety degrees and your arms swinging forward and back, not across your body.","Keep your eyes forward and stay in the middle of the belt instead of drifting back toward the rear roller.","Hold the pace for the desired time or distance, then slow the belt and walk for a few minutes before stepping off."],"images":{"main":"images/flat/treadmill-running-main.webp"}},{"id":"tree-pose","name":"Tree Pose","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_medius","quadriceps"],"steps":["Stand tall and shift the weight onto one foot.","Place the sole of the other foot on the inner calf or the inner thigh, avoiding the knee.","Press the foot and the leg into each other and level the hips.","Bring the hands to the chest or overhead and hold for the prescribed time.","Lower the foot and repeat on the other side."],"images":{"main":"images/flat/tree-pose-main.webp"}},{"id":"triangle-pose","name":"Triangle Pose","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings","obliques"],"steps":["Stand wide with the front foot turned out and the back foot angled slightly in.","Keep both legs straight and reach the front hand forward as the hips shift back.","Tilt sideways and bring the bottom hand to the shin, a block or the floor, top arm reaching up.","Hold the position for the prescribed time, turning the chest towards the ceiling.","Press into the feet to come up and repeat on the other side."],"images":{"main":"images/flat/triangle-pose-main.webp"}},{"id":"tricep-kickback","name":"Dumbbell Tricep Kickback","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["triceps_brachii"],"steps":["Hinge forward at the hips, holding a dumbbell in each hand with the elbows bent at 90 degrees.","Extend both arms straight back, squeezing the triceps.","Hold briefly at full extension.","Lower with control.","Repeat for the planned number of reps."],"images":{"start":"images/flat/tricep-kickback-start.webp","peak":"images/flat/tricep-kickback-peak.webp"}},{"id":"tricep-pushdown","name":"Cable Tricep Pushdown","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["triceps_brachii"],"steps":["Stand facing a cable machine with a straight bar attachment.","Grip the bar and pin your elbows to your sides.","Push the bar down until your arms are fully extended.","Slowly return to the starting position.","Repeat."],"images":{"start":"images/flat/tricep-pushdown-start.webp","peak":"images/flat/tricep-pushdown-peak.webp"}},{"id":"triceps-dip-hold-bars","name":"Triceps Dip Hold on Dip Bars","bodyPart":"upper_arms","category":"strength","equipment":"dip_station","muscles":["pectoralis_major","triceps_brachii"],"steps":["Grip the parallel bars of a dip station, press up and straighten your arms with your shoulders pushed down away from your ears.","Lean slightly forward, keep your legs together and cross your feet behind you if you want.","Lower yourself slowly by bending your elbows until your upper arms are about parallel to the floor.","Stop there and hold, with your elbows pointing back and your chest open.","Keep your shoulders down and your body steady while you hold for the planned time.","Press back up to straight arms and step down."],"images":{"main":"images/flat/triceps-dip-hold-bars-main.webp"}},{"id":"triceps-dip-hold-bench","name":"Triceps Dip Hold on Bench","bodyPart":"upper_arms","category":"strength","muscles":["triceps_brachii"],"steps":["Sit on the edge of a bench, place your hands next to your hips with your fingers pointing forward and walk your feet out so that your legs are straight.","Slide your hips off the bench and straighten your arms to hold your weight.","Lower your body by bending your elbows until they reach about 90 degrees, keeping your back close to the bench.","Stop there and hold, with your elbows pointing straight back and your chest open.","Keep your shoulders down and away from your ears while you hold for the planned time.","Press up to straight arms and sit back down."],"images":{"main":"images/flat/triceps-dip-hold-bench-main.webp"}},{"id":"trx-bicep-curl","name":"TRX Bicep Curl","bodyPart":"upper_arms","category":"strength","equipment":"suspension_trainer","muscles":["biceps_brachii"],"steps":["Adjust the suspension trainer straps to a medium length.","Stand facing the anchor point, grasp the handles with an underhand grip, and lean back until your arms are fully extended.","Keep your body straight and core engaged, pull your chest towards your hands by bending your elbows.","Squeeze your biceps at the top of the movement.","Slowly extend your arms back to the starting position, controlling the descent.","Maintain tension throughout the set."],"images":{"start":"images/flat/trx-bicep-curl-start.webp","peak":"images/flat/trx-bicep-curl-peak.webp"}},{"id":"trx-chest-press","name":"TRX Chest Press","bodyPart":"chest","category":"strength","equipment":"suspension_trainer","muscles":["pectoralis_major"],"steps":["Adjust the suspension trainer handles to mid-calf height.","Stand facing away from the anchor point, holding a handle in each hand, arms extended.","Lean forward into a plank position, keeping your body straight from head to heels.","Lower your chest towards your hands by bending your elbows, maintaining tension in the straps.","Press back up to the starting position, fully extending your arms and squeezing your chest."],"images":{"start":"images/flat/trx-chest-press-start.webp","peak":"images/flat/trx-chest-press-peak.webp"}},{"id":"trx-face-pull","name":"TRX Face Pull","bodyPart":"shoulders","category":"strength","equipment":"suspension_trainer","muscles":["posterior_deltoid","rhomboids"],"steps":["Grasp the TRX handles with an overhand grip, palms facing down.","Lean back until your arms are fully extended and your body forms a straight line.","Pull the handles towards your face, driving your elbows high and wide.","Squeeze your shoulder blades together at the peak contraction.","Slowly extend your arms back to the starting position with control."],"images":{"start":"images/flat/trx-face-pull-start.webp","peak":"images/flat/trx-face-pull-peak.webp"}},{"id":"trx-hamstring-curl","name":"TRX Hamstring Curl","bodyPart":"upper_legs","category":"strength","equipment":"suspension_trainer","muscles":["hamstrings"],"steps":["Lie on your back with heels in the suspension trainer cradles, knees bent at 90 degrees.","Lift your hips off the floor, creating a straight line from knees to shoulders.","Extend your legs forward, maintaining hip elevation and core tension.","Pull your heels back towards your glutes, contracting your hamstrings forcefully.","Control the movement, avoiding any drop in hip height throughout the set."],"images":{"start":"images/flat/trx-hamstring-curl-start.webp","peak":"images/flat/trx-hamstring-curl-peak.webp"}},{"id":"trx-lunge","name":"TRX Lunge","bodyPart":"upper_legs","category":"strength","equipment":"suspension_trainer","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing away from the anchor point with the suspension trainer straps behind you, hands on your hips or free for balance.","Place the top of one foot in the foot cradles and extend that leg behind you.","Brace your core and lower your body by bending the front knee, keeping your torso upright.","Descend until your front thigh is parallel to the floor or just below, maintaining tension on the suspension trainer.","Drive through your front heel to return to the starting position, extending the front leg.","Complete all reps on one side, then switch legs and repeat per side."],"images":{"start":"images/flat/trx-lunge-start.webp","peak":"images/flat/trx-lunge-peak.webp"}},{"id":"trx-pistol-squat","name":"TRX Pistol Squat","bodyPart":"upper_legs","category":"strength","equipment":"suspension_trainer","muscles":["gluteus_maximus","quadriceps"],"steps":["Anchor the suspension trainer and hold the handles with both hands, arms extended.","Stand tall, lift one leg straight out in front of you, keeping it off the ground.","Initiate the squat by pushing your hips back and bending the standing knee, lowering your body as deep as possible.","Keep your chest up, back straight, and use the TRX for balance and support as needed.","Drive through your heel to return to the starting position, extending the standing leg fully.","Complete all reps on one side before switching to the other."],"images":{"start":"images/flat/trx-pistol-squat-start.webp","peak":"images/flat/trx-pistol-squat-peak.webp"}},{"id":"trx-plank","name":"TRX Plank","bodyPart":"core","category":"strength","equipment":"suspension_trainer","muscles":["rectus_abdominis","transverse_abdominis"],"steps":["Place both feet in the TRX foot cradles.","Assume a forearm or high plank position on the floor.","Keep your body in a straight line from head to heels.","Brace your core and squeeze your glutes.","Hold the position for the desired time.","Lower your knees to exit safely."],"images":{"main":"images/flat/trx-plank-main.webp"}},{"id":"trx-row","name":"TRX Row","bodyPart":"back","category":"strength","equipment":"suspension_trainer","muscles":["latissimus_dorsi","rhomboids"],"steps":["Grasp the handles of a suspension trainer with a neutral grip, palms facing each other.","Lean back, extending your arms fully, keeping your body straight from head to heels.","Engage your core and pull your chest towards your hands, squeezing your shoulder blades together.","Pause briefly at the top, then slowly lower yourself back to the starting position with control.","Maintain a rigid body throughout the movement, avoiding any sagging in the hips."],"images":{"start":"images/flat/trx-row-start.webp","peak":"images/flat/trx-row-peak.webp"}},{"id":"trx-side-plank","name":"TRX Side Plank","bodyPart":"core","category":"strength","equipment":"suspension_trainer","muscles":["obliques","transverse_abdominis"],"steps":["Place both feet in the TRX foot cradles and lie on your side.","Prop up on your bottom forearm with your elbow under your shoulder.","Lift your hips so your body forms a straight line.","Stack your top foot over the bottom foot.","Hold the position while breathing steadily.","Lower and switch sides after the set."],"images":{"main":"images/flat/trx-side-plank-main.webp"}},{"id":"trx-squat","name":"TRX Squat","bodyPart":"upper_legs","category":"strength","equipment":"suspension_trainer","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing the anchor point, holding the handles with palms facing each other, arms extended.","Lean back slightly, keeping your body straight and core engaged, with feet shoulder-width apart.","Initiate the squat by pushing your hips back and bending your knees, lowering your body as if sitting in a chair.","Descend until your thighs are parallel to the floor or as deep as comfortable, maintaining tension on the straps.","Drive through your heels to return to the starting position, extending your hips and knees fully."],"images":{"start":"images/flat/trx-squat-start.webp","peak":"images/flat/trx-squat-peak.webp"}},{"id":"trx-tricep-extension","name":"TRX Triceps Extension","bodyPart":"upper_arms","category":"strength","equipment":"suspension_trainer","muscles":["triceps_brachii"],"steps":["Stand facing away from the anchor point, holding the TRX handles with an overhand grip, palms facing down.","Lean forward, extending your arms straight out in front of you at shoulder height, creating tension in the straps.","Keeping your elbows high and fixed, bend them to lower your body by letting your hands move towards your temples.","Extend your elbows forcefully to push your body back to the starting position, squeezing your triceps.","Maintain a rigid plank position throughout the movement, engaging your core and glutes."],"images":{"start":"images/flat/trx-tricep-extension-start.webp","peak":"images/flat/trx-tricep-extension-peak.webp"}},{"id":"trx-y-fly","name":"TRX Y-Fly","bodyPart":"shoulders","category":"strength","equipment":"suspension_trainer","muscles":["posterior_deltoid","trapezius"],"steps":["Stand facing the anchor point, holding the handles with an overhand grip, palms facing down.","Lean back, extending your arms straight in front of you, maintaining a plank position with your body.","Raise your arms up and out into a 'Y' overhead, pulling your shoulder blades together and down as your body rises toward the anchor.","Keep a slight, fixed bend in the elbows throughout and squeeze your shoulder blades at the top.","Slowly control the descent back to the starting position, resisting the pull of the straps."],"images":{"start":"images/flat/trx-y-fly-start.webp","peak":"images/flat/trx-y-fly-peak.webp"}},{"id":"upright-row","name":"Barbell Upright Row","bodyPart":"shoulders","category":"strength","equipment":"barbell","muscles":["lateral_deltoid","trapezius"],"steps":["Stand holding a barbell with a shoulder-width overhand grip.","Pull the bar straight up along your body toward your chin.","Lead with your elbows, keeping them above your hands.","Lower the bar with control.","Repeat."],"images":{"start":"images/flat/upright-row-start.webp","peak":"images/flat/upright-row-peak.webp"}},{"id":"upward-dog","name":"Upward-Facing Dog","bodyPart":"core","category":"stretching","muscles":["erector_spinae","triceps_brachii"],"steps":["Lie face down with the hands beside the lower ribs and the tops of the feet on the floor.","Press the hands down and straighten the arms, lifting the chest and then the thighs off the mat.","Draw the shoulders back and down and keep the neck long.","Hold the position for the prescribed time with only the hands and the tops of the feet on the floor.","Bend the arms and lower down under control."],"images":{"main":"images/flat/upward-dog-main.webp"}},{"id":"v-bar-lat-pulldown","name":"V-Bar Lat Pulldown","bodyPart":"back","category":"strength","equipment":"lat_pulldown_machine","muscles":["latissimus_dorsi"],"steps":["Attach a V-bar (double-D handle) to a lat pulldown cable.","Sit with the thighs secured under the pad and grip the handle, palms facing each other.","Begin with the arms fully extended overhead.","Pull the handle down to the sternum by driving the elbows down and slightly back.","Squeeze the lats at the bottom, then return slowly under control.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/v-bar-lat-pulldown-start.webp","peak":"images/flat/v-bar-lat-pulldown-peak.webp"}},{"id":"v-bar-tricep-pushdown","name":"V-Bar Tricep Pushdown","bodyPart":"upper_arms","category":"strength","equipment":"cable","muscles":["triceps_brachii"],"steps":["Attach a V-bar handle to a high cable pulley.","Stand facing the stack and grip the V-bar with both hands, palms down.","Start with the elbows tucked to the sides, forearms parallel to the floor.","Press the handle down until the arms are fully extended.","Squeeze the triceps, then return under control to the starting position.","Repeat for the recommended number of repetitions."],"images":{"start":"images/flat/v-bar-tricep-pushdown-start.webp","peak":"images/flat/v-bar-tricep-pushdown-peak.webp"}},{"id":"v-sit","name":"V-Sit","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the floor.","Reach your arms forward so your body forms a V shape.","Balance on your sit bones with core tight.","Hold the position while breathing steadily.","Lower your legs and torso to exit."],"images":{"main":"images/flat/v-sit-main.webp"}},{"id":"v-ups","name":"V Ups","bodyPart":"core","category":"strength","muscles":["hip_flexors","rectus_abdominis"],"steps":["Lie flat on your back with arms extended overhead and legs straight.","Simultaneously raise your legs and upper body toward each other.","Reach your hands toward your feet at the top, forming a V shape.","Keep your legs straight throughout the movement.","Lower both ends under control back to the floor.","Repeat for the desired number of reps."],"images":{"start":"images/flat/v-ups-start.webp","peak":"images/flat/v-ups-peak.webp"}},{"id":"walking","name":"Walking","bodyPart":"full_body","category":"cardio","muscles":["gastrocnemius","quadriceps"],"steps":["Stand tall with your weight over the middle of your feet and your shoulders relaxed, not pulled back.","Step forward and land on your heel, then roll through the foot and push off the ball and toes.","Keep at least one foot on the ground at all times — as soon as both leave the floor you are running, not walking.","Let your arms swing naturally from the shoulder, opposite arm to opposite leg, with the elbows softly bent.","Look ahead rather than down at your feet, and breathe through a steady, repeatable rhythm.","Continue for the desired time or distance, picking a pace at which you could still hold a conversation."],"images":{"main":"images/flat/walking-main.webp"}},{"id":"walking-lunge","name":"Walking Lunge","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand tall with feet hip-width apart and hands on hips.","Step one foot forward into a long lunge.","Lower until both knees are around 90 degrees.","Drive through the front heel and step the back foot forward.","Continue alternating legs as you walk forward.","Repeat for the desired number of reps."],"images":{"start":"images/flat/walking-lunge-start.webp","peak":"images/flat/walking-lunge-peak.webp"}},{"id":"wall-ball","name":"Wall Ball","bodyPart":"full_body","category":"strength","equipment":"wall_ball","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand facing a wall about an arm's length away, feet shoulder-width apart, holding the ball at your chest with both hands.","Keep your elbows under the ball and your chest up.","Squat down until your hips are at or below knee height, keeping your heels on the floor.","Drive up hard through your legs and hips and, as you rise, throw the ball up to the target with both arms.","Catch the ball at chest height as it comes down, letting your arms absorb it.","Go straight into the next squat with the catch and repeat for the planned repetitions."],"images":{"main":"images/flat/wall-ball-main.webp"}},{"id":"wall-hamstring-stretch","name":"Wall Hamstring Stretch","bodyPart":"upper_legs","category":"stretching","muscles":["hamstrings"],"steps":["Lie on your back on the floor next to a wall or an open doorway, with your hips close to the wall.","Raise one leg and rest the heel on the wall with the knee as straight as you can comfortably get it.","Keep the other leg flat on the floor and your lower back relaxed.","Shuffle your hips closer to the wall to increase the stretch, or move away to ease it.","Breathe slowly and hold for the planned time while the hamstring relaxes.","Lower the leg and repeat on the other side."],"images":{"main":"images/flat/wall-hamstring-stretch-main.webp"}},{"id":"wall-push-ups","name":"Wall Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Stand facing a wall and place your palms on it at shoulder height.","Step your feet back until your arms are fully extended.","Bend your elbows to bring your chest toward the wall.","Keep your body in a straight line throughout.","Press back to the starting position.","Repeat for the desired number of reps."],"images":{"start":"images/flat/wall-push-ups-start.webp","peak":"images/flat/wall-push-ups-peak.webp"}},{"id":"wall-sit","name":"Wall Sit","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Stand with back against a wall.","Slide down until thighs are parallel to the floor.","Hold the position.","Stand back up when done."],"images":{"main":"images/flat/wall-sit-main.webp"}},{"id":"warrior-one","name":"Warrior I","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","quadriceps"],"steps":["Step one foot back and turn it out about forty-five degrees, planting the whole sole.","Bend the front knee until it stacks over the ankle and keep the back leg straight.","Draw both hip points towards the front of the mat and lift the arms overhead.","Hold the position for the prescribed time with the ribs down and the chest lifted.","Step the feet together and repeat on the other side."],"images":{"main":"images/flat/warrior-one-main.webp"}},{"id":"warrior-three","name":"Warrior III","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_maximus","hamstrings"],"steps":["Stand on one leg with the knee soft and the hips level.","Hinge forward from the hips as the other leg lifts behind you.","Continue until the torso and the lifted leg are roughly parallel to the floor.","Reach the arms forward, back along the body or out to the sides, and hold for the prescribed time.","Lower the leg and repeat on the other side."],"images":{"main":"images/flat/warrior-three-main.webp"}},{"id":"warrior-two","name":"Warrior II","bodyPart":"upper_legs","category":"strength","muscles":["gluteus_medius","quadriceps"],"steps":["Stand wide with the front foot turned out ninety degrees and the back foot slightly in.","Bend the front knee until it stacks over the ankle and tracks towards the middle toes.","Open the hips and chest to the side and extend the arms parallel to the floor.","Hold the position for the prescribed time, gazing over the front hand.","Straighten the front leg and repeat on the other side."],"images":{"main":"images/flat/warrior-two-main.webp"}},{"id":"weighted-dips","name":"Weighted Dips","bodyPart":"chest","category":"strength","equipment":"dip_station","muscles":["pectoralis_major","triceps_brachii"],"steps":["Attach a plate to a dip belt around your waist so the weight hangs between your legs.","Grip the parallel dip bars and press yourself up to the top position with your arms locked out and your feet off the floor.","Lean your torso slightly forward and lower your body by bending your elbows until your shoulders are below them.","Press back up through your palms until your arms are locked out again, keeping the hanging plate from swinging.","Repeat for the desired number of reps."],"images":{"start":"images/flat/weighted-dips-start.webp","peak":"images/flat/weighted-dips-peak.webp"}},{"id":"weighted-pull-up","name":"Weighted Pull-Up","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Attach a plate to a dip belt around your waist so the weight hangs between your legs, or hold the load between your feet.","Grip the pull-up bar with an overhand grip slightly wider than shoulder-width and hang at full arm extension with your legs together.","Pull your elbows down and back to drive your chest toward the bar until your chin clears it.","Lower yourself under control back to the full dead hang, keeping tension on your lats and letting the weight settle before the next rep.","Repeat for the desired number of reps."],"images":{"start":"images/flat/weighted-pull-up-start.webp","peak":"images/flat/weighted-pull-up-peak.webp"}},{"id":"weighted-wall-crunch","name":"Weighted Wall Crunch","bodyPart":"core","category":"strength","equipment":"plates","muscles":["rectus_abdominis"],"steps":["Lie on your back and park your legs so your hips cannot help: brace your feet against a wall or a box, or hold your legs up with the knees bent.","Hold a weight against your chest with both hands -- a plate, a dumbbell, or a kettlebell all work.","Crunch up, lifting your shoulder blades off the floor.","Lower with control.","Repeat."],"images":{"start":"images/flat/weighted-wall-crunch-start.webp","peak":"images/flat/weighted-wall-crunch-peak.webp"}},{"id":"wide-grip-bench-press","name":"Wide-Grip Bench Press","bodyPart":"chest","category":"strength","equipment":"barbell","muscles":["pectoralis_major"],"steps":["Lie on a flat bench. Grip the barbell wider than shoulder-width.","Lower the bar to mid-chest.","Press back up to full extension.","Repeat."],"images":{"start":"images/flat/wide-grip-bench-press-start.webp","peak":"images/flat/wide-grip-bench-press-peak.webp"}},{"id":"wide-grip-pull-ups","name":"Wide Grip Pull Ups","bodyPart":"back","category":"strength","equipment":"pull_up_bar","muscles":["latissimus_dorsi"],"steps":["Grip the pull-up bar with an overhand grip wider than shoulder-width.","Hang with arms fully extended and core braced.","Pull your chest toward the bar by driving your elbows down.","Keep your shoulders pulled back as you rise.","Lower yourself under control to full extension.","Repeat for the desired number of reps."],"images":{"start":"images/flat/wide-grip-pull-ups-start.webp","peak":"images/flat/wide-grip-pull-ups-peak.webp"}},{"id":"wide-grip-push-ups","name":"Wide Grip Push Ups","bodyPart":"chest","category":"strength","muscles":["pectoralis_major"],"steps":["Start in a high plank with hands wider than shoulder-width.","Keep your body in a straight line from head to heels.","Lower your chest toward the floor by bending your elbows.","Keep your core braced and glutes engaged.","Press back up until your arms are extended.","Repeat for the desired number of reps."],"images":{"start":"images/flat/wide-grip-push-ups-start.webp","peak":"images/flat/wide-grip-push-ups-peak.webp"}},{"id":"wide-grip-seated-cable-row","name":"Wide Grip Seated Cable Row","bodyPart":"back","category":"strength","equipment":"cable","muscles":["latissimus_dorsi","rhomboids"],"steps":["Sit at a cable row station with feet on the platform.","Grip a wide bar with an overhand grip.","Pull the bar toward your upper abdomen, squeezing your shoulder blades.","Extend your arms back to the starting position with control.","Repeat."],"images":{"start":"images/flat/wide-grip-seated-cable-row-start.webp","peak":"images/flat/wide-grip-seated-cable-row-peak.webp"}},{"id":"wide-legged-forward-fold","name":"Wide-Legged Forward Fold","bodyPart":"upper_legs","category":"stretching","muscles":["adductors","hamstrings"],"steps":["Stand with the feet wide apart and the outer edges parallel.","Place the hands on the hips, lift the chest and hinge forward from the hip joints.","Bring the hands to the floor under the shoulders and let the head hang.","Hold the fold for the prescribed time, shifting the weight slightly into the balls of the feet.","Bring the hands back to the hips and come up with a flat back."],"images":{"main":"images/flat/wide-legged-forward-fold-main.webp"}},{"id":"wide-stance-leg-press","name":"Wide-Stance Leg Press","bodyPart":"upper_legs","category":"strength","equipment":"leg_press","muscles":["adductors"],"steps":["Set the back pad and seat so your lower back remains supported at the bottom of the repetition.","Place your feet wide on the platform with the toes turned out only as far as the knees can follow comfortably.","Lower the sled by bending the hips and knees while keeping the knees aligned with the toes and the feet flat.","Press through the whole foot and extend the hips and knees without forcing the knees into lockout.","Lower the sled under control and repeat for the desired number of repetitions."],"images":{"start":"images/flat/wide-stance-leg-press-start.webp","peak":"images/flat/wide-stance-leg-press-peak.webp"}},{"id":"worlds-greatest-stretch","name":"World's Greatest Stretch","bodyPart":"full_body","category":"stretching","muscles":["hamstrings","hip_flexors"],"steps":["Start in a push-up position with your hands under your shoulders and your body in a straight line.","Step one foot forward, outside the same-side hand, into a deep lunge and keep the back leg straight.","Keep the hand on the back-leg side planted under your shoulder and sink your hips toward the floor.","Rotate your chest toward the front leg, lifting the arm on that side up until it points at the ceiling, and follow your hand with your eyes.","Hold the open position for a breath, then lower your hand back to the floor.","Step back to the push-up position and repeat on the other side, alternating sides for the planned repetitions."],"images":{"start":"images/flat/worlds-greatest-stretch-start.webp","peak":"images/flat/worlds-greatest-stretch-peak.webp"}},{"id":"wrist-curl","name":"Bilateral Dumbbell Wrist Curl","bodyPart":"lower_arms","category":"strength","equipment":"dumbbell","muscles":["forearm_flexors"],"steps":["Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms up.","Let both dumbbells roll down to your fingertips.","Curl both dumbbells up by flexing your wrists.","Squeeze at the top, then lower under control.","Repeat for the desired number of reps."],"images":{"start":"images/flat/wrist-curl-start.webp","peak":"images/flat/wrist-curl-peak.webp"}},{"id":"wrist-roller","name":"Wrist Roller","bodyPart":"lower_arms","category":"strength","equipment":"wrist_roller","muscles":["forearm_extensors","forearm_flexors"],"steps":["Grip the wrist roller handle with your elbows bent at your sides and your forearms in front of you at waist height.","Let the weight hang from the cord.","Roll the handle forward with alternating wrist movements to wind the weight up.","Keep your elbows at your sides throughout.","Once fully wound, reverse the rotation to lower the weight.","Repeat for the desired number of reps."],"images":{"start":"images/flat/wrist-roller-start.webp","peak":"images/flat/wrist-roller-peak.webp"}},{"id":"zercher-squat","name":"Zercher Squat","bodyPart":"upper_legs","category":"strength","equipment":"barbell","muscles":["gluteus_maximus","quadriceps"],"steps":["Set a barbell in a rack at about waist height, step in and hook it into the crooks of the elbows, with the forearms crossed or the hands clasped in front of the chest.","Lift the bar out of the rack, step back and stand with the feet about shoulder-width apart.","Brace the core and keep the chest up and the elbows pressed together.","Squat down by bending the hips and knees until the thighs are at least parallel to the floor.","Drive through the middle of the feet to stand back up.","Repeat for the desired number of repetitions, then re-rack the bar."],"images":{"start":"images/flat/zercher-squat-start.webp","peak":"images/flat/zercher-squat-peak.webp"}},{"id":"zottman-curl","name":"Zottman Curl","bodyPart":"upper_arms","category":"strength","equipment":"dumbbell","muscles":["biceps_brachii"],"steps":["Stand with your feet about hip-width apart, arms extended at your sides, and a dumbbell in each hand with the palms facing forward.","Keep your upper arms beside your ribs and curl both dumbbells toward your shoulders without swinging the torso.","At the top, keep the elbows bent and rotate the forearms until the palms face down.","Lower the dumbbells slowly with the pronated grip until the arms are straight.","Turn the palms forward again at the bottom and repeat for the desired number of repetitions."],"images":{"start":"images/flat/zottman-curl-start.webp","peak":"images/flat/zottman-curl-peak.webp"}}];
